import{a as e}from"./jsx-runtime-Bzw2jH9X.js";var t=e({default:()=>n}),n=JSON.parse(`[{"id":"qa-1","status":"entwurf","clusterId":"A","werkstueckRef":"A.1.1","stufe":1,"question":"Welche Frage hilft dir am besten, die drei Vorschläge zu vergleichen, wenn keiner sofort widerlegt werden kann?","scenario":"Du kommst nach Hause und findest auf dem Küchentisch einen zerbrochenen Keks. Du lebst allein, die Wohnung ist abgeschlossen, nichts fehlt. Drei Leute haben Vorschläge: Eine Freundin vermutet eine leichte Erschütterung von der Straße, ein Bekannter einen heimlichen Besuch mit Zweitschlüssel, eine Kollegin ein Wesen, das durch ein Wurmloch kam.","options":["Welcher Vorschlag klingt am spannendsten und lässt sich am besten weitererzählen?","Welcher Vorschlag kommt mit den wenigsten neuen, unbewiesenen Annahmen aus?","Welcher Vorschlag wird von den meisten der drei Leute für richtig gehalten?","Welcher Vorschlag wäre am schwersten zu widerlegen, wenn man es versuchte?"],"correctIndex":1,"explanation":"Wenn mehrere Erklärungen den Befund erklären und keine widerlegt ist, ist die sparsamste die bessere Ausgangsbasis: die mit den wenigsten neuen, unbewiesenen Annahmen. Die Erschütterung braucht nur Bekanntes: Straße, Verkehr, Schwerkraft. Der heimliche Besuch braucht zusätzlich eine weitere Person, die hereinkommt, ein Motiv und einen Zweitschlüssel – lauter Annahmen, die du erst belegen müsstest. Das Wurmloch-Wesen braucht eine ganze Kaskade neuer Dinge, deren Existenz niemand belegt hat. Wie spannend eine Geschichte klingt, wie viele sie teilen oder wie schwer sie zu widerlegen ist, sagt nichts darüber, wie gut sie begründet ist. Das Rasiermesser beweist dabei nicht, dass die sparsame Erklärung stimmt; es sagt nur, womit man die Prüfung sinnvoll beginnt.","coreRule":"⚡ Sparsamkeitsprinzip: Bei gleich gut passenden Erklärungen beginne mit der, die die wenigsten unbewiesenen Annahmen braucht.","quote":"Welche neuen Welten muss ich erfinden, damit diese Erklärung wahr ist?","quoteLabel":"Prüffrage","beleg":"Werkstück A.1.1 Ockhams Rasiermesser, Abschnitte „Kernidee“, „Kontext & Tiefe“, „Anti-Denkmuster“ (Aktivierungs-Frage); Fußnote ga-ockham betrifft nur die Herkunft der Formel","kurz":"Wenn keiner der Vorschläge sofort widerlegt werden kann, beginnst du am besten mit dem, der am wenigsten Unbelegtes braucht. Die Erschütterung kommt mit Bekanntem aus. Spannung, Zustimmung oder Unwiderlegbarkeit sagen nichts über die Begründung.","prueffrage":"Welche der drei Ursachen hast du selbst schon einmal erlebt oder beobachtet, und welche kennst du nur aus Geschichten?","rueckmeldung":[{"option":0,"text":"Eine spannende Geschichte bleibt gut im Gedächtnis und lässt sich schön ausbauen. Wie gut sie den zerbrochenen Keks erklärt und wie viel sie dafür voraussetzt, sagt dieser Reiz aber nicht."},{"option":2,"text":"Die Meinung anderer kann ein Anlass sein, etwas genauer anzusehen. Ein Maßstab ist sie nicht: Wie viele einen Vorschlag für richtig halten, sagt nichts darüber, wie gut er begründet ist und wie viel Unbelegtes er voraussetzt."},{"option":3,"text":"Schwer widerlegbar zu sein, wirkt wie eine Stärke. Eine Erklärung, die sich gegen jede Prüfung abdichtet, sagt aber gerade deshalb wenig, etwa das Wurmloch-Wesen. Entscheidend ist, wie viel Unbelegtes ein Vorschlag voraussetzt."}],"familie":"sparsamste-erklaerung","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Baker, A.: Simplicity. Stanford Encyclopedia of Philosophy (überarb. 16.05.2022), Abschn. 1–2","oeffentlich":true,"url":"https://plato.stanford.edu/entries/simplicity/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Thorburn, W. M. (1918): The Myth of Occam's Razor. Mind 27(3), 345–353","oeffentlich":false,"doi":"10.1093/mind/XXVII.3.345"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"90ba7dcd37575947"}},{"id":"qa-2","status":"entwurf","clusterId":"A","werkstueckRef":"A.1.2","stufe":1,"question":"Was ist die vernünftigste Reaktion?","scenario":"Du schickst deiner Chefin am Vorabend der großen Präsentation einen Bericht, in den du viele Stunden investiert hast. Am Morgen ist dein Posteingang leer, und in der Präsentation fällt der Bericht mit keinem Wort. Eine Kollegin sagt: „Die ignoriert dich mit Absicht. Das ist Sabotage.“","options":["Das Schweigen als Zustimmung werten: Wer nichts kritisiert, hatte am Bericht nichts auszusetzen.","Taktisches Kalkül vermuten: Wer fremde Leistungen nicht nennt, will die eigene Wirkung vergrößern.","Annehmen, dass der Bericht schwach war, weil gute Arbeit in der Regel ausdrücklich erwähnt wird.","Zuerst eine harmlose Erklärung prüfen, bevor du Absicht unterstellst."],"correctIndex":3,"explanation":"Für Sabotage müssten gleich mehrere Dinge zusammenkommen: böse Absicht, geschickte Verstellung, ein aktiver Plan und die Bereitschaft, den Erfolg der Firma dafür zu riskieren. Für eine Panne genügt eine einzige, allgemein bekannte Annahme: Systeme fallen aus, und Menschen sind überlastet oder vergesslich. Da Chaos und Zufall im Alltag weit häufiger sind als kalkulierte Intrigen, ist die banale Erklärung die bessere Ausgangshypothese. Das ist keine Garantie, sondern ein Startpunkt: Ein kurzes Nachfragen oder Nachsehen klärt es meist schnell. Auch die anderen Deutungen (Zustimmung, Kalkül, schwacher Bericht) schließen aus einem einzigen mehrdeutigen Hinweis auf eine bestimmte Bedeutung, obwohl das Schweigen mit vielen Ursachen vereinbar ist.","coreRule":"⚡ Schreibe nicht der Bosheit zu, was Dummheit, Fahrlässigkeit oder Zufall hinreichend erklären.","quote":"Was wäre die unbösartigste, chaotischste oder dümmste mögliche Erklärung für dieses Ereignis?","quoteLabel":"Prüffrage:","beleg":"Werkstück A.1.2, Abschnitte „Der E-Mail-Affront“ und „Kontext & Tiefe“ (Hypothese A vs. B); Fußnote ga-hanlon betrifft nur die Herkunft des Namens.","kurz":"Ein leerer Posteingang und eine ausgelassene Erwähnung sind mit vielen Ursachen vereinbar. Die banale Erklärung wie Überlastung oder Panne braucht die wenigsten Annahmen und eignet sich als Startpunkt, den ein kurzes Nachfragen meist klärt.","prueffrage":"Was alles kann zwischen dem Abschicken am Vorabend und der Präsentation am Morgen schiefgegangen sein?","rueckmeldung":[{"option":0,"text":"Wer nichts sagt, hat manchmal tatsächlich nichts auszusetzen. Doch Schweigen kann ebenso Zeitmangel, einen technischen Ausfall oder Vergessen bedeuten, und von außen sieht das alles gleich aus. Daher ist die Zustimmung nicht belegt."},{"option":1,"text":"Dass jemand fremde Leistungen verschweigt, um selbst besser dazustehen, kommt vor. Dieses Kalkül verlangt aber wie Sabotage Absicht und Planung. Gewöhnliche Überlastung braucht weniger Annahmen und ist im Alltag häufiger."},{"option":2,"text":"Auch gute Arbeit bleibt oft unerwähnt, etwa weil die Zeit fehlt. Über die Qualität des Berichts ist nichts bekannt, nur dass eine Reaktion ausblieb. Aus diesem mehrdeutigen Signal lässt sich Schwäche nicht ableiten."}],"familie":"umstaende-vor-absicht","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Quote Investigator: Never Attribute to Malice That Which Is Adequately Explained by Stupidity (30.12.2016, aktual. 18.04.2025)","oeffentlich":true,"url":"https://quoteinvestigator.com/2016/12/30/not-malice/","abruf":"2026-10-12"},{"typ":"url","kurz":"Gilbert, D. T.; Malone, P. S. (1995): The Correspondence Bias. Psychological Bulletin 117(1), 21–38 (Autorenkopie, Harvard)","oeffentlich":true,"url":"https://dtg.sites.fas.harvard.edu/Gilbert%20%26%20Malone%20%28CORRESPONDENCE%20BIAS%29.pdf","seite":"21","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"99a7f738f677baa1"}},{"id":"qa-3","status":"entwurf","clusterId":"A","werkstueckRef":"A.3","stufe":2,"question":"Nach dem Gespräch mit einem Nachbarn bist du verblüfft: Du hast jeden Test vorgeschlagen, den du dir ausdenken konntest, und jedes Mal hat er eine neue Bedingung ergänzt. Was ist an seiner Behauptung am grundsätzlichsten problematisch?","options":["Die Behauptung stützt sich auf einen einzelnen Zeugen; mit mehr Garagen und Beobachtern ließe sich der Drache prüfen.","Die Behauptung ist so unwahrscheinlich, dass sie sich schon allein deshalb nicht ernsthaft prüfen lässt.","Der Begriff „Drache“ ist nicht genau genug festgelegt; mit einer klaren Begriffsbestimmung wäre die Aussage prüfbar.","Keine denkbare Beobachtung könnte sie widerlegen, denn jeder Test wird durch eine Zusatzbedingung abgewehrt."],"correctIndex":3,"explanation":"Eine Aussage ist nur dann wissenschaftlich oder rational wertvoll, wenn es eine denkbare Beobachtung gibt, die sie widerlegen könnte. Hier wird jeder Test durch eine nachgeschobene Bedingung entwertet, und am Ende ist die Behauptung von der Aussage „da ist gar kein Drache“ durch keine Messung mehr zu unterscheiden. Das ist etwas anderes als Falschsein: Eine falsche Aussage kann widerlegt werden, eine immunisierte Aussage sagt dagegen nichts über die Welt aus, weil sie nichts verbietet. Entscheidend ist also nicht, wie unwahrscheinlich eine Behauptung klingt, sondern ob sie ein echtes Risiko des Scheiterns trägt. Einsteins Vorhersage der Lichtablenkung an der Sonne (Sonnenfinsternis 1919) hätte scheitern können; genau das machte sie überprüfbar.","coreRule":"⚡ Prüfbar ist nur, was scheitern könnte: Frag immer, welche Beobachtung die Behauptung widerlegen würde.","quote":"„Now, what's the difference between an invisible, incorporeal, floating dragon who spits heatless fire and no dragon at all?“ Frei übersetzt: Was unterscheidet einen unsichtbaren, unkörperlichen, schwebenden Drachen, der Feuer ohne Hitze speit, von gar keinem Drachen?","quoteLabel":"Carl Sagan, The Demon-Haunted World, Kap. 10, S. 161 (Original):","scenario":"Ein Nachbar behauptet: „In meiner Garage lebt ein unsichtbarer, unhörbarer Drache, der hitzefreies Feuer speit.“ Du schlägst vor, Mehl auf den Boden zu streuen, um Fußspuren zu sehen. Er antwortet: „Der Drache schwebt.“ Du willst eine Infrarotkamera einsetzen. Er sagt: „Sein Feuer ist hitzefrei.“ Du willst Farbe versprühen, um die Umrisse zu zeigen. Er meint: „Er ist körperlos, die Farbe geht einfach durch ihn hindurch.“","beleg":"Szene frei nach Sagan, C. (1995/1996): The Demon-Haunted World, Kap. 10 „The Dragon in My Garage“ (Headline-Ausgabe 1997, S. 160–161); das Zitat steht dort wörtlich auf S. 161 (geprüft im Volltext, Calibre buecher-sachbuecher:9271, PDF-S. 173); die deutsche Fassung ist eine eigene Übersetzung. Werkstück A.3, Fußnoten ga-drache und ga-popper.","kurz":"Eine Behauptung, die jedes Testergebnis durch eine neue Bedingung abwehrt, verbietet nichts und lässt sich von „da ist kein Drache“ nicht unterscheiden. Der Fehler wäre, ihre Unwahrscheinlichkeit zu beklagen, statt zu fragen, ob sie überhaupt scheitern könnte.","prueffrage":"Wie viele Eigenschaften hatte der Drache zu Beginn, und wie viele kamen nach deinen Vorschlägen hinzu?","rueckmeldung":[{"option":0,"text":"Mehr Beobachter sind grundsätzlich besser als einer. Hier würden sie aber dasselbe erleben wie du: Jedes Ergebnis wird nachträglich wegerklärt. Das Problem liegt also nicht in der Zahl der Zeugen, sondern darin, dass keine Beobachtung zählen darf."},{"option":1,"text":"Dass die Behauptung sehr unwahrscheinlich ist, stimmt. Das macht sie aber nicht unprüfbar: Auch Unwahrscheinliches kann an Messungen scheitern. Hier liegt das Problem woanders, nämlich darin, dass nichts mehr scheitern kann."},{"option":2,"text":"Ein klar gefasster Begriff hilft beim Prüfen. Doch der Nachbar beschreibt seinen Drachen recht genau, nur ergänzt er nach jedem Vorschlag eine passende Eigenschaft. Auch eine präzise Definition würde er so wieder aushebeln."}],"familie":"widerlegung-benennen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Thornton, S.: Karl Popper. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/popper/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Sagan, C. (1995): The Demon-Haunted World. New York: Random House, Kap. 10 „The Dragon in My Garage“","oeffentlich":false}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"e21e967547ec4293"}},{"id":"qa-4","status":"entwurf","clusterId":"A","werkstueckRef":"A.4","stufe":1,"question":"Ein Kollege erzählt dir ernsthaft, in seiner Garage lebe ein unsichtbarer, lautloser und nicht messbarer Drache. Auf deine Skepsis antwortet er: „Dann beweis mir doch, dass es ihn nicht gibt!“ Was ist an dieser Forderung das eigentliche Problem?","options":["Er verlangt von dir den Nachweis einer Nicht-Existenz, obwohl er die Behauptung aufstellt und ihre Belege liefern müsste.","Er verlangt von dir eine Messung, die du ohne Spezialgeräte nicht durchführen kannst, und stellt damit unfaire technische Anforderungen.","Er verlangt von dir einen Beweis, obwohl eine Behauptung ohne Gegenbeweis erst einmal als vorläufig wahr gelten darf.","Er verlangt von dir einen Beweis, obwohl nur Fachleute mit Erfahrung in der Drachenforschung über die Frage urteilen können."],"correctIndex":0,"explanation":"Wer etwas behauptet, muss es belegen; der Zweifler muss das Gegenteil nicht beweisen. Die Nicht-Existenz solcher Dinge lässt sich ohnehin nicht nachweisen: Der unsichtbare Drache in der Garage und Russells Teekanne zwischen Erde und Mars sind Beispiele dafür. Würde die Beweislast beim Zweifler liegen, müsste man unendlich viele fantastische Behauptungen widerlegen, was unmöglich ist. Dass etwas nicht widerlegt wurde, ist kein Beleg dafür, dass es stimmt. Je außergewöhnlicher die Behauptung, desto stärker müssen die Belege sein.","coreRule":"⚡ Wer behauptet, muss belegen: Was ohne Beweis behauptet werden kann, kann auch ohne Beweis verworfen werden.","quote":"Außergewöhnliche Behauptungen erfordern außergewöhnliche Beweise.","quoteLabel":"Carl Sagan (nach Marcello Truzzi), frei übersetzt:","scenario":"","beleg":"Werkstück A.4: Kernidee, Kontext & Tiefe (Beweislast, Hitchens’ Rasiermesser, außergewöhnliche Behauptungen), Red Flags („Kannst du das Gegenteil beweisen?“). Der Satz „Extraordinary claims require extraordinary evidence“ wird Carl Sagan zugeschrieben, ähnlich Marcello Truzzi („extraordinary proof“); nachgewiesen in Prothero (2017), UFOs, Chemtrails, and Aliens, und Loxton/Prothero (2013), Abominable Science!, jeweils als Sagans bekannter Satz nach Truzzi (Volltext Calibre buecher-sachbuecher:8727 und :8869); die deutsche Fassung ist eine eigene Übersetzung.","kurz":"Wer etwas behauptet, muss es belegen. Den Zweifler zum Gegenbeweis aufzufordern, kehrt das um, zumal sich die Nicht-Existenz eines solchen Drachens ohnehin nicht nachweisen lässt. Was nicht widerlegt ist, ist deshalb noch nicht wahr.","prueffrage":"Wie viele andere unsichtbare Wesen in anderen Garagen müsstest du nach dieser Forderung ebenfalls widerlegen?","rueckmeldung":[{"option":1,"text":"Fehlende Ausrüstung scheint das Problem zu sein, weil wirklich nichts zu messen ist. Das liegt aber an der Behauptung selbst: Ein nicht messbarer Drache ließe sich auch mit den besten Geräten nicht prüfen. Entscheidend ist, wer die Belege schuldet."},{"option":2,"text":"Ohne Gegenbeweis scheint eine Behauptung erst einmal stehen zu bleiben. Dass etwas nicht widerlegt wurde, ist aber kein Beleg dafür, dass es stimmt. Sonst müsste man unendlich viele fantastische Behauptungen widerlegen, bevor man sie ablehnen darf."},{"option":3,"text":"Bei vielen Fragen brauchen Urteile tatsächlich Sachkenntnis. Hier gibt es aber keine Drachenforschung, deren Urteil man abwarten müsste. Das Problem liegt woanders: Der Kollege schiebt die Beweislast für seine eigene Behauptung auf dich."}],"familie":"beweislast-klaeren","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Dowden, B.: Fallacies. Internet Encyclopedia of Philosophy (Einträge „Appeal to Ignorance“, „Misplaced Burden of Proof“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Sagan, C. (1995): The Demon-Haunted World. New York: Random House, Kap. 10 „The Dragon in My Garage“","oeffentlich":false},{"typ":"literatur","kurz":"Russell, B. (1952): Is There a God? In: Collected Papers of Bertrand Russell, Bd. 11. London: Routledge 1997, 543–548","oeffentlich":false}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"908e114516e0e2e6"}},{"id":"qa-5","status":"entwurf","clusterId":"A","werkstueckRef":"A.7","stufe":3,"question":"Ein Routine-Test auf eine seltene Krankheit (1 von 10.000 Menschen betroffen) erkennt 99 % der Kranken und 99 % der Gesunden korrekt. Dein Ergebnis ist positiv, Symptome hast du keine. Ein Freund sagt: „Der Test ist zu 99 % genau, also bist du zu 99 % krank.“ Wie beurteilst du diese Schlussfolgerung?","options":["Sie stimmt: Bei einer Spezifität von 99 % ist ein positives Ergebnis fast immer richtig, auch bei einer so seltenen Krankheit.","Sie stimmt halb: Fehlalarme und echte Treffer gleichen sich bei einem so genauen Test ungefähr aus, also liegt die Wahrscheinlichkeit bei etwa 50 %.","Sie stimmt nicht: Unter den vielen Gesunden gibt es so viele Fehlalarme, dass sie die wenigen echten Fälle weit überwiegen; die Wahrscheinlichkeit liegt unter 1 %.","Sie stimmt nicht: Bei einem positiven Befund liegt die Wahrscheinlichkeit nur bei etwa 10 %, weil auf jeden echten Fall höchstens zehn Fehlalarme kommen."],"correctIndex":2,"explanation":"Rechne mit natürlichen Häufigkeiten: Bei 1 Million Menschen sind 100 krank, davon testen 99 positiv. Von den 999.900 Gesunden testen 1 % falsch positiv, das sind 9.999 Menschen. Unter den 10.098 positiven Ergebnissen sind also nur 99 echte Fälle, das sind etwa 0,98 %. Entscheidend ist die niedrige Basisrate der Krankheit: Sie lässt die Fehlalarme die echten Fälle weit überwiegen.","coreRule":"⚡ Verwechsle nie die Genauigkeit eines Tests mit der Wahrscheinlichkeit, dass du betroffen bist: Ohne die Ausgangshäufigkeit (Basisrate) lässt sich ein positives Ergebnis nicht deuten.","quote":"","quoteLabel":"","scenario":"","beleg":"Werkstück A.7 „Probabilistisches Denken“, Abschnitt „Kontext & Tiefe“ (Der Test des Arztes, Berechnung mit natürlichen Häufigkeiten)","kurz":"Der Test irrt bei 1 % der Gesunden, und Gesunde sind weit in der Überzahl. Unter 1 Million Getesteten stehen so rund 10.000 Fehlalarme nur 99 echten Fällen gegenüber, also knapp 1 %. Die Genauigkeit des Tests ist nicht die Wahrscheinlichkeit, krank zu sein.","prueffrage":"Wie viele von 1 Million getesteten Menschen würden positiv testen, ohne krank zu sein, und wie viele mit Krankheit?","rueckmeldung":[{"option":0,"text":"Die Spezifität von 99 % stimmt, und sie klingt nach einem verlässlichen Befund. Sie sagt aber nur, wie viele Gesunde richtig negativ testen. Bei so wenigen Kranken stammen dennoch fast alle positiven Ergebnisse von Gesunden."},{"option":1,"text":"Hohe Trefferquoten legen nahe, dass sich Fehler und Treffer aufwiegen. Weil Gesunde so viel zahlreicher sind, kommen aber rund 100 Fehlalarme auf einen echten Fall. Die Wahrscheinlichkeit liegt weit unter 50 %."},{"option":3,"text":"Dass die Fehlalarme überwiegen, stimmt. Das Verhältnis ist aber viel ungünstiger: Auf jeden echten Fall kommen rund hundert Fehlalarme, nicht zehn. Die Wahrscheinlichkeit liegt daher knapp unter 1 %, nicht bei 10 %."}],"familie":"basisrate-beachten","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Gigerenzer, G. u. a. (2007): Helping Doctors and Patients Make Sense of Health Statistics. Psychological Science in the Public Interest 8(2), 53–96","oeffentlich":true,"doi":"10.1111/j.1539-6053.2008.00033.x","url":"https://kops.uni-konstanz.de/entities/publication/1c820f2d-aeed-4bfd-b65b-0e3f86803750/full","abruf":"2026-10-12"},{"typ":"url","kurz":"Joyce, J.: Bayes' Theorem. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/bayes-theorem/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"39278b010c186583"}},{"id":"qa-6","status":"entwurf","clusterId":"A","werkstueckRef":"A.8","stufe":2,"question":"Eine Stadtverwaltung will die Zahl der Tauben in der Innenstadt senken und zahlt 2 Euro für jede abgelieferte tote Taube. In den ersten Wochen werden Hunderte Tauben abgegeben. Dann stellt die Verwaltung fest, dass einzelne Bürger Tauben extra züchten, und stoppt das Programm. Welches der folgenden Beispiele zeigt dasselbe Muster eines Fehlanreizes?","options":["Eine Regierung zahlte Geld für jede abgelieferte tote Kobra; manche Bürger begannen, Kobras zu züchten, und setzten die Tiere frei, als das Programm endete.","Eine Regierung zahlte Geld für jede abgelieferte tote Kobra; die Zahl der Schlangen sank dauerhaft, dafür nahmen die Nagetiere stark zu.","Eine Regierung startete eine Impfkampagne gegen Schlangenbisse; die Zahl der Bisse sank, doch die Menschen gingen mehr Risiken ein.","Eine Regierung zahlte Geld für jede abgelieferte tote Ratte; manche Jäger brachten Ratten aus Nachbarorten mit, um mehr Prämien zu kassieren."],"correctIndex":0,"explanation":"Der Taubenfall zeigt eine Kette: Die Prämie soll den Bestand senken, lockt aber dazu, Tiere eigens zu züchten, und nach dem Programmstopp bleibt die Frage, was mit den nun wertlosen Tieren geschieht. Genau diese Abfolge zeigt die bekannte Kobra-Lehrgeschichte aus dem kolonialen Indien: Kopfgeld, Zucht, Programmende, Freilassung, am Ende mehr Tiere als vorher. Die anderen Beispiele zeigen andere Mechanismen: eine Nebenwirkung für eine andere Art, mehr Risikobereitschaft nach einer Schutzmaßnahme oder ein Ausnutzen der Prämie, bei dem keine neuen Tiere entstehen. Im Tauben- wie im Kobrafall vergrößert der Fehlanreiz das Problem selbst: Eine Belohnung für das Messbare (abgelieferte Tiere) untergräbt das Ziel (weniger Tiere). Hinweis zur Sachlage: Das bekannte Lehrbeispiel mit den Kobras im kolonialen Indien ist historisch nicht belegt (die Friends of Snakes Society fand 2025 keine zeitgenössischen Belege für Kobra-Zuchtbetriebe), der Mechanismus selbst aber ist real und an anderen Fällen dokumentiert.","coreRule":"⚡ Denke in höheren Ordnungen: Frage immer „Und was dann? Und wie reagiert das System?“","quote":"","quoteLabel":"","scenario":"","beleg":"Werkstück A.8, Fußnote ga-kobra (Kobra-Effekt, Mechanismus real, Anekdote historisch dünn); Anmerkung anm-ga-kobra","kurz":"Gesucht ist dieselbe Kette wie bei den Tauben: Die Prämie soll den Bestand senken, lockt aber dazu, Tiere eigens zu züchten, und vergrößert so das Problem. Nur das Kobra-Beispiel mit Zucht und Freilassung zeigt diesen Ablauf.","prueffrage":"Woher stammen die Tiere, für die bezahlt wird, und gab es sie alle schon vor der Prämie?","rueckmeldung":[{"option":1,"text":"Die Prämie hat hier zwar eine Nebenwirkung, doch sie trifft eine andere Art: Wenn die Schlangen verschwinden, vermehren sich ihre Beutetiere. Von Zucht um der Prämie willen und von einem Programmende mit Folgen ist nicht die Rede."},{"option":2,"text":"Eine Schutzmaßnahme, nach der Menschen mehr Risiken eingehen, folgt einem eigenen Mechanismus. Hier lockt keine Belohnung dazu, das Problem selbst zu erzeugen, und es gibt auch keinen Programmstopp mit Folgen."},{"option":3,"text":"Auch hier wird die Prämie ausgenutzt, doch es entstehen keine neuen Tiere: Die Jäger holen vorhandene Ratten von anderswo. Es fehlen die Zucht um der Prämie willen und das Programmende, nach dem wertlos gewordene Tiere übrig bleiben."}],"familie":"systemisch-denken","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Friends of Snakes Society (2025, aktualisiert 16.09.2026): The Cobra Effect: Colonial Misinformation Masquerading as Economic Theory","oeffentlich":true,"url":"https://friendsofsnakes.org.in/cobra-effect/","abruf":"2026-10-12"},{"typ":"url","kurz":"Gilbert, M. J.: Interview mit Michael G. Vann zur Rattenjagd in Hanoi 1902. World History Connected 15.2","oeffentlich":true,"url":"https://worldhistoryconnected.press.uillinois.edu/15.2/vann_interview.html","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Siebert, H. (2001): Der Kobra-Effekt","oeffentlich":false}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"210d923506f75859"}},{"id":"qa-7","status":"entwurf","clusterId":"A","werkstueckRef":"A.10","stufe":2,"question":"Wie reagierst du am besten, bevor du einen Einwand gegen Saras Vorschlag vorbringst?","options":["Du fasst ihren Vorschlag in seiner überzeugendsten Form zusammen, lässt dir bestätigen, dass du ihn richtig erfasst hast, und erst dann nennst du deinen Einwand.","Du fasst ihren Vorschlag kurz zusammen, überspringst die Rückfrage und nennst gleich deinen stärksten Einwand, damit die Sitzung nicht lange dauert.","Du nennst zuerst deinen Einwand und schließt danach eine knappe Zusammenfassung ihres Vorschlags an, damit klar wird, worauf er sich bezieht.","Du nimmst den Vorschlag zunächst gar nicht auf und sammelst alle Schwachstellen, die dir einfallen, damit der Einwand möglichst vollständig ausfällt."],"correctIndex":0,"explanation":"Wer eine Gegenposition erst in ihrer stärksten und plausibelsten Form wiedergibt und sich bestätigen lässt, dass er sie richtig verstanden hat, schafft zwei Vorteile. Erstens zwingt es ihn, die Position wirklich zu verstehen, statt gegen eine Vermutung zu argumentieren. Zweitens zählt der Einwand mehr: Wer die stärkste Version einer Idee widerlegt, hat sie wirklich widerlegt, wer nur eine Karikatur besiegt, hat nichts erreicht. Dazu kommt, dass sich ein verstandener Gegner eher auf Kritik einlässt als jemand, der sich verzerrt dargestellt fühlt. Toms Antwort ist das Gegenbeispiel: Er greift eine abwertende Verkürzung an, nicht Saras tatsächliches Anliegen. Die übrigen Wege lassen die Prüfung aus: Ohne Rückfrage bleibt offen, ob die Zusammenfassung stimmt. Wer erst den Einwand nennt, hat die Position noch nicht in ihrer stärksten Form geprüft; ein fair behandelter Gegner hört der Kritik eher zu. Und eine reine Fehlersammlung ohne Verständnis richtet sich gegen eine selbstgebaute Version des Vorschlags.","coreRule":"⚡ Erst die Gegenposition so stark und fair wiedergeben, dass der andere zustimmt – dann kritisieren.","quote":"","quoteLabel":"","scenario":"In der Teamsitzung schlägt Sara vor, die Vier-Tage-Woche einzuführen. Du hältst das für falsch. Tom antwortet sofort: „Ihr wollt also einfach weniger arbeiten und trotzdem volles Gehalt kassieren?“ Du willst es besser machen als Tom und deinen Einwand wirksam vorbringen.","beleg":"Werkstück A.10, Kernidee und Rapoports Regeln (Fußnote ga-rapoport), Abschnitt „Kontext & Tiefe“","kurz":"Wer Saras Vorschlag in seiner stärksten Form wiedergibt und sich bestätigen lässt, versteht ihn wirklich. Erst dann trifft der Einwand das tatsächliche Anliegen, statt wie bei Tom eine Verkürzung anzugreifen.","prueffrage":"Was genau hat Sara vorgeschlagen, und was davon ist in Toms Antwort noch zu erkennen?","rueckmeldung":[{"option":1,"text":"Das Zusammenfassen ist ein guter Anfang, und Zeit zu sparen ist verständlich. Ohne Rückfrage bleibt aber offen, ob die Zusammenfassung stimmt, und dein Einwand könnte an Saras eigentlichem Anliegen vorbeigehen."},{"option":2,"text":"Ein klarer Bezug des Einwands ist sinnvoll, und eine Zusammenfassung gehört dazu. Kommt der Einwand aber zuerst, steht noch gar nicht fest, ob du den Vorschlag richtig erfasst hast, und Sara hört eher zu, wenn sie sich zuvor fair dargestellt sieht."},{"option":3,"text":"Ein gründlicher Einwand klingt stark, besonders mit vielen Schwachstellen. Ohne den Vorschlag erst aufzunehmen, kritisierst du aber womöglich eine selbstgebaute Version davon, ähnlich wie Tom, statt Saras tatsächliches Anliegen."}],"familie":"fair-wiedergeben","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"3 Quarks Daily (23.05.2013): Daniel Dennett's seven tools for thinking – Auszug aus Dennett 2013, zuerst The Guardian, Abschn. „Respect your opponent“","oeffentlich":true,"url":"https://3quarksdaily.com/?p=18487","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Rapoport, A. (1960): Fights, Games, and Debates","oeffentlich":false},{"typ":"literatur","kurz":"Dennett, D. C. (2013): Intuition Pumps and Other Tools for Thinking","oeffentlich":false}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"7b4dcf57986c81ce"}},{"id":"qa-8","status":"entwurf","clusterId":"A","werkstueckRef":"A.14","stufe":1,"question":"Welche Frage hilft dir am besten, die Entscheidung über die Mitgliedschaft nüchtern zu treffen?","scenario":"Seit drei Jahren zahlst du 50 € im Monat für ein Fitnessstudio, warst aber seit einem Jahr kein einziges Mal mehr dort. Beim Blick auf den Kontoauszug denkst du: „Ich habe schon so viel Geld hineingesteckt, jetzt kann ich nicht einfach kündigen.“ Eine Freundin sagt: „Dann mach doch einen Realitätscheck.“","options":["„Würde ich die Mitgliedschaft heute, mit allem, was ich jetzt weiß, noch einmal abschließen?“","„Wie oft muss ich noch hingehen, damit sich die bisher gezahlten 1.800 Euro gelohnt haben?“","„Habe ich in den drei Jahren insgesamt genug trainiert, um die Mitgliedschaft zu rechtfertigen?“","„Wie erkläre ich mir selbst, dass ich nach drei Jahren Treue nicht einfach aufgeben darf?“"],"correctIndex":0,"explanation":"Die bisher gezahlten 1.800 Euro sind weg, egal ob du kündigst oder weitermachst. Sie dürfen deshalb nicht in die Entscheidung einfließen. Entscheidend ist nur, was ab jetzt zu erwarten ist: Kosten und Nutzen der kommenden Monate. Die Probe dafür ist ein gedanklicher Neustart: Würdest du heute, ohne Vorgeschichte, mit deinem jetzigen Wissen einen Vertrag über 50 Euro im Monat unterschreiben? Lautet die Antwort „Nein“, ist das ein starkes Signal, nur aus Trägheit und wegen versunkener Kosten festzuhalten. Die anderen Fragen blicken zurück und versuchen, die vergangenen Ausgaben nachträglich zu rechtfertigen. Wer so fragt, begründet das Festhalten mit der Vergangenheit statt mit dem künftigen Nutzen.","coreRule":"⚡ Ignoriere versunkene Kosten: Frag dich, ob du heute neu damit anfangen würdest. Wenn nicht, beende es.","quote":"Unabhängig von dem, was ich bisher investiert habe: Wenn ich nicht schon dabei wäre, würde ich heute damit anfangen?","quoteLabel":"Prüffrage:","beleg":"Werkstück A.14, Kernidee und Aktivierungs-Frage (Null-Basis-Check); Bezug zur Versunkene-Kosten-Falle (B.6). Keine Fußnoten.","kurz":"Die gezahlten 1.800 Euro sind weg, egal wie du dich entscheidest. Zählen kann nur der künftige Nutzen gegen die künftigen Kosten; der Denkfehler liegt darin, das Festhalten mit der Vergangenheit zu begründen statt mit dem, was kommt.","prueffrage":"Welche Zahlungen und welchen Nutzen kannst du mit deiner Entscheidung heute überhaupt noch verändern?","rueckmeldung":[{"option":1,"text":"Die Frage klingt nach Zukunft, denn es geht ums Hingehen. Als Ziel dient aber die Summe von 1.800 Euro, die schon bezahlt und nicht zurückzuholen ist. Gemessen wird so an der Vergangenheit, nicht am künftigen Nutzen."},{"option":2,"text":"Ein Blick zurück auf drei Jahre wirkt wie eine faire Bilanz. Er ändert aber nichts an den kommenden Monaten: Das bereits Gezahlte bleibt verloren, und seit einem Jahr gab es ohnehin keinen Besuch mehr."},{"option":3,"text":"Hier wird nicht geprüft, sondern eine Begründung gesucht. Die Frage setzt schon voraus, dass du nicht aufgeben darfst, und stützt sich dabei auf die Vorgeschichte statt auf den Nutzen der kommenden Monate."}],"familie":"versunkene-kosten","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Arkes, H. R.; Blumer, C. (1985): The Psychology of Sunk Cost. OBHDP 35(1), 124–140 (Kopie auf einem Kursserver der Universität Klagenfurt, nicht die Verlagsfassung)","oeffentlich":true,"doi":"10.1016/0749-5978(85)90049-4","url":"https://cognition.aau.at/bg/BA/Arkes%20%26%20Blumer%201985.pdf","seite":"124–125","abruf":"2026-10-12"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"d32b72fbe76080db"}},{"id":"qa-9","status":"entwurf","clusterId":"A","werkstueckRef":"A.24","stufe":4,"question":"Welche Schlussfolgerung ist aus dieser Lage gerechtfertigt – und welche nicht?","options":["Die Studien in den Fachzeitschriften wurden gefälscht, denn sonst könnten die beiden Erfolgsquoten nicht so weit auseinanderliegen.","Die Behördenakten sind unzuverlässig, denn eine Quote von nur 51 % widerspricht der Erfahrung der meisten Fachleute.","Die Medikamente wirken in der Praxis kaum, denn eine Erfolgsquote von 51 % liegt nahe am reinen Zufall von 50 %.","Die gedruckte Literatur zeichnet ein verzerrtes Bild, denn offenbar wurden vor allem die positiven Studien veröffentlicht."],"correctIndex":3,"explanation":"Die Lücke zwischen 94 % und 51 % entsteht durch Auswahl: Die FDA-Akten erfassten jede Studie schon vor Beginn, ob sie später gedruckt wurde oder nicht. In der Literatur fehlten dagegen die negativen Studien: Von den 36 negativen oder fragwürdigen waren 22 nie erschienen, und 11 weitere waren so umgeschrieben worden, dass sie dort als Erfolge dastanden. Das Umschreiben ist eine Verzerrung der Darstellung, kein Beleg für gefälschte Daten. Auch sonst mussten die einzelnen Studien nicht gefälscht sein: Jede konnte eine saubere Kontrollgruppe, eine korrekte Verblindung und eine ordentliche Statistik haben. Der Fehler liegt im Überlebendenverzeichnis, nicht in der einzelnen Studie. Wer nur las, was gedruckt war, überschätzte die Wirkung der Medikamente um rund ein Drittel. Die 51 % sagen nur, wie viele der registrierten Studien positiv ausgingen; über die Größe des Effekts sagen sie nichts. Sie erlauben deshalb weder den Schluss auf Wirkungslosigkeit noch auf bloßen Zufall.","coreRule":"⚡ Was wurde nicht veröffentlicht? Wer nur das Gedruckte liest, sieht eine ausgewählte Stichprobe. Frag nach dem Studienregister: Wie viele angemeldete Studien erschienen nie?","quote":"Die Täuschung lag nicht in den Studien. Sie lag in der Schublade, in der die anderen verschwunden waren.","quoteLabel":"Publikationsbias","scenario":"Ein Forscher vergleicht zwei Bilder desselben Gegenstands. Bild 1: die veröffentlichte Fachliteratur zu zwölf Antidepressiva. Dort melden 94 % der Studien einen Erfolg. Bild 2: die Akten der Arzneimittelbehörde FDA, bei der jede Studie vor Beginn angemeldet werden musste, ob sie später gedruckt wurde oder nicht. Dort stehen 74 Studien, von denen nur 51 % positiv ausgingen.","beleg":"Werkstück A.24, Abschnitt „Die Schublade“ (Zitat), Fußnote ga-publikationsbias (Turner et al. 2008, NEJM 358(3): 74 FDA-Studien, 94 % vs. 51 % positiv, Überschätzung um ca. 32 %)","kurz":"Die Lücke von 94 % zu 51 % entsteht durch Auswahl: Negative Studien blieben ungedruckt oder wurden umgeschrieben. Der naheliegende Fehler ist, in der gedruckten Literatur das ganze Bild zu sehen, obwohl sie nur die Überlebenden zeigt.","prueffrage":"Was unterscheidet die Studien in den Behördenakten von denen in den Fachzeitschriften, abgesehen vom Ergebnis?","rueckmeldung":[{"option":0,"text":"Eine so große Lücke weckt schnell den Verdacht auf Fälschung. Sie lässt sich aber ohne gefälschte Daten erklären: Negative Studien blieben ungedruckt oder wurden in der Darstellung zu Erfolgen umgeschrieben."},{"option":1,"text":"Eine Quote, die dem gewohnten Bild widerspricht, macht misstrauisch. Die Akten erfassten aber jede Studie schon vor Beginn, auch die nie gedruckten. Gerade sie sind die vollständigere Quelle, nicht die unzuverlässigere."},{"option":2,"text":"51 % klingt nach Münzwurf, doch ohne jede Wirkung fiele nur ein kleiner Teil der Studien zufällig positiv aus, nicht die Hälfte. Zudem zählt die Quote nur positive Studien und sagt nichts über die Größe des Effekts."}],"familie":"fehlende-faelle-suchen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Turner, E. H.; Matthews, A. M.; Linardatos, E.; Tell, R. A.; Rosenthal, R. (2008): Selective Publication of Antidepressant Trials and Its Influence on Apparent Efficacy. NEJM 358(3), 252–260 (Abstract)","oeffentlich":true,"doi":"10.1056/NEJMsa065779","url":"https://pubmed.ncbi.nlm.nih.gov/18199864/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Rosenthal, R. (1979): The File Drawer Problem and Tolerance for Null Results. Psychological Bulletin 86(3), 638–641","oeffentlich":false}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"4ca3605f6ce6d4e0"}},{"id":"qa-10","status":"entwurf","clusterId":"A","werkstueckRef":"Anhang VII.2","stufe":2,"question":"Ein Sprachmodell liefert dir zu deiner Hypothese eine Studie mit Autor, Jahr und Zeitschrift, die sie scheinbar bestätigt. Was musst du tun, bevor daraus ein Beleg wird?","options":["Du hältst die Angabe für einen Beleg, sobald Autor, Jahr und Zeitschrift plausibel klingen, denn erfundene Quellen wären auffällig.","Du fragst dasselbe Modell noch einmal und wertest die Studie als bestätigt, wenn es sie ein zweites Mal nennt.","Du öffnest die Quelle außerhalb der KI, prüfst DOI oder Fundstelle und liest die Kernaussage im Original.","Du prüfst nur, ob die Zeitschrift existiert, und verlässt dich darauf, dass das Modell den Inhalt zuverlässig zusammenfasst."],"correctIndex":2,"explanation":"Was ein Sprachmodell liefert, ist eine Liste von Kandidaten, keine Quelle. Fünf Fehlerarten treten regelmäßig auf: Die Quelle existiert nicht; sie sagt etwas anderes; sie ist überholt; die Zusammenfassung verdreht das Ergebnis; das Modell stimmt dir zu, weil du ihm deine Hypothese verraten hast. Plausibel klingende Angaben und eine wiederholte Antwort desselben Modells prüfen nichts, denn beides stammt aus derselben Quelle, die du gerade überprüfen willst. Dass eine Zeitschrift existiert, sagt noch nichts darüber, ob der genannte Aufsatz darin steht oder das behauptet, was das Modell ihm zuschreibt. Ein Beispiel: Im Fall Mata v. Avianca (New York, 2023) belegte ChatGPT einen Schriftsatz mit sechs frei erfundenen Gerichtsurteilen; das Gericht verhängte Sanktionen.","coreRule":"⚡ KI-Ergebnis ≠ Beleg: außerhalb der KI öffnen, Fundstelle prüfen, Kernaussage im Original lesen.","quote":"","quoteLabel":"","kurz":"Was das Modell nennt, ist nur ein Kandidat. Erst das Original zeigt, ob die Studie existiert und das aussagt, was behauptet wird. Plausible Angaben oder eine wiederholte Antwort desselben Modells prüfen nichts, denn sie kommen aus derselben Quelle.","prueffrage":"Was wüsstest du über diese Studie, wenn dir niemand außer dieser einen Quelle davon erzählt hätte?","rueckmeldung":[{"option":0,"text":"Autor, Jahr und Zeitschrift wirken wie die Bestandteile einer echten Quelle. Genau solche Angaben erzeugt ein Sprachmodell aber auch frei, etwa die erfundenen Urteile im Fall Mata v. Avianca. Plausibel zu klingen, belegt nichts."},{"option":1,"text":"Eine zweite Nennung derselben Studie fühlt sich wie Bestätigung an. Beide Antworten stammen aber aus derselben Quelle, die du gerade überprüfen willst. Eine Wiederholung ist deshalb keine unabhängige Prüfung."},{"option":3,"text":"Dass die Zeitschrift existiert, ist ein sinnvoller erster Schritt. Er sagt aber nichts darüber, ob der Aufsatz dort steht oder das aussagt, was das Modell behauptet. Auch eine Zusammenfassung kann das Ergebnis verdrehen."}],"familie":"ki-ausgabe-pruefen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Mata v. Avianca, Inc., No. 22-cv-1461 (PKC), S.D.N.Y.: Opinion and Order on Sanctions, 22.06.2023 (ECF 54), Richter P. Kevin Castel","oeffentlich":true,"url":"https://storage.courtlistener.com/recap/gov.uscourts.nysd.575368/gov.uscourts.nysd.575368.54.0.pdf","seite":"S. 1","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Mata v. Avianca, Inc., 678 F. Supp. 3d 443 (S.D.N.Y. 2023)","oeffentlich":false,"seite":"S. 456, 466 (laut Belegregister)"}],"thema":"Technik und KI"},{"id":"qb-1","status":"entwurf","clusterId":"B","werkstueckRef":"B.1","stufe":1,"question":"Ein Kollege ist überzeugt, dass die neue Mitarbeiterin schlampig arbeitet. Hat sie ein Detail richtig gemacht, sagt er: „Zufall.“ Unterläuft ihr ein Fehler, sagt er: „Ich wusste es.“ Welche Frage zeigt am besten, ob sein Urteil auf einer fairen Prüfung beruht?","options":["Welche Beobachtung würde ihn dazu bringen, sein Urteil aufzugeben, und hat er auch nach solchen gesucht?","Wie viele Fehler hat er insgesamt gefunden, und sind es mehr als drei, die er sich gemerkt hat?","Wie überzeugt und selbstsicher ist er von seinem Urteil, und wie lange hält er es schon?","Findet die Mitarbeiterin selbst, dass sie sorgfältig arbeitet, und würde sie das auch anderen gegenüber sagen?"],"correctIndex":0,"explanation":"Hier wird nicht geprüft, sondern gesammelt: Der Kollege sucht und deutet einseitig, denn Fehler gelten als Beweis, Treffer als Zufall. Das ist genau der Bestätigungsfehler. Die wirksame Gegenfrage lautet: Was wäre der stärkste Beweis gegen meine Position? Dass er Treffer als Zufall abtut und nur Fehler zählt, zeigt die einseitige Auswahl; die bloße Zahl der Fehler belegt daher nichts. Seine Überzeugung ist kein Beleg, und ihre eigene Einschätzung ersetzt keine neutrale Prüfung. Wer jede Beobachtung zur eigenen Vermutung passend deutet, bestätigt sich selbst, ohne etwas zu testen.","coreRule":"Wer nur nach Bestätigung sucht, findet sie immer. Frag dich: Was würde meine Annahme widerlegen, und habe ich danach gesucht?","quote":"","quoteLabel":"","scenario":"Schon in der ersten Woche hat er einen kleinen Tippfehler von ihr bemerkt und sich daraufhin festgelegt: Sie arbeitet schlampig. Seitdem achtet er genau auf ihre Fehler. Ihre korrekt erledigten Aufgaben kommentiert er höchstens mit „Glück gehabt“. Auf Nachfrage nennt er drei Fehler als Beweis.","beleg":"Werkstück B.1, Fußnote gl-b-nickerson (Nickerson 1998, S. 175 f., 178, 211): einseitiges Suchen und Deuten von Belegen zugunsten der vorliegenden Hypothese; Menschen suchen von sich aus kaum nach Widerlegung.","kurz":"Fair geprüft wäre sein Urteil nur, wenn er auch angeben könnte, was es widerlegen würde. Er wertet Fehler als Beweis und Treffer als Zufall, deshalb bestätigt jede Beobachtung seine Vermutung. Das ist der Bestätigungsfehler.","prueffrage":"Wie viele ihrer Aufgaben hat sie fehlerfrei erledigt, und wie hat er diese bewertet?","rueckmeldung":[{"option":1,"text":"Die Zahl der Fehler zu kennen, ist ein Anfang, aber allein sagt sie wenig: Er zählt nur Fehler und wertet Treffer als Zufall. Eine Auswahl, die von vornherein nur das Passende sammelt, wird durch mehr Funde nicht aussagekräftiger."},{"option":2,"text":"Wie fest er überzeugt ist und wie lange schon, beschreibt seine Haltung, nicht die Prüfung. Sicherheit wirkt überzeugend, ist aber kein Beleg. Auch eine falsche Annahme kann sich lange und sehr sicher anfühlen."},{"option":3,"text":"Ihre Sicht ist als zusätzliche Information durchaus interessant. Ob er fair prüft, zeigt sie aber nicht, denn das hängt an seinem Vorgehen. Eine Selbsteinschätzung ersetzt keine neutrale Prüfung."}],"familie":"gegenbeleg-suchen","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Nickerson, R. S. (1998): Confirmation Bias: A Ubiquitous Phenomenon in Many Guises. Review of General Psychology 2(2), 175–220","oeffentlich":true,"url":"https://pages.ucsd.edu/~mckenzie/nickersonConfirmationBias.pdf","seite":"175","abruf":"2026-10-12"},{"typ":"url","kurz":"Dowden, B.: Fallacies, Eintrag „Confirmation Bias“. Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Nickerson (1998), Verlagsfassung APA","oeffentlich":false,"doi":"10.1037/1089-2680.2.2.175"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"7fabaa9802df1fdd"}},{"id":"qb-2","status":"entwurf","clusterId":"B","werkstueckRef":"B.2","stufe":1,"question":"Welche Erklärung passt am besten zu Marias Verhalten?","options":["Sie lässt sich von einer ersten Zahl, die sie gehört hat, in all ihren späteren Einschätzungen leiten.","Ihr fehlt das Wissen, um zu erkennen, wie viel sie noch nicht weiß, und deshalb wirkt ihr eigenes Urteil überzeugender, als es ist.","Sie schaut nur auf die Anleger, die gewonnen haben, und übersieht dabei jene, die gescheitert und aus dem Markt verschwunden sind.","Sie schreibt eigene Erfolge sich selbst zu und Verluste den äußeren Umständen, um ihr Selbstbild zu schützen."],"correctIndex":1,"explanation":"Was Maria vor allem auszeichnet, ist eine Selbstsicherheit, die ihrem Wissensstand weit vorauseilt. Die Fähigkeiten, die man braucht, um in einem Bereich gut zu sein, sind dieselben, die man braucht, um die eigene Leistung dort einzuschätzen. Wer ein Feld nur oberflächlich kennt, sieht dessen Komplexität nicht und hält seine einfachen Antworten deshalb für ausreichend. Ein extremes Beispiel ist der Bankräuber McArthur Wheeler (1995), der sein Gesicht mit Zitronensaft einrieb, weil er glaubte, das mache ihn für Kameras unsichtbar, und der vom Fehlschlag völlig überrascht war. Für die anderen Deutungen gibt es keine Anhaltspunkte: Eine Ausgangszahl, die ihr Urteil lenkt, kommt nicht vor, ebenso wenig eine Auswahl nur der Gewinner oder ein Muster aus selbst zugeschriebenen Erfolgen und fremd verschuldeten Misserfolgen. Zugleich gilt: Aus dem Verhalten allein lässt sich nicht beweisen, dass dieser Mechanismus wirkt. Wie viel davon echte Blindheit für die eigene Inkompetenz ist und wie viel ein statistischer Effekt, ist in der Forschung umstritten.","coreRule":"⚡ Die doppelte Bürde: Wer in einem Feld wenig kann, dem fehlt oft auch das Rüstzeug, die eigene Schwäche zu erkennen. Misstrauen ist angebracht, wenn Gewissheit schnell wächst und Expertenwissen als „unnötig kompliziert“ abgetan wird.","quote":"","quoteLabel":"","scenario":"Maria hat drei Wochen lang Videos über Börsenhandel gesehen. Sie ist überzeugt, den Markt zu durchschauen, und rät ihrem Onkel, der seit 30 Jahren als Vermögensberater arbeitet, seine Strategie sei „völlig veraltet“. Seine Einwände wischt sie als „unnötig kompliziert“ weg. Mit seinen Einwänden kann sie nichts anfangen, weil sie die Fachbegriffe dahinter nicht kennt.","beleg":"Werkstück B.2 (Wheeler-Episode, Dunning-Kruger-Effekt, Hinweis zur Beleglage); Fn. gl-b-wheeler, gl-b-dunning","kurz":"Maria kennt das Feld so wenig, dass sie dessen Komplexität nicht sieht und ihre einfachen Antworten für ausreichend hält. Der naheliegende Fehler: ihre Sicherheit für Kompetenz zu nehmen. Beweisen lässt sich der Mechanismus aus dem Verhalten allein nicht.","prueffrage":"Wie lange befasst sich Maria schon mit Börsenhandel, wie lange ihr Onkel, und wie sicher tritt jeder von beiden auf?","rueckmeldung":[{"option":0,"text":"Eine Ausgangszahl, an der sich spätere Einschätzungen ausrichten, ist bei Maria nicht zu erkennen. Sie hat drei Wochen Videos gesehen und urteilt daraufhin selbstsicher; für diese Deutung fehlt jeder Anhaltspunkt."},{"option":2,"text":"Nur Gewinner zu betrachten und die Gescheiterten zu übersehen, ist ein verbreiteter Fehler beim Blick auf Märkte. Bei Maria ist davon aber nichts zu sehen: Von Gewinnern oder Ausgeschiedenen ist nirgends die Rede."},{"option":3,"text":"Diese Deutung braucht Erfolge und Misserfolge, die jemand unterschiedlich erklärt. Von Gewinnen oder Verlusten Marias ist aber keine Rede, beschrieben ist nur ihre Selbstsicherheit nach drei Wochen Videos."}],"familie":"gewissheit-kalibrieren","fertigkeit":"F5","quellen":[{"typ":"doi","kurz":"Kruger, J.; Dunning, D. (1999): Unskilled and Unaware of It. Journal of Personality and Social Psychology 77(6), 1121–1134","oeffentlich":false,"doi":"10.1037/0022-3514.77.6.1121","seite":"S. 1121"},{"typ":"doi","kurz":"Magnus, J. R.; Peresetsky, A. A. (2022): A Statistical Explanation of the Dunning–Kruger Effect. Frontiers in Psychology 13","oeffentlich":true,"doi":"10.3389/fpsyg.2022.840180","abruf":"2026-10-12"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"d667aec7b7d609ae"}},{"id":"qb-3","status":"entwurf","clusterId":"B","werkstueckRef":"B.6","stufe":1,"question":"Was ist an dieser Begründung fehlerhaft, und welche Frage würde die Entscheidung besser tragen?","options":["Der Fehler liegt darin, dass die 25 € ohnehin nicht zurückkommen, ob du bleibst oder gehst. Besser ist die Frage: „Was ist die beste Nutzung der nächsten 90 Minuten?“","Der Fehler liegt darin, dass nach zwanzig Minuten noch kein Urteil über den Film möglich ist. Besser ist die Frage: „Wie hat der Film bei anderen Zuschauern abgeschnitten?“","Der Fehler liegt darin, dass der Preis des Abends zu hoch gewesen ist. Besser ist die Frage: „Hätte ich für das Geld etwas Günstigeres unternehmen können?“","Der Fehler liegt darin, dass du die Meinung der anderen im Saal ausblendest. Besser ist die Frage: „Bleiben die anderen Zuschauer bis zum Ende sitzen?“"],"correctIndex":0,"explanation":"Die 25 € sind in dem Moment weg, in dem du bezahlst. Du bekommst sie nicht zurück, egal ob du den Film zu Ende siehst oder nicht. Das Geld darf deshalb die Entscheidung nicht lenken, nur die Zukunft zählt. Wer bleibt, verliert zusätzlich 90 Minuten Lebenszeit. Die Begründung „Ich habe doch schon so viel bezahlt“ ist ein Warnsignal für die Versunkene-Kosten-Falle: Sie bindet uns an eine Entscheidung, weil wir Geld und Mühe nicht als „verschwendet“ abschreiben wollen (Verlustaversion, Wunsch nach Konsistenz). Die gute Frage lautet: Was ist ab jetzt die beste Nutzung meiner Zeit? Nach Hause gehen und ein gutes Buch lesen ist dabei eine naheliegende Alternative.","coreRule":"⚡ Vergangene Kosten sind vergangen. Entscheide nur nach dem, was künftig Kosten und Nutzen bringt.","quote":"","quoteLabel":"","scenario":"Du sitzt im Kino. Du hast 15 € für die Karte und 10 € für Popcorn und Getränk bezahlt. Nach zwanzig Minuten ist klar: Der Film ist furchtbar. Du sagst dir: „Ich bleibe, schließlich habe ich 25 € für diesen Abend ausgegeben. Wenn ich jetzt gehe, war das Geld verschwendet.“","beleg":"Werkstück B.6, Fußnote gl-b-sunk-cost (Arkes/Blumer 1985, S. 124, 126): Kinofilm-Beispiel, Kernidee und Aktivierungsfrage der Versunkene-Kosten-Falle","kurz":"Die 25 € sind weg, ob du bleibst oder gehst, deshalb darf das Geld die Entscheidung nicht lenken. Zählen kann nur, was dir die nächsten 90 Minuten bringen, und die kosten dich zusätzlich Lebenszeit.","prueffrage":"Wie würdest du entscheiden, wenn dir eine Freundin Karte und Popcorn geschenkt hätte?","rueckmeldung":[{"option":1,"text":"Nach zwanzig Minuten steht das Urteil hier schon fest, daran liegt es nicht. Der Fehler steckt in der Begründung über die 25 €, und die Meinung anderer sagt nicht, was du aus deiner Zeit machen willst."},{"option":2,"text":"Ein Blick zurück auf den Preis wirkt vernünftig, ändert aber nichts: Das Geld ist ausgegeben, egal ob günstiger oder nicht. Für die Entscheidung jetzt zählt nur, was ab jetzt kommt."},{"option":3,"text":"Was die anderen tun, ist ein Hinweis auf ihre Lage, nicht auf deine. Sie können aus denselben Gründen sitzen bleiben, etwa weil sie bezahlt haben. Die gute Frage richtet sich auf deine eigene Zeit."}],"familie":"versunkene-kosten","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Arkes, H. R.; Blumer, C. (1985): The Psychology of Sunk Cost. Organizational Behavior and Human Decision Processes 35(1) (inoffizielle Kopie, Universität Klagenfurt)","oeffentlich":true,"url":"https://cognition.aau.at/bg/BA/Arkes%20%26%20Blumer%201985.pdf","seite":"124, 126","abruf":"2026-10-12"},{"typ":"doi","kurz":"Arkes, H. R.; Blumer, C. (1985): The Psychology of Sunk Cost, Verlagsfassung","oeffentlich":false,"doi":"10.1016/0749-5978(85)90049-4"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"0a6b273c98a24c42"}},{"id":"qb-4","status":"entwurf","clusterId":"B","werkstueckRef":"B.10","stufe":2,"question":"Welche Erklärung für die hohe Bewertung passt am besten zu diesem Befund?","options":["Die Studierenden hatten sich so offen im Test gezeigt, dass jede Auswertung ihr Wesen zwangsläufig gut traf.","Die Skala reichte nur bis 5, und die Obergrenze zog die Urteile der Studierenden insgesamt nach oben.","Die Sätze sind so vage und schmeichelhaft, dass fast jeder passende Beispiele aus seinem Leben findet und sie auf sich bezieht.","Nur Studierende mit besonders guter Selbstkenntnis hatten den Test ausgefüllt und erkannten sich daher wieder."],"correctIndex":2,"explanation":"Alle bekamen denselben Text, also kann er nicht auf die einzelne Person zugeschnitten gewesen sein. Dass er trotzdem fast jeden überzeugt, liegt an seiner Bauweise: Die Aussagen sind allgemeingültig (fast jeder ist mal extrovertiert, mal introvertiert, fast jeder ist manchmal selbstkritisch), schmeicheln dem Selbstbild und enthalten nur kleine, verzeihliche „Schwächen“. Beim Lesen sucht das Gehirn gezielt nach Situationen, die zur Aussage passen, und übersieht die, die ihr widersprechen. Die anderen Erklärungen scheitern: Auch die Offenheit im Test erklärt nichts, denn der Text war für alle identisch und gar nicht aus ihren Antworten abgeleitet. Eine Skalenobergrenze erklärt nicht, warum Menschen den Text für zutreffend halten, und ein Auswahleffekt wäre bei einer ganzen Seminargruppe, die denselben Text erhält, nicht plausibel. Dieses Muster trägt einen Großteil von Horoskopen, Wahrsagerei und Cold Reading.","coreRule":"⚡ Der schmeichelhafte Spiegel: Wie viele Menschen kenne ich, auf die diese Aussage NICHT zutreffen würde?","quote":"Er hatte allen Studenten exakt denselben Text gegeben.","quoteLabel":"Merksatz:","scenario":"Eine Dozentin lässt ihre Studierenden einen Persönlichkeitstest ausfüllen und verteilt eine Woche später angeblich „individuell auf dich zugeschnittene“ Auswertungen. Darin stehen Sätze wie „Du hast ein großes Bedürfnis nach der Zuneigung und Bewunderung anderer“, „Du neigst dazu, dir selbst gegenüber kritisch zu sein“ und „Manchmal bist du extrovertiert und gesellig, zu anderen Zeiten introvertiert und zurückhaltend“. Die Studierenden bewerten die Treffsicherheit auf einer Skala von 0 bis 5 im Schnitt mit 4,26. Später stellt sich heraus: Alle hatten denselben Text bekommen, größtenteils aus einem Astrologiebuch vom Zeitungskiosk übernommen.","beleg":"Werkstück B.10, Fn. gl-b-forer: Forer (1949), Mittelwert 4,26 auf Skala 0–5; Erklärungsmerkmale (universell, schmeichelhaft, Bestätigungsfehler) im Haupttext.","kurz":"Der Text war für alle gleich, also nicht persönlich zugeschnitten. Er überzeugt, weil er so allgemein und schmeichelhaft ist, dass fast jeder passende Situationen aus seinem Leben findet und die unpassenden übersieht.","prueffrage":"Würden die Studierenden den Text auch dann für passend halten, wenn sie ihn mit dem ihrer Sitznachbarn vergleichen?","rueckmeldung":[{"option":0,"text":"Offenheit im Test lässt eine Auswertung glaubwürdig wirken. Hier aber war der Text für alle identisch und nicht aus den Antworten abgeleitet, also kann die Offenheit die Treffsicherheit nicht erklären."},{"option":1,"text":"Eine Skala mit Obergrenze begrenzt nur den möglichen Wertebereich. Sie erklärt nicht, warum die Studierenden den Text für zutreffend hielten. Die hohe Bewertung braucht einen inhaltlichen Grund."},{"option":3,"text":"Ein Auswahleffekt setzt voraus, dass nur bestimmte Leute den Test ausfüllten; hier ließ die Dozentin ihre Studierenden insgesamt teilnehmen. Und gute Selbstkenntnis erklärt nicht, warum sich alle im selben Text wiedererkannten."}],"familie":"passt-auf-jeden","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Carroll, R. T.: Forer effect. The Skeptic's Dictionary","oeffentlich":true,"url":"https://skepdic.com/forer.html","abruf":"2026-10-12"},{"typ":"doi","kurz":"Forer, B. R. (1949): The Fallacy of Personal Validation: A Classroom Demonstration of Gullibility. Journal of Abnormal and Social Psychology 44(1), 118–123","oeffentlich":false,"doi":"10.1037/h0059240"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"0d93052eda317447"}},{"id":"qb-5","status":"entwurf","clusterId":"B","werkstueckRef":"B.15","stufe":3,"question":"Ein Analyst will entscheiden, wo Kampfflugzeuge zusätzlich gepanzert werden sollen. Er wertet dafür nur die Maschinen aus, die von ihren Einsätzen zurückgekehrt sind, und kartiert deren Einschusslöcher. Die meisten Treffer liegen an den Flügelspitzen, am Rumpf und am Heck, am Cockpit und an den Motoren findet er kaum welche. Welche Schlussfolgerung ist am besten begründet?","options":["Flügel und Rumpf sollten verstärkt werden, weil dort die meisten Einschusslöcher gezählt wurden und weitere folgen werden.","Cockpit und Motoren sollten verstärkt werden, weil Flugzeuge mit Treffern dort vermutlich nicht zurückgekehrt sind und in der Auswertung fehlen.","Auf zusätzliche Panzerung sollte ganz verzichtet werden, weil zusätzliches Gewicht Reichweite und Wendigkeit stärker senkt, als Treffer gefährden.","Das ganze Flugzeug sollte gleichmäßig verstärkt werden, weil sich künftige Treffer aus der Zählung nicht vorhersagen lassen."],"correctIndex":1,"explanation":"Die Auswertung enthält nur Flugzeuge, die trotz ihrer Treffer zurückgekommen sind. Die sichtbaren Löcher zeigen also, wo ein Flugzeug getroffen werden kann und trotzdem überlebt. Maschinen, die an Cockpit oder Motoren getroffen wurden, sind vermutlich abgestürzt und fehlen in der Stichprobe. Die Stellen ohne Einschusslöcher sind deshalb die verdächtigen. Das ist ein klassischer Überlebensirrtum: Die Stichprobe wurde durch das Überleben vorgefiltert, und die fehlenden Daten wären für die Schlussfolgerung entscheidend. Die übrigen Antworten ziehen Schlüsse aus der gefilterten Stichprobe oder weichen der Frage aus, ohne die Verzerrung zu erkennen. Am bekanntesten ist diese Überlegung vom Mathematiker Abraham Wald, der 1943 für die Statistical Research Group der Columbia University arbeitete. Die oft erzählte Dialogszene dazu ist allerdings zugespitzt, und eine ausdrückliche Panzerungsempfehlung ist in seinen Arbeiten nicht belegt.","coreRule":"⚡ Wo ist der unsichtbare Friedhof der Gescheiterten?","quote":"Die Toten können keine kritischen Blog-Posts schreiben.","quoteLabel":"Merksatz:","scenario":"","beleg":"Werkstück B.15 (Der Überlebensirrtum), Abschnitt „Anwendung & Relevanz“, Pseudomedizin; zur Wald-Szene Fußnote gl-b-wald: Mangel, M.; Samaniego, F. J. (1984): „Abraham Wald’s Work on Aircraft Survivability“. Journal of the American Statistical Association 79(386), S. 259–267","kurz":"Die Auswertung kennt nur Flugzeuge, die trotz ihrer Treffer zurückkamen. Die Lücken an Cockpit und Motoren deuten darauf hin, dass Maschinen mit Treffern dort fehlen, weil sie abgestürzt sind. Wer nur Überlebende zählt, schließt vom Gefilterten aufs Ganze.","prueffrage":"Woher stammen alle Flugzeuge, deren Einschusslöcher hier gezählt wurden, und was haben sie gemeinsam?","rueckmeldung":[{"option":0,"text":"Viele Löcher an einer Stelle wirken wie ein Hinweis auf eine Schwachstelle. Gezählt wurden aber nur Maschinen, die zurückkamen; die Treffer an Flügeln und Rumpf wurden also überstanden. Sie zeigen eher, wo Treffer wenig schaden."},{"option":2,"text":"Zusätzliches Gewicht kostet tatsächlich Reichweite und Wendigkeit. Wie schwer das wiegt, sagen die Daten aber nicht, und der Verzicht übergeht, was die verzerrte Stichprobe über die gefährdeten Stellen verrät."},{"option":3,"text":"Gleichmäßige Verstärkung wirkt fair, verschenkt aber Information. Die Daten sind nicht wertlos, sondern verzerrt: Wo Einschusslöcher fehlen, wurden vermutlich Maschinen getroffen, die nicht zurückkamen."}],"familie":"fehlende-faelle-suchen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Casselman, B. (2016): The Legend of Abraham Wald. AMS Feature Column","oeffentlich":true,"url":"https://www.ams.org/publicoutreach/feature-column/fc-2016-06","abruf":"2026-10-04"},{"typ":"doi","kurz":"Mangel, M.; Samaniego, F. J. (1984): Abraham Wald's Work on Aircraft Survivability. Journal of the American Statistical Association 79(386), 259–267","oeffentlich":false,"doi":"10.1080/01621459.1984.10478038"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"be6afa3025c08d04"}},{"id":"qb-6","status":"entwurf","clusterId":"B","werkstueckRef":"B.19","stufe":2,"question":"Welche Rückfrage trifft den Kern des Problems in diesem Fall am besten?","options":["Wurde vorab festgelegt, dass genau diese beiden Werte untersucht werden, oder erst nach Blick auf alle Ergebnisse ausgewählt?","Wurde das Mittel an Menschen aus mehreren Ländern getestet, damit das Ergebnis für die gesamte Bevölkerung gilt?","Haben die Probanden, die das Mittel nahmen, im Studienzeitraum zufällig auch mehr Sport getrieben und anders gegessen?","Wurden die beiden verbesserten Werte in der Gruppe mit dem Mittel zur gleichen Zeit und mit demselben Gerät gemessen?"],"correctIndex":0,"explanation":"In einer großen Datenmenge entstehen zwangsläufig zufällige Cluster. Zwei zufällige Treffer unter 50 gemessenen Werten sind deshalb noch kein Beweis. Entscheidend ist die Reihenfolge: Eine Hypothese, die vor der Datenerhebung feststand, wird durch einen Treffer gestützt. Wird sie erst nach dem Blick auf die Daten um die Treffer herum gebaut, ist das so, als würde man erst auf die Scheunenwand schießen und dann die Zielscheibe um die dichteste Stelle malen. Dazu kommt, dass die 48 Werte ohne Effekt verschwiegen werden. Ein solches Muster ist höchstens eine Vermutung, die an neuen, unabhängigen Daten geprüft werden muss.","coreRule":"⚡ Erst schießen, dann die Zielscheibe malen gilt nicht: Eine Hypothese muss vor den Daten feststehen, und ein im Nachhinein gefundenes Muster muss an neuen Daten bestätigt werden.","quote":"In jeder ausreichend großen und zufälligen Datenmenge entstehen zwangsläufig Cluster und scheinbar unwahrscheinliche Muster.","quoteLabel":"Merksatz:","scenario":"Ein Hersteller testet ein neues Nahrungsergänzungsmittel und misst bei den Probanden 50 verschiedene Gesundheitswerte. Bei 48 Werten zeigt sich kein Unterschied zur Vergleichsgruppe, bei zwei Werten gibt es eine kleine, „statistisch signifikante“ Verbesserung. In der Werbung heißt es: „Wissenschaftlich bewiesen: verbessert diese beiden Werte!“","kurz":"Entscheidend ist, wann die Hypothese feststand: Zwei Treffer unter 50 Werten können Zufall sein. Wer die Zielscheibe erst nach dem Schuss um die dichteste Stelle malt, beweist nichts, zumal die 48 Werte ohne Effekt verschwiegen werden.","prueffrage":"Wie viele der 50 Werte zeigten keinen Unterschied, und kommt das in der Werbung vor?","rueckmeldung":[{"option":1,"text":"Ob das Ergebnis über die Probanden hinaus gilt, ist eine berechtigte Frage. Sie trifft aber nicht den Kern: Auch eine internationale Stichprobe würde zwei Treffer unter 50 Messungen nicht überzeugender machen."},{"option":2,"text":"Andere Einflüsse wie Sport oder Ernährung können Ergebnisse verzerren. Den Kern trifft das aber nicht: Bei 50 gemessenen Werten sind einige kleine Treffer auch ohne jede Verzerrung allein durch Zufall zu erwarten."},{"option":3,"text":"Gleiche Messbedingungen sind wichtig für verlässliche Daten. Auch bei sauberster Messung bleibt aber das Kernproblem: Unter 50 Werten fallen einige allein durch Zufall signifikant aus, und wer erst danach auswählt, findet fast immer etwas."}],"familie":"muster-im-zufall","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"CDC/CSTE (2013): Investigating Suspected Cancer Clusters and Responding to Community Concerns. MMWR Recommendations and Reports 62(8)","oeffentlich":true,"url":"https://www.cdc.gov/mmwr/pdf/rr/rr6208.pdf","seite":"S. 21–22","abruf":"2026-10-12"},{"typ":"doi","kurz":"Nosek, B. A.; Ebersole, C. R.; DeHaven, A. C.; Mellor, D. T. (2018): The preregistration revolution. PNAS 115(11) (frei über PMC5856500)","oeffentlich":true,"doi":"10.1073/pnas.1708274114","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Kerr, N. L. (1998): HARKing: Hypothesizing After the Results are Known. Personality and Social Psychology Review 2(3), 196–217","oeffentlich":false}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"3af065e77662da2d"}},{"id":"qb-7","status":"entwurf","clusterId":"B","werkstueckRef":"B.28","stufe":2,"question":"Zwei Anleger haben jeweils 10.000 € in eine Aktie gesteckt. Am Abend ist Toms Aktie um 500 € gestiegen, Marias um 500 € gefallen. Tom klappt zufrieden den Laptop zu. Maria kann an nichts anderes mehr denken, liest fieberhaft Nachrichten und erwägt, alles zu verkaufen. Was erklärt den Unterschied in der Reaktion am sparsamsten?","options":["Ein Verlust wird gegenüber dem bisherigen Stand meist stärker gewichtet als ein gleich hoher Gewinn; Maria reagiert deshalb heftiger als Tom.","Ein Gewinn wird gegenüber dem bisherigen Stand meist stärker gewichtet als ein gleich hoher Verlust; Tom reagiert deshalb gelassener als Maria.","Beide bewerten ihr Depot allein nach dem absoluten Endstand ihres Vermögens; die unterschiedliche Reaktion liegt nur an der Tagesform.","Der empfundene Wert wächst proportional zum Betrag; Maria hat bei gleicher Summe also exakt so viel verloren, wie Tom gewonnen hat, und müsste gleich reagieren."],"correctIndex":0,"explanation":"Menschen bewerten Veränderungen nicht nach dem absoluten Endstand, sondern relativ zu einem Bezugspunkt, hier dem Stand vom Morgen. Von dort aus wiegt ein Verlust meist schwerer als ein gleich hoher Gewinn. Diese Verlustaversion wurde von Kahneman und Tversky beschrieben. In der klassischen Messung von 1992 wog ein Verlust rund doppelt so schwer, neuere Auswertungen finden je nach Methode ähnliche bis deutlich schwächere Werte; das „doppelt“ ist also eine Faustregel, kein Naturgesetz. Dass Marias Reaktion heftiger ausfällt als Toms, lässt sich damit gut erklären. Die Annahme, Gewinne wögen stärker als Verluste, passt nicht zur Beobachtung. Auch ein rein am Endvermögen orientiertes oder streng proportionales Empfinden würde erwarten lassen, dass beide gleich stark reagieren. Genau das ist hier nicht der Fall. Wer die Verlustaversion kennt, kann Marias Impuls prüfen: Sie sollte nicht verkaufen, nur um den Schmerz zu vermeiden, sondern fragen, ob sie die Aktie heute noch kaufen würde (Clean-Slate-Test).","coreRule":"⚡ Verluste wiegen vom Bezugspunkt aus meist schwerer als gleich hohe Gewinne. Prüfe deshalb, ob du entscheidest, um einen Verlust zu vermeiden, oder weil die Sache gut ist.","quote":"","quoteLabel":"","scenario":"Der Betrag der Veränderung ist in beiden Fällen identisch: 500 €. Trotzdem fällt die emotionale Reaktion sehr unterschiedlich aus.","beleg":"Werkstück B.28, Fußnote gl-b-verlust: Tversky, A.; Kahneman, D. (1992): „Advances in Prospect Theory: Cumulative Representation of Uncertainty“. Journal of Risk and Uncertainty 5(4), S. 297–323.","kurz":"Menschen bewerten Veränderungen vom Bezugspunkt aus, nicht nach dem Endstand, und ein Verlust wiegt dabei meist schwerer als ein gleich hoher Gewinn. Deshalb reagiert Maria heftiger, obwohl es um dieselben 500 € geht.","prueffrage":"Wenn beide dieselben 500 € bewegen: Woran misst jeder von beiden, ob der Tag gut oder schlecht war?","rueckmeldung":[{"option":1,"text":"Dass Gewinne stärker zählen als Verluste, würde die Lage genau umdrehen: Tom müsste dann stärker reagieren als Maria. Beobachtet wird das Gegenteil, und auch Messungen zeigen meist, dass Verluste schwerer wiegen."},{"option":2,"text":"Ein reiner Blick auf den Endstand würde bei beiden ähnlich ausfallen, denn beide stehen nahe an 10.000 €. Die verschiedenen Reaktionen erklärt das nicht, und für eine unterschiedliche „Tagesform“ gibt es keinen Hinweis."},{"option":3,"text":"Richtig ist, dass der Betrag gleich ist. Hinge das Empfinden aber strikt am Betrag, müssten beide gleich reagieren, und genau das geschieht nicht. Die Annahme beschreibt also, was die Beobachtung widerlegt."}],"familie":"verlust-und-gewinn-abwaegen","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Kahneman, D.; Knetsch, J. L.; Thaler, R. H. (1991): Anomalies: The Endowment Effect, Loss Aversion, and Status Quo Bias. Journal of Economic Perspectives 5(1), 193–206","oeffentlich":true,"doi":"10.1257/jep.5.1.193","url":"https://www.aeaweb.org/articles?id=10.1257/jep.5.1.193","abruf":"2026-10-12"},{"typ":"doi","kurz":"Brown, A. L.; Imai, T.; Vieider, F. M.; Camerer, C. F. (2024): Meta-Analysis of Empirical Estimates of Loss Aversion (Preprint MetaArXiv; Zeitschriftenfassung JEL 62(2), 485–516)","oeffentlich":true,"doi":"10.31222/osf.io/hnefr","abruf":"2026-10-12"},{"typ":"doi","kurz":"Tversky, A.; Kahneman, D. (1992): Advances in Prospect Theory: Cumulative Representation of Uncertainty. Journal of Risk and Uncertainty 5(4), 297–323","oeffentlich":false,"doi":"10.1007/BF00122574"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"9edbee400acdf790"}},{"id":"qc-1","status":"entwurf","clusterId":"C","werkstueckRef":"C.1.2","stufe":1,"question":"Ein Anbieter wirbt: „Unser Magnetmotor läuft ohne Strom und ohne Brennstoff dauerhaft und liefert nebenbei Strom für dein Haus.“ Du sollst die Behauptung prüfen. Welche Frage deckt am schnellsten auf, ob sie physikalisch möglich ist?","options":["Woher stammt die Energie, die das Gerät laufend abgibt, und wohin geht sie?","Wie viele Kundenbewertungen hat das Gerät und wie positiv fallen sie aus?","Wie neu ist die Technik und wurde sie bereits von anderen Firmen nachgebaut?","Wie leise läuft der Motor und wie viel Platz braucht er im Haus?"],"correctIndex":0,"explanation":"Jede Maschine, die dauerhaft Energie abgibt, muss sie irgendwoher beziehen: Energie wird nur umgewandelt, nie aus dem Nichts erzeugt. Ein Gerät ohne Energiezufuhr, das auch noch Strom liefert, widerspräche also dem Energieerhaltungssatz. Zudem geht bei jeder realen Umwandlung ein Teil als Wärme verloren, etwa durch Reibung, sodass selbst ein Motor, der sich nur dreht, ohne Zufuhr irgendwann stehen bleibt. Die Frage nach Herkunft und Verbleib der Energie prüft genau das. Bewertungen, Neuheit oder Lautstärke sagen nichts darüber, ob die Behauptung physikalisch möglich ist.","coreRule":"⚡ Frag bei jeder Energie-Behauptung: Wo kommt die Energie her, wo geht sie hin, und wie bezahlt das System den Preis der zunehmenden Unordnung?","quote":"","quoteLabel":"","scenario":"Auf einer Webseite wird ein „Magnetmotor“ für 499 Euro beworben. Er soll sich ohne Strom und ohne Brennstoff dauerhaft drehen und zusätzlich einen Haushalt mit Strom versorgen.","kurz":"Wer dauerhaft Energie abgibt, muss sie irgendwoher beziehen, denn Energie wird nur umgewandelt, nie erschaffen. Bewertungen, Neuheit oder Lautstärke klären das nicht; ein Gerät, das ohne jede Zufuhr Strom liefert, widerspräche dem Energieerhaltungssatz.","prueffrage":"Was müsste nach einem Jahr Dauerbetrieb im Motor fehlen oder verbraucht sein, wenn er die ganze Zeit ein Haus mit Strom versorgt hat?","rueckmeldung":[{"option":1,"text":"Viele gute Bewertungen sprechen oft für ein brauchbares Produkt. Sie sagen aber nur etwas über die Zufriedenheit der Käufer, nicht darüber, ob ein Gerät ohne Energiezufuhr dauerhaft Strom liefern kann. Das lässt sich so nicht beantworten."},{"option":2,"text":"Eine Technik kann neu oder schon vielfach kopiert sein und trotzdem nicht halten, was die Werbung verspricht. Weder Neuheit noch Nachbauten klären, ob die Energiebilanz aufgeht. Dafür braucht es die Frage nach der Energiequelle."},{"option":3,"text":"Lautstärke und Platzbedarf entscheiden, ob ein Gerät im Alltag praktisch wäre, aber nicht, ob es funktioniert. Auch ein leiser, kleiner Motor müsste seine Energie irgendwoher beziehen. Dazu sagt diese Frage nichts."}],"familie":"bilanz-pruefen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"OpenStax: University Physics Vol. 2, 3.3 First Law of Thermodynamics","oeffentlich":true,"url":"https://openstax.org/books/university-physics-volume-2/pages/3-3-first-law-of-thermodynamics","abruf":"2026-10-12"},{"typ":"url","kurz":"Ling, S. J.; Moebs, W.; Sanny, J. (2016): University Physics Vol. 2 (OpenStax), 4.7 Entropy on a Microscopic Scale","oeffentlich":true,"url":"https://openstax.org/books/university-physics-volume-2/pages/4-7-entropy-on-a-microscopic-scale","abruf":"2026-10-12"}],"thema":"Technik und KI","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"bb4d14891507bada"}},{"id":"qc-2","status":"entwurf","clusterId":"C","werkstueckRef":"C.1.4","stufe":2,"question":"Eine Kollegin behauptet: „Mars ist riesig. Dass er bei deiner Geburt am Himmel stand, hat dich geprägt, denn die Schwerkraft eines Planeten wirkt auf alles, was auf ihm lebt oder im Einflussbereich liegt.“ Welche Rückfrage prüft die Behauptung am besten?","options":["Wie stark zog der Mars im Vergleich zu den Menschen im Kreißsaal?","Wie viele Menschen, die an einem Marstag geboren wurden, glauben an den Einfluss?","Wie lange schon beschäftigen sich Menschen mit Horoskopen und Überlieferungen?","Wie groß ist der Mars insgesamt im Vergleich zu den übrigen Planeten?"],"correctIndex":0,"explanation":"Die Schwerkraft wächst mit der Masse, nimmt aber mit dem Quadrat der Entfernung ab: Verdoppelst du den Abstand, bleibt ein Viertel der Kraft, bei zehnfachem Abstand ein Hundertstel. Der Mars ist zwar riesig, aber selbst bei größter Annäherung rund 55 Millionen Kilometer entfernt. Der Geburtshelfer ist winzig, steht aber etwa einen halben Meter vom Neugeborenen entfernt. Rechnet man beides durch, zieht der Geburtshelfer meist um ein Vielfaches stärker am Baby als der Mars, und selbst bei dessen größter Annäherung ist die Kraft des Mars nicht stärker als die des Geburtshelfers. Die Behauptung lässt sich also mit einer einfachen Größenordnungsrechnung prüfen. Die anderen Fragen führen davon weg: Glaube, Tradition oder bloße Größe sagen nichts darüber, wie stark der Mars tatsächlich wirkt. Wer Masse und Abstand vergleicht, kann die Behauptung testen, statt sie nur zu bestaunen oder abzulehnen.","coreRule":"⚡ Ferne Größe schlägt nahe Kleinheit nicht automatisch: Bei einer behaupteten Fernwirkung zuerst Masse und Abstand vergleichen.","quote":"Die Gravitationskraft, eine der vier fundamentalen Kräfte des Universums, nimmt mit dem Quadrat der Entfernung ab.","quoteLabel":"Merksatz:","scenario":"Du sprichst mit einer Kollegin über Horoskope. Sie sagt, die Anziehungskraft des Mars bei der Geburt erkläre, warum manche Menschen so sind, wie sie sind.","beleg":"Werkstück C.1.4 – Gravitation & das Abstandsgesetz (Rechnung in Band II, Fußnote zur Hebamme)","kurz":"Wie stark der Mars an einem Neugeborenen zieht, lässt sich ausrechnen: Die Schwerkraft nimmt mit dem Quadrat der Entfernung ab. Der Mars ist groß, aber Millionen Kilometer weg, der Geburtshelfer winzig, aber nah. Größe allein beweist also nichts.","prueffrage":"Wie weit ist der Mars selbst bei seiner größten Annäherung von der Erde entfernt?","rueckmeldung":[{"option":1,"text":"Die Zahl der Gläubigen zu zählen sagt etwas über Überzeugungen, nicht über Kräfte. Ob der Mars tatsächlich auf Neugeborene wirkt, hängt nicht davon ab, wie viele daran glauben."},{"option":2,"text":"Eine lange Tradition erklärt, warum Horoskope so verbreitet sind. Ob die Behauptung über die Schwerkraft stimmt, lässt sich damit nicht klären, denn auch alte Überlieferungen können falsch sein."},{"option":3,"text":"Die Größe ist ein einleuchtender Ansatzpunkt, weil die Masse in die Schwerkraft eingeht. Die Kraft nimmt aber mit dem Quadrat des Abstands ab, und der bleibt beim Vergleich mit anderen Planeten völlig außen vor."}],"familie":"groessenordnung-schaetzen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"OpenStax: University Physics Vol. 1, 13.1 Newton's Law of Universal Gravitation","oeffentlich":true,"url":"https://openstax.org/books/university-physics-volume-1/pages/13-1-newtons-law-of-universal-gravitation","abruf":"2026-10-12"},{"typ":"daten","kurz":"NASA NSSDCA: Mars Fact Sheet","oeffentlich":true,"url":"https://nssdc.gsfc.nasa.gov/planetary/factsheet/marsfact.html","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"71e21bb47ffb146a"}},{"id":"qc-3","status":"entwurf","clusterId":"C","werkstueckRef":"C.2.1","stufe":2,"question":"Eine Verkäuferin sagt: „Dieses Mittel ist eine C30-Potenz. Es wurde dreißigmal im Verhältnis 1 zu 100 verdünnt, enthält aber noch den vollen Wirkstoff der Ausgangssubstanz, nur eben feiner verteilt.“ Welche Überlegung prüft diese Behauptung am besten?","options":["Man rechnet nach, wie viele Moleküle der Ausgangssubstanz bei dieser Verdünnung im Mittel noch übrig sein können, denn Materie besteht aus einzelnen Teilchen und ist nicht unendlich teilbar.","Man fragt, ob die Verkäuferin für ihre Aussage ein Zertifikat vorweisen kann, denn nur dann ist die Herstellungsangabe vertrauenswürdig.","Man prüft, ob das Mittel schon lange verkauft wird, denn ein Mittel, das sich über Jahre hält, muss einen stofflichen Wirkstoff enthalten.","Man nimmt das Mittel selbst eine Woche lang und beobachtet, ob es einem besser geht, denn das eigene Empfinden zeigt zuverlässig, ob ein Wirkstoff enthalten ist."],"correctIndex":0,"explanation":"Die Behauptung lässt sich ohne Autoritäten und ohne Selbstversuch prüfen: durch Nachrechnen. Ein Mol eines Stoffes enthält etwa 6 × 10²³ Teilchen (Avogadro-Konstante). Bei C12 (1 zu 10²⁴) enthält ein Mol des Endprodukts im Mittel nur noch etwa 0,6 Moleküle der Ausgangssubstanz. C30 bedeutet 1 zu 10⁶⁰, also weit jenseits dieser Grenze. Bei einer einmolaren Urtinktur bräuchte man für im Mittel ein einziges Molekül eine Lösungskugel mit etwa dem Durchmesser Erde–Sonne (rund 150 Millionen km). Die Aussage „enthält noch den vollen Wirkstoff, nur feiner verteilt“ scheitert also an der Teilchennatur der Materie. Ein Zertifikat, die Verkaufsdauer oder das eigene Befinden nach einer Woche sagen nichts darüber, ob Moleküle vorhanden sind: Ein Zertifikat beweist keine Chemie, langer Verkauf beweist keine Wirkung, und das Befinden wird von Erwartung und natürlichem Krankheitsverlauf mitbestimmt.","coreRule":"⚡ Behauptungen über Stoffe lassen sich nachrechnen: Materie ist nicht unendlich teilbar, und ab einer bestimmten Verdünnung ist statistisch kein Teilchen mehr da.","quote":"","quoteLabel":"","scenario":"Du stehst in einer Apotheke und liest die Beschreibung eines Mittels. Die Verkäuferin erklärt dir die Herstellung der C30-Potenz.","beleg":"Werkstück C.2.1, Fußnoten gl-c-avogadro und gl-c-c30: Rademacher, P. (2013): „Die Mär vom Wasser mit Gedächtnis“. Chemie in unserer Zeit 47(1), S. 24–31","kurz":"Die Behauptung lässt sich nachrechnen, weil Materie aus Teilchen besteht. Bei 1 zu 10⁶⁰ bleibt im Mittel kein einziges Molekül übrig. Zertifikat, Verkaufsdauer oder Befinden sagen darüber nichts, denn sie messen nicht, was im Fläschchen ist.","prueffrage":"Wie viel vom Ausgangsstoff kommt am Ende an, wenn man dreißigmal hintereinander jeweils nur ein Hundertstel weitergibt?","rueckmeldung":[{"option":1,"text":"Nach einem Beleg zu fragen ist grundsätzlich klug. Ein Zertifikat zeigt aber höchstens, dass ein Verfahren eingehalten wurde. Ob nach dreißigmaliger Verdünnung noch Wirkstoff vorhanden ist, entscheidet sich an der Zahl der Teilchen."},{"option":2,"text":"Ein Mittel, das über Jahre im Regal steht, wirkt erprobt. Die Verkaufsdauer sagt aber nur etwas über Nachfrage und Gewohnheit. Ob Moleküle im Fläschchen sind, hängt nicht davon ab, wie lange es verkauft wird."},{"option":3,"text":"Das eigene Befinden lässt sich ohne Aufwand beobachten, und das macht den Selbstversuch so einleuchtend. Es wird aber von Erwartung und natürlichem Krankheitsverlauf mitbestimmt und zeigt deshalb nicht verlässlich, ob ein Wirkstoff enthalten ist."}],"familie":"verduennung-nachrechnen","fertigkeit":"F4","quellen":[{"typ":"daten","kurz":"NIST CODATA: Avogadro constant","oeffentlich":true,"url":"https://physics.nist.gov/cgi-bin/cuu/Value?na","abruf":"2026-10-12"},{"typ":"url","kurz":"EASAC (2017): Homeopathic products and practices: assessing the evidence and ensuring consistency in regulating medical claims in the EU","oeffentlich":true,"url":"https://www.interacademies.org/sites/default/files/2020-04/easac_homepathy_statement_web_final.pdf","seite":"5","abruf":"2026-10-12"},{"typ":"doi","kurz":"Rademacher, P. (2013): Die Mär vom Wasser mit Gedächtnis. Chemie in unserer Zeit 47(1), 24–31","oeffentlich":false,"doi":"10.1002/ciuz.201300580"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"ba45d4223bb3ee5c"}},{"id":"qc-4","status":"entwurf","clusterId":"C","werkstueckRef":"C.4.2","stufe":1,"question":"Welche Frage solltest du als Erstes klären, bevor du bei einer Infektion über ein Antibiotikum entscheidest?","options":["Ob die Beschwerden stark genug sind, dass der Körper allein damit nicht fertig wird.","Ob die Infektion von Bakterien oder von Viren verursacht wird.","Ob der Mann schon einmal ein Antibiotikum vertragen hat.","Ob die Infektion schon länger als ein paar Tage andauert."],"correctIndex":1,"explanation":"Entscheidend ist nicht, ob eine Infektion vorliegt, sondern welcher Erreger dahintersteckt. Antibiotika greifen Strukturen an, die Bakterien haben, menschliche Zellen aber nicht, etwa die Zellwand. Viren besitzen weder Zellwand noch eigenen Stoffwechsel, sie sind genetische Pakete, die fremde Zellen zur Vervielfältigung nutzen. Bei einer gewöhnlichen Erkältung (virale Ursache) hat ein Antibiotikum also nichts, woran es angreifen könnte. Es nützt nicht, kann aber schaden: Es tötet empfindliche Bakterien im Körper und begünstigt die wenigen zufällig resistenten, die überleben und sich vermehren. Schwere Beschwerden, frühere Verträglichkeit oder die Dauer sind Nebenfragen. Sie sagen nichts darüber, ob ein Antibiotikum überhaupt wirken kann.","coreRule":"⚡ Bevor du eine Behandlung wählst, kläre, was der Angreifer ist: Das Wort „Infektion“ allein sagt noch nichts darüber, welches Mittel hilft.","quote":"„Ich habe eine Infektion, also brauche ich Antibiotika.“","quoteLabel":"Typischer Fehlschluss","scenario":"Ein Mann mit laufender Nase, Halsschmerzen und Abgeschlagenheit sagt zu seiner Ärztin: „Ich habe eine Infektion, also brauche ich Antibiotika.“ Die Ärztin lehnt ab.","beleg":"Werkstück C.4.2, Abschnitt „Die vergebliche Medikation“ und „Kontext & Tiefe“ (Bakterien: Antibiotika greifen z. B. die Zellwand an; Viren: keine Zellwand, kein eigener Stoffwechsel; Resistenzen durch unnötigen Einsatz).","kurz":"Entscheidend ist der Erreger, nicht die Infektion an sich: Antibiotika treffen Bakterien, bei Viren (wie bei einer Erkältung) finden sie keinen Angriffspunkt. Der Fehler liegt darin, „Infektion“ mit „Antibiotikum nötig“ gleichzusetzen.","prueffrage":"Was genau steckt hinter dem Wort „Infektion“, und gilt das für alle Infektionen gleich?","rueckmeldung":[{"option":0,"text":"Wie schwer die Beschwerden sind, ist bei der Behandlung durchaus wichtig. Sie verraten aber nicht, ob ein Antibiotikum überhaupt angreifen kann: Auch eine heftige Viruserkrankung bleibt für ein Antibiotikum unerreichbar."},{"option":2,"text":"Frühere Verträglichkeit ist eine sinnvolle Frage, sobald ein Antibiotikum ernsthaft in Betracht kommt. Sie betrifft aber nur die Sicherheit, nicht die Wirkung, und sagt nichts darüber, ob es hier etwas bewirken kann."},{"option":3,"text":"Eine lange Dauer kann ein Hinweis sein, dass mehr dahintersteckt, und wird deshalb oft beachtet. Sie beantwortet aber nicht direkt, ob die Ursache ein Erreger ist, an dem ein Antibiotikum überhaupt ansetzen kann."}],"familie":"genau-unterscheiden","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"IQWiG, gesundheitsinformation.de: Erkältung","oeffentlich":true,"url":"https://www.gesundheitsinformation.de/erkaeltung.html","abruf":"2026-10-12"},{"typ":"url","kurz":"Mobley 2006, How do antibiotics kill bacterial cells but not human cells?, Scientific American","oeffentlich":true,"url":"https://www.scientificamerican.com/article/how-do-antibiotics-kill-b/","abruf":"2026-10-12"},{"typ":"url","kurz":"MSD Manual (Consumer Version): Overview of Antibiotics","oeffentlich":true,"url":"https://www.msdmanuals.com/home/infections/antibiotics/overview-of-antibiotics","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"0a3a768a4bfad652"}},{"id":"qc-5","status":"entwurf","clusterId":"C","werkstueckRef":"C.5.4","stufe":3,"question":"Was ist an diesem Argument der entscheidende Fehler?","options":["Die Prämisse ist falsch gewählt: Das Feuer war in Wirklichkeit heißer als 1500 °C, sodass der Stahl doch schmolz und das Gebäude daraufhin einstürzte.","Die Prämisse ist richtig, aber der Schluss unterstellt, Stahl müsse schmelzen, um zu versagen. Schon weit unter dem Schmelzpunkt verliert er einen Großteil seiner Tragfähigkeit.","Die Prämisse ist richtig, aber der Brand war ohnehin unerheblich, weil der Aufprall der Flugzeuge die Tragstruktur allein vollständig zerstört hat.","Die Prämisse ist richtig, aber der Stahl war durch jahrzehntelange Korrosion so geschwächt, dass schon ein kleiner Brand ausreichte, um ihn zu zerstören."],"correctIndex":1,"explanation":"Das Argument prüft die falsche Größe. Dass Stahl bei 800–1000 °C nicht schmilzt, stimmt, ist aber unerheblich: Ein Träger muss nicht flüssig werden, um zu versagen, es genügt, dass er die Last nicht mehr trägt. Baustahl verliert schon bei 600–800 °C über die Hälfte seiner Tragfähigkeit; bei etwa 800 °C bleibt rund ein Zehntel, bei 1000 °C nur noch wenige Prozent. Geschwächte Träger biegen sich durch und knicken aus; gibt ein Stockwerk nach, stürzt der obere Gebäudeteil auf das darunterliegende, und die dynamische Belastung übersteigt die statische Last, für die ein Gebäude ausgelegt ist, um ein Vielfaches (progressiver Kollaps). Das erklärt den Einsturz bereits vollständig; eine Sprengung wird nur durch den unbegründeten Zwischenschritt „Stahl muss schmelzen“ scheinbar nötig.","coreRule":"⚡ Ein Bauteil muss nicht schmelzen, um zu versagen: Prüfe, ob die Prämisse des Gegenarguments überhaupt zur Schlussfolgerung passt.","quote":"","quoteLabel":"","scenario":"In einer Diskussion über den Einsturz eines Hochhauses, in dem nach einem Flugzeugeinschlag und dem Abschlagen des Brandschutzes ein Großbrand wütete, argumentiert jemand: „Kerosinfeuer erreicht höchstens 800–1000 °C, Stahl schmilzt aber erst bei etwa 1500 °C. Also kann das Feuer den Einsturz nicht verursacht haben, es muss eine Sprengung gewesen sein.“","kurz":"Das Argument prüft die falsche Größe: Stahl muss nicht schmelzen, um zu versagen. Schon bei 600–800 °C verliert er über die Hälfte seiner Tragfähigkeit, und geschwächte Träger knicken ein. Der Schmelzpunkt ist für den Einsturz schlicht nicht der Maßstab.","prueffrage":"Was wurde beim Einschlag abgeschlagen, und wozu ist es an den Stahlträgern eines Hochhauses angebracht?","rueckmeldung":[{"option":0,"text":"Dass der Brand zum Einsturz beitrug, stimmt. Für über 1500 °C und geschmolzenen Stahl gibt es aber keinen Beleg, und nötig sind sie nicht: Der Fehler liegt woanders, denn um zu versagen, musste der Stahl gar nicht schmelzen."},{"option":2,"text":"Der Einschlag hat sicher Schaden angerichtet, doch danach wütete im noch stehenden Gebäude ein Großbrand; ihn für unerheblich zu erklären, passt dazu nicht. Vor allem verfehlt das den Fehler: Das Argument setzt Versagen mit Schmelzen gleich."},{"option":3,"text":"Für jahrzehntelange Korrosion gibt es keinen Hinweis, sie wäre eine zusätzliche Annahme, und es brannte kein kleines Feuer, sondern ein Großbrand. Der Fehler liegt im Argument selbst: Es verwechselt Schmelzen mit dem Verlust der Tragfähigkeit."}],"familie":"schluss-pruefen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"NIST: FAQs – NIST WTC Towers Investigation","oeffentlich":true,"url":"https://www.nist.gov/world-trade-center-investigation/study-faqs/wtc-towers-investigation","abruf":"2026-10-12"},{"typ":"literatur","kurz":"NIST (2005): Final Report on the Collapse of the World Trade Center Towers (NCSTAR 1)","oeffentlich":false}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"31973a4bffd5f161"}},{"id":"qc-6","status":"entwurf","clusterId":"C","werkstueckRef":"C.5.6","stufe":3,"question":"Welche Folgerung ist am besten begründet?","options":["Das Fehlen einer offensichtlichen Zündquelle beweist, dass es keine gab; der Körper muss sich daher von innen entzündet haben.","Dass der Raum unversehrt blieb, zeigt, dass kein gewöhnliches Feuer beteiligt war; sonst hätte es sich ausgebreitet.","Eine kleine äußere Zündquelle kann die Kleidung entzündet haben; danach brannte Körperfett über Stunden langsam am Stoff weiter, ohne den Raum zu erfassen.","Je vollständiger ein Körper verbrennt, desto heißer muss das Feuer gewesen sein; dann hätte der ganze Raum brennen müssen."],"correctIndex":2,"explanation":"Der Film schließt von „ich sehe keine Ursache“ auf „es gab keine Ursache“. Das ist ein Fehlschluss: Eine Zigarette, Kerze oder ein Funke ist schnell übersehen, vor allem wenn das Feuer sie selbst verzehrt hat. Auch die unversehrte Umgebung spricht nicht gegen ein normales Feuer. Sie passt zu einem Feuer, das klein und langsam brennt: Schmelzendes Körperfett wird von verkohlter Kleidung aufgesaugt und brennt dort wie an einem Kerzendocht, nur eben umgekehrt, weil der Brennstoff innen liegt. Experimentell ließ sich das nachstellen: Ein in eine Baumwolldecke gewickelter Schweinekadaver (DeHaan und Nurbakhsh, 2001), mit Benzin entzündet, brannte mehr als 6,5 Stunden von selbst weiter; als die Forscher es löschten, waren bereits über 60 Prozent des Tierkörpers zerstört. Eine bekannte, reproduzierbare Erklärung braucht keine neue, geheimnisvolle Ursache.","coreRule":"⚡ Keine sichtbare Ursache heißt nicht: keine Ursache. Eine Erklärung mit bekannter Physik schlägt „unerklärlich“.","quote":"Kein Zauberfeuer: Banale Zündquelle + stundenlanger Schwelbrand = Dochteffekt.","quoteLabel":"Merksatz:","scenario":"Eine Dokumentation zeigt den Fall einer älteren Frau, die in ihrer Wohnung fast vollständig zu Asche verbrannt ist. Der Sessel darunter ist zerstört, aber die übrige Einrichtung ist kaum beschädigt. Im Film heißt es: „Ohne erkennbare Zündquelle und ohne Brandschäden im Raum kann das nur eine spontane Selbstentzündung gewesen sein.“","beleg":"Werkstück C.5.6, Fußnoten gl-c-reeser, gl-c-dehaan; Red Flags und Anti-Denkmuster","kurz":"Ein kleiner Funke oder eine Zigarette ist schnell übersehen, vor allem wenn das Feuer sie selbst verzehrt hat. Daraus, dass man keine Ursache sieht, folgt nicht, dass es keine gab; ein langsam brennendes Feuer erklärt auch den unversehrten Raum.","prueffrage":"Welche Gegenstände in der Wohnung sind verbrannt und welche nicht, und wie weit standen sie vom Sessel entfernt?","rueckmeldung":[{"option":0,"text":"Dass keine Zündquelle zu sehen ist, wirkt wie ein Beleg für ihr Fehlen. Eine Zigarette, Kerze oder ein Funke ist aber schnell übersehen, zumal wenn das Feuer sie selbst verzehrt hat. Der Schluss auf eine Entzündung von innen hat keinen Halt."},{"option":1,"text":"Ein kaum beschädigter Raum wirkt wie ein Widerspruch zu einem gewöhnlichen Feuer. Das ist er nicht: Ein kleines, langsames Feuer breitet sich kaum aus, etwa wenn schmelzendes Körperfett an verkohlter Kleidung wie an einem Docht brennt."},{"option":3,"text":"Große Hitze in kurzer Zeit hätte den Raum tatsächlich erfasst. Ein Körper kann aber auch durch ein kleines Feuer zerstört werden, das über Stunden brennt: Ein in eine Decke gewickelter Schweinekadaver brannte im Versuch mehr als 6,5 Stunden weiter."}],"familie":"bekannte-ursache-zuerst","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"DeHaan, J. D.; Nurbakhsh, S. (2001): Sustained Combustion of an Animal Carcass and Its Implications for the Consumption of Human Bodies in Fires. J Forensic Sci 46(5):1076–1081 – PubMed-Abstract","oeffentlich":true,"url":"https://pubmed.ncbi.nlm.nih.gov/11569545/","abruf":"2026-10-12"},{"typ":"doi","kurz":"DeHaan, J. D.; Nurbakhsh, S. (2001): Sustained Combustion of an Animal Carcass … J Forensic Sci 46(5) (Volltext kostenpflichtig)","oeffentlich":false,"doi":"10.1520/JFS15101J"},{"typ":"url","kurz":"Christensen, A. M. (2000): Debunking the Spontaneous Human Combustion Myth: Experiments in the Combustibility of the Human Body. Masterarbeit, University of Tennessee (TRACE)","oeffentlich":true,"url":"https://trace.tennessee.edu/utk_gradthes/4133","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"6e78c3d79f9c767b"}},{"id":"qc-7","status":"entwurf","clusterId":"C","werkstueckRef":"C.1.3","stufe":1,"question":"Bei der Frage nach unserer Herkunft sagt jemand: „Wir sind aus Sternenstoff gemacht? Das ist doch nur eine hübsche Metapher, so wie ‚Wir sind alle eins‘.“ Welche Antwort zeigt am besten, dass die Aussage wörtlich und nachprüfbar gemeint ist?","options":["Das Universum bestand anfangs fast nur aus Wasserstoff und Helium; Kohlenstoff und Sauerstoff entstanden später durch Kernfusion in Sternen und wurden durch Sternexplosionen verteilt. Die Atome in deinem Körper waren also tatsächlich einmal Teil von Sternen.","Das Universum brachte beim Urknall alle Elemente des Periodensystems in ähnlichen Anteilen hervor; Sterne haben sie später nur auf Planeten verteilt. Die Atome in deinem Körper stammen also aus der Frühzeit des Kosmos.","Auf der jungen Erde bildeten Vulkane und Blitze aus Wasserstoff und Helium die schwereren Elemente; erst danach entstand Leben. Die Atome in deinem Körper wurden also auf der Erde selbst erzeugt.","Meteoriten haben die schweren Elemente aus fernen Galaxien auf die Erde gebracht, wo sie sich im Boden anreicherten. Die Atome in deinem Körper kommen also von außerhalb unserer Milchstraße."],"correctIndex":0,"explanation":"Die Aussage lässt sich an Beobachtungen prüfen: Das frühe Universum bestand fast nur aus Wasserstoff (etwa 75 %) und Helium (etwa 25 %). Kohlenstoff, Sauerstoff, Eisen und alles andere Schwere gab es nicht und musste erst entstehen. Kohlenstoff, Sauerstoff und Eisen entstehen durch Kernfusion in Sternen und ihren Explosionen; sehr schwere Elemente wie Gold großenteils auch bei Neutronensternkollisionen. Sternexplosionen und Sternwinde streuen die neuen Elemente ins All, wo sie in spätere Gaswolken, Sterne und Planeten eingehen. Wer Kohlenstoff und Sauerstoff im Körper hat, trägt damit den Beleg in sich, dass in unserer galaktischen Nachbarschaft mindestens ein massereicher Stern gelebt hat und gestorben ist. Das ist keine Metapher, sondern eine überprüfbare Herkunftsgeschichte der Materie. Die Alternativen scheitern an derselben Prüffrage: Ein Urknall mit allen Elementen widerspricht der beobachteten Zusammensetzung des frühen Universums, und auf der Erde fehlen Druck und Temperatur für Fusion. Auch Meteoriten aus fernen Galaxien erklären nichts; die schweren Elemente entstehen in Sternen und werden von dort in Gaswolken verteilt, aus denen neue Planeten entstehen.","coreRule":"⚡ Wer „Metapher“ sagt, muss prüfen, ob sich die Aussage nicht doch wörtlich belegen lässt: Wir sind nicht von den Sternen beeinflusst, sondern aus ihnen gemacht.","quote":"","quoteLabel":"","scenario":"Ein Gespräch über Esoterik und Wissenschaft: Eine Person hält „Wir sind aus Sternenstoff gemacht“ für eine rein poetische Redewendung ohne Tatsachengehalt.","beleg":"Werkstück C.1.3; Haupttext sowie Abschnitt „Kontext & Tiefe“ (Supernova/Sternwinde); Fn gl-c-elementherkunft (Kobayashi et al. 2020); Fn gl-c-nukleosynthese (Tyson/Gott/Strauss 2022; Schwedt 2014).","kurz":"Die Aussage ist wörtlich prüfbar: Das frühe Universum bestand fast nur aus Wasserstoff und Helium, Kohlenstoff und Sauerstoff entstanden erst in Sternen. Bei einer Metapher ließe sich nichts messen; hier gibt es Beobachtungen, die man nachprüfen kann.","prueffrage":"Welche Stoffe gab es kurz nach dem Urknall überhaupt, und woher soll der Rest stammen?","rueckmeldung":[{"option":1,"text":"Die Atome sind tatsächlich uralt und kosmischen Ursprungs, das stimmt. Beobachtet wird beim frühen Universum aber fast nur Wasserstoff und Helium; Kohlenstoff, Sauerstoff und Eisen mussten erst in Sternen entstehen."},{"option":2,"text":"Dass Leben erst nach den Elementen entstand, stimmt. Vulkane und Blitze verwandeln aber keinen Wasserstoff in schwerere Elemente: Dafür braucht es Kernfusion, und für sie fehlen auf der Erde Druck und Temperatur."},{"option":3,"text":"Meteoriten bringen tatsächlich Material auf die Erde. Der Verweis auf ferne Galaxien verschiebt die Frage aber nur, denn er erklärt nicht, wo schwere Elemente entstehen: in Sternen, auch in unserer eigenen Milchstraße."}],"familie":"genau-unterscheiden","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Fields, B. D.; Molaro, P.; Sarkar, S.: Big Bang Nucleosynthesis (rev. Aug. 2023). In: Particle Data Group, Review of Particle Physics 2024, Kap. 24","oeffentlich":true,"url":"https://pdg.lbl.gov/2024/reviews/rpp2024-rev-bbang-nucleosynthesis.pdf","abruf":"2026-10-12"},{"typ":"doi","kurz":"Kobayashi, C.; Karakas, A. I.; Lugaro, M. (2020): The Origin of Elements from Carbon to Uranium. ApJ 900(2), 179","oeffentlich":true,"doi":"10.3847/1538-4357/abae65","url":"https://arxiv.org/abs/2008.04660","abruf":"2026-10-12"},{"typ":"url","kurz":"NASA Imagine the Universe!: Supernovae","oeffentlich":true,"url":"https://imagine.gsfc.nasa.gov/science/objects/supernovae1.html","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"8f8608c79943b0af"}},{"id":"qc-8","status":"entwurf","clusterId":"C","werkstueckRef":"C.1.5","stufe":2,"question":"Du liest die Schlagzeile: „Fossilienfund beweist: Die Gesteinsschicht ist genau 410 Millionen Jahre alt.“ Welche Rückfrage prüft am besten, wie belastbar diese Altersangabe ist?","options":["Wurde das Alter über den Zerfall radioaktiver Isotope gemessen, oder stützt es sich nur auf Schichtenfolge und Fossilien?","Wie viele Fachleute haben den Fund bei einer Pressekonferenz mit „beeindruckend“ kommentiert, und wie bekannt sind sie?","Wie dick ist die Schicht, und wie schnell lagert ein heutiger Fluss pro Jahr Sediment ab? Daraus ließe sich das Alter hochrechnen.","Wie warm ist das Gestein heute, und liegt es tiefer als vergleichbare Funde aus derselben Gegend?"],"correctIndex":0,"explanation":"Schichtenfolge und Fossilien ordnen nur die Reihenfolge: In ungestörten Schichten liegt das Ältere unten. Konkrete Jahreszahlen stammen aus radiometrischer Datierung, etwa der Uran-Blei-Methode, die den gleichmäßigen, vorhersagbaren Zerfall radioaktiver Isotope wie eine Stoppuhr nutzt. Wer eine Altersangabe prüfen will, fragt deshalb nach der Methode hinter der Zahl. Schichtdicke geteilt durch eine heutige Ablagerungsrate liefert keine belastbare Jahreszahl, weil Ablagerung ungleichmäßig verlief, mit Pausen und Abtragung; die Tiefenlage ergibt wie die Schichtenfolge nur ein Älter oder Jünger, und die heutige Gesteinstemperatur sagt über das Alter nichts. Der Beifall von Fachleuten ist keine Messung.","coreRule":"⚡ Schichten ordnen die Reihenfolge, Isotope liefern die Jahre: Frag bei jeder Altersangabe nach der Messmethode.","quote":"","quoteLabel":"","scenario":"Ein Nachrichtenportal berichtet über den Fund eines Fossils in einer Gesteinsschicht. Der Artikel nennt ein exaktes Alter in Jahren, erklärt aber nicht, woher es stammt.","beleg":"Werkstück C.1.5, Abschnitt „Kontext & Tiefe“ (Buch der Gesteine, Atomare Uhr); Fn. gl-c-erdalter (Dalrymple 2001) für die übereinstimmenden Datierungen","kurz":"Eine exakte Jahreszahl stammt nicht aus der Schichtenfolge, die nur ein Älter oder Jünger ordnet, sondern aus dem Zerfall radioaktiver Isotope, der wie eine Stoppuhr läuft. Wer eine Altersangabe prüft, fragt nach der Methode hinter der Zahl.","prueffrage":"Woran lässt sich in der Meldung erkennen, wie aus dem Fund eine Zahl in Millionen Jahren wurde?","rueckmeldung":[{"option":1,"text":"Lob von bekannten Fachleuten wirkt wie ein Gütesiegel. Wie sicher eine Jahreszahl ist, zeigt sich aber nicht am Beifall, sondern daran, womit sie gemessen wurde: Eine Stimmung ist keine Messung."},{"option":2,"text":"Eine Rechnung mit Schichtdicke und Ablagerungsrate wirkt greifbar. Heutige Raten taugen aber nicht als Maßstab für die ganze Erdgeschichte, denn Ablagerung verlief ungleichmäßig, mit Pausen und Abtragung. Eine belastbare Jahreszahl ergibt das nicht."},{"option":3,"text":"Die Tiefenlage verrät tatsächlich etwas: In ungestörten Schichten liegt das Ältere unten. Das ergibt aber nur eine Reihenfolge, keine Jahreszahl, und die heutige Wärme des Gesteins sagt über sein Alter nichts."}],"familie":"groessenordnung-schaetzen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"USGS: Geologic Time – Relative Time Scale","oeffentlich":true,"url":"https://pubs.usgs.gov/gip/geotime/relative.html","abruf":"2026-10-12"},{"typ":"url","kurz":"USGS: Geologic Time – radiometrische Zeitskala","oeffentlich":true,"url":"https://pubs.usgs.gov/gip/geotime/radiometric.html","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"f60874f7380d9dbb"}},{"id":"qc-9","status":"entwurf","clusterId":"C","werkstueckRef":"C.1.6","stufe":2,"question":"Welcher Einwand trifft die Schwachstelle dieser Behauptung am besten?","options":["Außerirdische Zivilisationen kann es nicht geben, weil Leben bisher nur auf der Erde nachgewiesen wurde und deshalb anderswo nicht entstanden sein kann.","Regelmäßige Besuche wären nur plausibel, wenn die Reise leicht wäre; sie verlangt aber gewaltige Energie, Zeit und Ressourcen, und „sicher längst gelöst“ nennt keinen Mechanismus.","Die Erdatmosphäre zerstört jedes fremde Raumschiff beim Eintritt, sodass Besucher selbst mit weit fortgeschrittener Technik nie unbeschadet landen könnten.","Wer so lange unterwegs ist, altert durch die Zeitdilatation um Jahrhunderte und käme bei der Ankunft längst tot an, ganz gleich, wie schnell das Schiff fliegt."],"correctIndex":1,"explanation":"Der Einwand muss die Behauptung dort treffen, wo sie ihre Last trägt: Sie setzt voraus, dass Reisen zwischen Sternen mühelos möglich sind. Nichts mit Masse erreicht die Lichtgeschwindigkeit (rund 300.000 km/s), die Milchstraße misst etwa 100.000 Lichtjahre, und selbst Tausende Zivilisationen lägen im Schnitt Tausende Lichtjahre auseinander. Schon mit der schnellsten menschlichen Sonde (rund 690.000 km/h, und diese Geschwindigkeit erreicht sie nur im Sturz auf die Sonne zu) dauerte der Weg zum nächsten Stern (gut 4 Lichtjahre) etwa 6.600 Jahre. „Die haben das sicher gelöst“ ist ein Argument aus Unwissenheit: Es nennt keinen Mechanismus und verschiebt die Beweislast. Die anderen Einwände scheitern selbst: Aus „bisher nur auf der Erde nachgewiesen“ folgt nicht „anderswo unmöglich“, und Leben jenseits der Erde ist ein ernsthaftes Forschungsfeld (Astrobiologie, SETI). Dass die Erdatmosphäre jedes fremde Raumschiff zerstört, ist eine Behauptung ohne Beleg; als echte Hürden der interstellaren Reise gelten Energie, Zeit und Ressourcen. Und die Zeitdilatation verkürzt die erlebte Reisezeit für die Reisenden; mehr Zeit vergeht für die Daheimgebliebenen.","coreRule":"⚡ Prüfe, welche Annahme eine Behauptung stillschweigend voraussetzt; „sicher irgendwie gelöst“ ersetzt keinen Mechanismus.","quote":"","quoteLabel":"","scenario":"Ein Podcast-Gast sagt: „Unzählige Sichtungen zeigen, dass uns Außerirdische ständig besuchen. Eine Zivilisation, die so alt ist, hat das Reisen sicher längst im Griff.“","kurz":"Die Behauptung ständiger Besuche setzt voraus, dass Reisen zwischen Sternen leicht ist, doch Entfernungen, Energie und Zeit sind gewaltig. „Sicher längst gelöst“ nennt keinen Mechanismus und verschiebt die Beweislast auf die Zweifelnden.","prueffrage":"Wie lange bräuchte man für die Strecke zum nächsten Stern, wenn man die schnellste Sonde der Menschheit zugrunde legt?","rueckmeldung":[{"option":0,"text":"Dass Leben bisher nur von der Erde bekannt ist, klingt nach einem Argument. Aus „noch nicht nachgewiesen“ folgt aber nicht „unmöglich“, und die Frage nach Außerirdischen ist legitim. Zu prüfen ist, was die Behauptung über das Reisen voraussetzt."},{"option":2,"text":"Eine Hürde bei der Ankunft klingt greifbar. Es gibt aber keinen Beleg, dass die Atmosphäre jedes Raumschiff zerstört, denn Kapseln und Sonden treten kontrolliert ein. Die eigentlichen Schwierigkeiten liegen bei Energie, Zeit und Ressourcen der Reise."},{"option":3,"text":"Zeitdilatation klingt nach einem physikalisch soliden Einwand. Sie wirkt aber andersherum: Für die Reisenden vergeht weniger Zeit als für die Daheimgebliebenen. Dass sie bei der Ankunft tot wären, folgt daraus nicht."}],"familie":"mechanismus-verlangen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"OpenStax: University Physics Vol. 3, 5.9 Relativistic Energy","oeffentlich":true,"url":"https://openstax.org/books/university-physics-volume-3/pages/5-9-relativistic-energy","abruf":"2026-10-12"},{"typ":"url","kurz":"NASA Science: Parker Solar Probe (Missionsseite)","oeffentlich":true,"url":"https://science.nasa.gov/mission/parker-solar-probe/","abruf":"2026-10-12"},{"typ":"url","kurz":"NASA Imagine the Universe!: The Nearest Neighbor Star","oeffentlich":true,"url":"https://imagine.gsfc.nasa.gov/features/cosmic/nearest_star_info.html","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"fb8dc7e9231a76fe"}},{"id":"qc-10","status":"entwurf","clusterId":"C","werkstueckRef":"C.3.3","stufe":2,"question":"Ein Kritiker sagt: „Evolution ist reiner Zufall, und durch reinen Zufall entsteht kein Auge.“ Welcher Einwand trifft seinen Denkfehler am genauesten?","options":["Die Entwicklung folgt einem Ziel, das sich aus den Bedürfnissen der Art ergibt und Mutationen gezielt in diese Richtung lenkt, bis das gewünschte Organ fertig ist.","Zufällig ist nur die Entstehung neuer Varianten, die Auswahl nicht: Die Umwelt filtert nach Überleben und Fortpflanzung, und kleine Vorteile bauen sich Schritt für Schritt auf.","Der Zufall spielt keine Rolle, weil Mutationen von Umweltreizen ausgelöst werden und deshalb meist von Anfang an nützlich sind, sodass keine Auslese nötig ist.","Der Zufall wirkt nur in kleinen Gruppen, in großen Populationen gleichen sich Mutationen gegenseitig vollständig aus, sodass dort keine Veränderung entsteht."],"correctIndex":1,"explanation":"Der Kritiker setzt den Prozess mit seiner ersten Hälfte gleich. Mutation und Neukombination von Genen erzeugen ungerichtete Variation: Eine Mutation ist an sich weder gut noch schlecht. Danach arbeitet die Umwelt als nicht-zufälliger Filter, denn wer mit einem Merkmal besser überlebt und sich häufiger fortpflanzt, gibt es öfter weiter. Über viele Generationen summieren sich winzige Vorteile, ohne dass jemand ein Ziel oder einen Plan hätte (der Biologe Richard Dawkins nannte das den „blinden Uhrmacher“). Die Wahrscheinlichkeit, dass ein Auge auf einen Schlag durch Würfeln entsteht, ist verschwindend gering. Aber genau das behauptet niemand, und der Kritiker bekämpft damit einen Strohmann. Auch die anderen Antworten scheitern: Ein Ziel oder eine Lenkung durch Bedürfnisse gibt es nicht, Mutationen sind völlig ungerichtet und von vornherein weder gut noch schlecht, also nicht von Anfang an nützlich; ob sie nützen, zeigt sich erst durch die Selektion. Und der Zufall der Variation wirkt nicht nur in kleinen Gruppen, sondern in jeder Population als Quelle neuer Merkmale; für Anpassung sorgt dagegen beständig nur die Selektion.","coreRule":"⚡ Evolution ist die nicht-zufällige Auswahl von zufälligen Variationen.","quote":"","quoteLabel":"","scenario":"","kurz":"Zufällig ist nur die Entstehung neuer Varianten; was bleibt, filtert die Umwelt nach Überleben und Fortpflanzung. Der Kritiker setzt den ganzen Prozess mit seiner ersten Hälfte gleich, obwohl sich kleine Vorteile Schritt für Schritt summieren.","prueffrage":"Gibt es bei heutigen Tieren Augen in vielen Abstufungen, vom lichtempfindlichen Fleck bis zum Linsenauge, und nützt schon die einfachste Stufe?","rueckmeldung":[{"option":0,"text":"Dass Arten gut an ihre Umwelt angepasst sind, lässt ein Ziel vermuten. Mutationen entstehen aber ungerichtet, ohne Plan oder Bedürfnis. Die Anpassung kommt erst dadurch zustande, dass vorteilhafte Varianten häufiger weitergegeben werden."},{"option":2,"text":"Die Umwelt spielt tatsächlich eine große Rolle, aber nicht als Auslöser nützlicher Mutationen. Mutationen sind ungerichtet und an sich weder gut noch schlecht; ob sie nützen, zeigt sich erst bei der Auslese, und ohne Auslese gäbe es keine Anpassung."},{"option":3,"text":"Zufallseffekte hängen tatsächlich von der Gruppengröße ab, doch die Variation durch Mutation entsteht in jeder Population. Sie gleicht sich nicht vollständig aus, sondern liefert den Rohstoff, aus dem die Selektion auswählt."}],"familie":"auslese-statt-plan","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"University of California Museum of Paleontology, Understanding Evolution: „Misconceptions about evolution“ (Abschnitte a2 und b1)","oeffentlich":true,"url":"https://evolution.berkeley.edu/teach-evolution/misconceptions-about-evolution/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Campbell, N. A.; Reece, J. B. u. a.: Campbell Biologie, 10. Aufl., Pearson 2016 (Landkarte [^gl-c-drift])","oeffentlich":false,"seite":"633, 636, 637"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"f6f7ec0c57d03e87"}},{"id":"qc-11","status":"entwurf","clusterId":"C","werkstueckRef":"C.3.6","stufe":4,"question":"Was ist an diesem Argument fehlerhaft?","options":["Es behandelt Eingriffe gleich, deren Folgen sich grundlegend unterscheiden: Eine Veränderung bleibt beim behandelten Menschen, die andere wird an alle Nachkommen weitergegeben.","Es übersieht, dass sich jede Genveränderung beim Menschen später wieder rückgängig machen lässt und daher kein besonderes ethisches Gewicht hat.","Es unterscheidet nicht zwischen Eingriffen in der Forschung und Eingriffen in der Klinik, obwohl erst die klinische Anwendung am Patienten ein Risiko darstellt.","Es übersieht, dass Eingriffe am Menschen grundsätzlich anders zu bewerten sind als Eingriffe an Tieren, weil nur beim Menschen Zustimmung eine Rolle spielt."],"correctIndex":0,"explanation":"Das Argument wirft zwei Anwendungen in einen Topf, die ethisch sehr verschieden wiegen. Wird eine Körperzelle eines erwachsenen Patienten editiert (somatisch), bleibt die Veränderung auf diesen einen Menschen beschränkt; er kann einwilligen, und der Nutzen lässt sich gegen das Risiko abwägen. So arbeitet etwa Casgevy gegen die Sichelzellkrankheit; die britische MHRA ließ die Therapie im November 2023 als weltweit erste Behörde zu. Wird dagegen ein Embryo, eine Eizelle oder eine Samenzelle editiert (Keimbahn), wird die Veränderung unwiderruflich an alle künftigen Generationen vererbt, deren Langzeitfolgen unklar sind und die nie zustimmen konnten. Wer beides pauschal gleichsetzt, kann weder die erlaubte Heilung noch das echte Risiko angemessen beurteilen. Die gute Frage lautet deshalb nicht „Gentechnik: ja oder nein?“, sondern: Welche Zellen, mit welcher Zustimmung, mit welcher Vererbbarkeit?","coreRule":"⚡ Bevor du Gentechnik bewertest, frag: Bleibt die Veränderung beim Patienten (somatisch) oder geht sie an alle Nachkommen (Keimbahn)?","quote":"","quoteLabel":"","scenario":"In einer Diskussion sagt jemand: „Dass Forscher menschliche Zellen mit CRISPR verändern, ist ethisch heikel. Deshalb muss man jede Genveränderung beim Menschen gleich streng behandeln, egal ob bei einem erkrankten Erwachsenen oder bei einem Embryo.“","kurz":"Das Argument wirft Eingriffe zusammen, die sehr Verschiedenes bewirken: Ändert man Körperzellen eines Erwachsenen, betrifft das nur ihn, bei Embryonen erben es alle Nachkommen. Wer beides gleich behandelt, kann weder Heilung noch Risiko richtig beurteilen.","prueffrage":"Wer ist von der Veränderung betroffen, und konnte jede dieser Personen dazu etwas sagen?","rueckmeldung":[{"option":1,"text":"Ob sich ein Eingriff zurücknehmen lässt, wiegt ethisch tatsächlich schwer. Gerade deshalb trägt der Einwand nicht: Eine Veränderung am Embryo ist unwiderruflich und wird an alle Nachkommen vererbt, rückgängig machen lässt sich also keineswegs jede."},{"option":2,"text":"Forschung und Klinik unterscheiden sich tatsächlich im Risiko für Patienten. Das Argument trennt aber nach den veränderten Zellen, erwachsener Patient oder Embryo, und auch die Forschung an Embryonen ist ethisch heikel, nicht erst die Klinik."},{"option":3,"text":"Einwilligung ist wichtig, und zwischen Mensch und Tier zu unterscheiden kann anderswo tragen. Hier geht es aber um zwei Eingriffe am Menschen, und gerade da liegt der Unterschied: Der Erwachsene kann zustimmen, künftige Generationen nicht."}],"familie":"nutzen-und-risiko-abwaegen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"National Human Genome Research Institute (NHGRI): „What are the Ethical Concerns of Genome Editing?“","oeffentlich":true,"url":"https://www.genome.gov/about-genomics/policy-issues/Genome-Editing/ethical-concerns","abruf":"2026-10-12"},{"typ":"url","kurz":"U.S. Food and Drug Administration (08.12.2023): „FDA Approves First Gene Therapies to Treat Patients with Sickle Cell Disease“","oeffentlich":true,"url":"https://www.fda.gov/news-events/press-announcements/fda-approves-first-gene-therapies-treat-patients-sickle-cell-disease","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"44dfc81c8cb6cb0d"}},{"id":"qc-12","status":"entwurf","clusterId":"C","werkstueckRef":"C.4.5","stufe":2,"question":"Nach einer Operation wird einer Gruppe von Schmerzpatienten eine Zuckerpille als „starkes neues Schmerzmittel“ gegeben. Viele berichten kurz darauf von deutlich weniger Schmerzen. Ein Kollege winkt ab: „Das war nur Einbildung, da kann nichts Reales im Körper passiert sein.“ Was spricht am stärksten gegen diesen Schluss?","options":["Echte Schmerzlinderung setzt immer einen Wirkstoff voraus, also muss die Pille Spuren davon enthalten haben.","Erwartung kann körpereigene Schmerzdämpfer wie Endorphine freisetzen, ein Erleben ohne Wirkstoff kann also körperlich real sein.","Wer ein Medikament erwartet, gibt schlicht angenehmere Antworten, im Körper ändert sich in keinem Fall etwas.","Schmerzen schwanken von selbst, deshalb ist jede Besserung nach einer Pille zufällig und ohne Zusammenhang."],"correctIndex":1,"explanation":"„Nur Einbildung“ unterstellt, dass alles, was von der Erwartung abhängt, nicht real sein kann. Das ist ein Fehlschluss. Erwartung kann messbare körperliche Vorgänge anstoßen: Eine als starkes Schmerzmittel angepriesene Zuckerpille kann im Gehirn die Ausschüttung körpereigener Endorphine auslösen, bei Parkinson-Patienten setzte eine Placebo-Injektion in einer kleinen PET-Studie mit sechs Patienten Dopamin frei. Die anderen Erklärungen greifen zu kurz oder sind unbelegt: Ein Wirkstoff ist nicht nötig, und höfliche Antworten oder spontane Schwankungen können zwar mitspielen, schließen eine reale körperliche Reaktion aber nicht aus. Kontrollierte Studien finden Placebo-Wirkungen fast nur bei Beschwerden, die Patienten selbst einschätzen. Die Placebo-Wirkung ist also real, aber begrenzt und sagt nichts darüber, ob die Behandlung selbst wirkt.","coreRule":"⚡ Ein Effekt, der von der Erwartung abhängt, ist nicht „nur Einbildung“. Er kann real sein und sagt trotzdem nichts über die spezifische Wirkung einer Behandlung.","quote":"","quoteLabel":"","scenario":"","beleg":"Werkstück C.4.5, Abschnitt „Kontext & Tiefe“, Fußnoten gl-c-colloca, gl-c-dopamin (Schmerzlinderung/Endorphine, Dopamin); Frage aus Abfrage zu Anwendung umgebaut","kurz":"„Nur Einbildung“ setzt voraus, dass nichts Reales sein kann, was von der Erwartung abhängt. Doch Erwartung kann körpereigene Schmerzdämpfer wie Endorphine freisetzen: Das Erleben ist dann ohne Wirkstoff körperlich real.","prueffrage":"Hat der Kollege im Körper der Patienten irgendetwas nachgesehen, bevor er sagt, dort sei nichts Reales passiert?","rueckmeldung":[{"option":0,"text":"Dass Linderung einen Wirkstoff braucht, klingt plausibel, denn so funktionieren gewöhnliche Medikamente. Hier war aber nur Zucker in der Pille, und Spuren eines Wirkstoffs werden bloß angenommen, nicht belegt. Nötig ist er nicht."},{"option":2,"text":"Erwartung kann Antworten tatsächlich färben, und höfliche Angaben spielen mitunter mit. Dass sich im Körper „in keinem Fall“ etwas ändert, ist aber unbelegt und wiederholt den Fehlschluss des Kollegen. Eine körperliche Reaktion bleibt möglich."},{"option":3,"text":"Schmerzen schwanken von selbst, und das kann den Eindruck einer Wirkung verstärken. Daraus folgt aber nicht, dass jede Besserung Zufall ist. Spontane Schwankungen schließen eine reale körperliche Reaktion auf die Erwartung nicht aus."}],"familie":"fair-testen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Levine, Gordon & Fields 1978, The mechanism of placebo analgesia, Lancet 2(8091) (PubMed-Abstract)","oeffentlich":true,"doi":"10.1016/s0140-6736(78)92762-9","url":"https://pubmed.ncbi.nlm.nih.gov/80579/","abruf":"2026-10-12"},{"typ":"url","kurz":"de la Fuente-Fernández u. a. 2001, Expectation and dopamine release: mechanism of the placebo effect in Parkinson's disease, Science 293 (PubMed-Abstract)","oeffentlich":true,"doi":"10.1126/science.1060937","url":"https://pubmed.ncbi.nlm.nih.gov/11498597/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Hróbjartsson & Gøtzsche 2010, Placebo interventions for all clinical conditions, Cochrane Database Syst Rev (PMC7156905)","oeffentlich":true,"doi":"10.1002/14651858.CD003974.pub3","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"1d7042d19f0da76b"}},{"id":"qc-13","status":"entwurf","clusterId":"C","werkstueckRef":"C.4.6","stufe":3,"question":"Welche Nachfrage prüft am besten, ob die Besserung auch ohne Behandlung zu erwarten war?","options":["Wie oft hattest du schon Schmerzspitzen, nach denen es auch ohne jede Behandlung wieder besser wurde?","Wie lange hat der Akupunkteur studiert und wie viele Patienten behandelt er pro Woche?","Wie stark war deine Erwartung, dass dir die Behandlung helfen wird, und wie überzeugt war der Akupunkteur?","Wie genau hat sich die Besserung angefühlt und an welchen Stellen des Rückens hast du sie bemerkt?"],"correctIndex":0,"explanation":"Wer Hilfe am Tiefpunkt sucht, erwischt oft genau den Extremwert. Nach einem extremen Wert liegt der nächste meist wieder näher am persönlichen Durchschnitt, auch ohne jede Behandlung. Die Nachfrage nach früheren Schmerzspitzen, die von allein abklangen, prüft genau das: Wäre die Besserung auch ohne Nadeln zu erwarten gewesen? Die Frage nach der Erwartung zielt auf den Placebo-Effekt, eine andere Erklärung, und Ausbildung des Behandlers oder das Gefühl der Besserung klären ebenfalls nicht, ob sie ohnehin gekommen wäre. Die eigene Vorgeschichte ist ein erster Prüfstein; ob die Nadeln selbst wirken, zeigt erst ein Vergleich mit Menschen, die nicht oder nur zum Schein behandelt wurden.","coreRule":"⚡ Wer am Tiefpunkt behandelt, hält die Rückkehr zur Mitte leicht für Heilung. Frag erst, was ohne Behandlung zu erwarten war.","quote":"","quoteLabel":"","scenario":"Ein Freund erzählt: „Ich hatte schreckliche Rückenschmerzen. Sonst sind sie meist mittelstark und schwanken von Tag zu Tag. Am schlimmsten Tag war ich beim Akupunkteur, am nächsten Tag war es deutlich besser. Die Nadeln wirken!“","beleg":"Werkstück C.4.6, Abschnitt „Regression zur Mitte“ (Rückenschmerz-Beispiel Skala 1-10, Akupunkteur), Werkbank-Frage","kurz":"Wer am schlimmsten Tag Hilfe sucht, erwischt oft einen Extremwert; danach liegt der nächste Tag meist wieder näher am Durchschnitt, auch ohne Behandlung. Die Besserung allein zeigt deshalb nicht, dass die Nadeln gewirkt haben.","prueffrage":"Warum ging dein Freund ausgerechnet an diesem Tag zum Akupunkteur und nicht an einem gewöhnlichen?","rueckmeldung":[{"option":1,"text":"Ausbildung und Erfahrung eines Behandlers wirken wie ein Qualitätsmerkmal. Sie sagen aber nichts über den Schmerzverlauf deines Freundes und damit nicht, ob die Besserung nach der Spitze ohnehin zu erwarten war."},{"option":2,"text":"Erwartung und Überzeugung können tatsächlich zur Besserung beitragen, das ist ein eigener Erklärungsweg (Placebo). Er klärt aber nicht, ob es nach einer Schmerzspitze von selbst besser wird, und genau darum geht es hier."},{"option":3,"text":"Genaue Angaben zur Besserung machen die Schilderung anschaulicher und wirken deshalb aufschlussreich. Ohne Vergleich mit dem üblichen Verlauf zeigen sie aber nicht, ob die Besserung ohnehin gekommen wäre."}],"familie":"was-waere-ohne","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Barnett, van der Pols & Dobson 2005, Regression to the mean: what it is and how to deal with it, Int J Epidemiol 34(1) (PubMed-Abstract)","oeffentlich":true,"doi":"10.1093/ije/dyh299","url":"https://pubmed.ncbi.nlm.nih.gov/15333621/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Vickers u. a. 2018, Acupuncture for Chronic Pain: Update of an Individual Patient Data Meta-Analysis, J Pain 19(5) (PMC5927830)","oeffentlich":true,"doi":"10.1016/j.jpain.2017.11.005","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"01607b278ef344d2"}},{"id":"qc-14","status":"entwurf","clusterId":"C","werkstueckRef":"C.4.7","stufe":1,"question":"Ein Artikel meldet: „Alarm! In Haferflocken wurde eine Substanz nachgewiesen, die in hohen Mengen Leberschäden verursacht.“ Menge, Grenzwert und Vergleichswerte nennt er nicht. Welche Reaktion ist die vernünftigste?","options":["Das Produkt meiden, denn eine nachweislich schädliche Substanz hat in Lebensmitteln nichts zu suchen.","Nach der gefundenen Menge fragen und sie mit Grenzwert und Vergleichswerten aus anderen Quellen abgleichen.","Der Meldung zunächst nicht glauben, denn Warnungen vor einzelnen Stoffen sind meistens übertrieben.","Prüfen, ob die Substanz auch in Bioprodukten vorkommt, und nur bei konventioneller Ware Konsequenzen ziehen."],"correctIndex":1,"explanation":"Ob ein Stoff schadet, entscheidet die Menge, nicht seine bloße Anwesenheit. Fast jede Substanz ist unterhalb einer Schwelle harmlos und oberhalb giftig: Wasser und Kochsalz können in extremen Mengen töten, Botulinumtoxin wird in winzigen Dosen sogar als Medikament eingesetzt. Selbst bei Stoffen, für die vorsorglich keine sichere Schwelle angenommen wird, hängt das Risiko von der Dosis ab. Die Meldung „gefunden“ sagt deshalb allein nichts über eine Gefahr aus. Aussagekräftig wird sie erst durch drei Zahlen: die gefundene Menge, den Grenzwert und die Belastung aus anderen, oft natürlichen Quellen. Alarmismus wie reflexhaftes Abwiegeln überspringen genau diese Prüfung.","coreRule":"⚡ Die Anwesenheit eines Stoffs sagt nichts über Gefahr. Entscheidend ist die Menge im Verhältnis zur Schwelle.","quote":"","quoteLabel":"","scenario":"","kurz":"Aus dem bloßen Nachweis eines Stoffs folgt noch keine Gefahr, denn die Menge entscheidet. Erst gefundene Menge, Grenzwert und Vergleichswerte machen die Meldung beurteilbar; ob man in Panik gerät oder sie abtut, ersetzt diese Prüfung nicht.","prueffrage":"Würde dieselbe Meldung dich beunruhigen, wenn der nachgewiesene Stoff Kochsalz wäre, das in großen Mengen ebenfalls schadet?","rueckmeldung":[{"option":0,"text":"Unnötige Belastungen zu vermeiden klingt vernünftig. Die Meldung sagt aber nur, dass der Stoff in hohen Mengen schadet, nicht dass die Menge im Produkt hoch ist. Dass etwas darin steckt, sagt für sich noch nichts über eine Gefahr."},{"option":2,"text":"Misstrauen gegenüber einer Meldung ohne Zahlen ist angebracht. Sie pauschal abzutun ist aber ebenfalls ein Reflex: Sie kann stimmen, und ob „meistens übertrieben“ auch hier gilt, wäre erst nach Prüfung der Mengen klar."},{"option":3,"text":"Die Herkunft der Ware kann bei Belastungen eine Rolle spielen. Die Frage, ob die Menge hier überhaupt bedenklich ist, bleibt damit aber offen, und nur sie entscheidet, ob irgendeine Konsequenz nötig ist."}],"familie":"dosis-entscheidet","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Grandjean, P. (2016): Paracelsus Revisited: The Dose Concept in a Complex World. Basic & Clinical Pharmacology & Toxicology 119(2), 126–132","oeffentlich":true,"doi":"10.1111/bcpt.12622","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4942381/","abruf":"2026-10-12"},{"typ":"url","kurz":"EFSA: Margin of Exposure (Themenseite)","oeffentlich":true,"url":"https://efsa.europa.eu/en/topics/topic/margin-exposure","abruf":"2026-10-12"},{"typ":"url","kurz":"Paracelsus (1538): Sieben Defensiones, hg. Sudhoff 1915 (Digitalisat Wellcome Collection), dritte Defension","oeffentlich":true,"url":"https://wellcomecollection.org/works/jxt2qtp7","seite":"25","abruf":"2026-10-08"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"6a26a9b9b7478d67"}},{"id":"qc-15","status":"entwurf","clusterId":"C","werkstueckRef":"C.4.8","stufe":4,"question":"Was ist an diesem Schluss fehlerhaft?","options":["Er unterstellt, dass Selektion späte Schäden voll gewichtet, obwohl sie am Fortpflanzungserfolg ansetzt, den diese kaum noch berühren.","Er unterstellt, dass Herzinfarkte im Alter häufig sind, obwohl sie bei Menschen jeden Alters etwa gleich oft vorkommen.","Er unterstellt, dass Gene in verschiedenen Lebensphasen verschieden wirken können, obwohl jedes Gen immer nur eine einzige Wirkung hat.","Er unterstellt, dass die Selektion auf einzelne Gene wirkt, obwohl sie ausschließlich auf ganze Populationen und nie auf Individuen wirkt."],"correctIndex":0,"explanation":"Die natürliche Selektion optimiert den Fortpflanzungserfolg, nicht die Lebensspanne. Ein Gen, das früh Nachkommen begünstigt und erst nach der Fertilitätsphase schadet, wird kaum „bestraft“: Seine späten Kosten fallen für den Fortpflanzungserfolg wenig ins Gewicht, sein früher Nutzen zählt voll. Dieses Muster heißt antagonistische Pleiotropie. Ein verborgener Nutzen im Alter ist also gar nicht nötig, um das Fortbestehen des Gens zu erklären. Altern erscheint hier als Nebenwirkung evolutionärer Kurzsichtigkeit, nicht als Ziel der Selektion. Zu prüfen ist stets, auf welchen Zeitraum sich ein „Das hätte die Evolution aussortiert“ überhaupt stützen kann. Hinweis: Ob es beim Menschen ein zweifelsfrei belegtes Gen dieser Art gibt, ist offen; belegt ist das Muster an Hefe, Würmern, Fliegen und Mäusen. Die Denkfigur der Frage bleibt davon unberührt.","coreRule":"⚡ Selektion zählt den Fortpflanzungserfolg, nicht die Lebensspanne – „Warum hat die Evolution das nicht aussortiert?“ setzt eine Bewertung voraus, die es so nicht gibt.","quote":"Evolution agiert als blinder Bastler: Sie nutzt „gut genug für jetzt“-Lösungen, ohne langfristige Kosten zu berücksichtigen.","quoteLabel":"Zum Weiterdenken:","scenario":"Ein Gen erhöht mit 20 Jahren die Fortpflanzungschancen und steigert mit 70 das Herzinfarktrisiko. Im Gespräch über das Altern sagt jemand dazu: „Wenn ein Gen im Alter Herzinfarkte auslöst, müsste die natürliche Selektion es längst aussortiert haben. Dass es noch da ist, zeigt, dass es einen verborgenen Nutzen für die Alten haben muss.“","beleg":"Werkstück C.4.8, Abschnitt „Evolutionäre Kurzsichtigkeit“; Austad & Hoffman 2018 (Fußnote gl-c-austad) zum Beleg an Modellorganismen und zur offenen Lage beim Menschen.","kurz":"Selektion bewertet den Fortpflanzungserfolg, nicht die Lebensspanne: Ein Gen mit frühem Nutzen und spätem Schaden kann sich halten, ohne im Alter zu nützen. Der Schluss „das hätte die Evolution aussortiert“ übersieht, welcher Zeitraum dafür überhaupt zählt.","prueffrage":"Wenn ein Träger dieses Gens mit 70 einen Herzinfarkt erleidet, was hat das Gen in seinem Leben bis dahin schon bewirkt?","rueckmeldung":[{"option":1,"text":"Herzinfarkte kommen keineswegs in jedem Alter gleich oft vor, sie nehmen mit dem Alter deutlich zu. Der Fehler des Schlusses liegt woanders: Er übersieht, dass die Selektion späte Schäden kaum erfasst, wenn das Gen früh die Fortpflanzung fördert."},{"option":2,"text":"Viele Gene haben mehrere Wirkungen; ein Gen, das mit 20 nützt und mit 70 schadet, ist genau so ein Fall. Die Annahme, jedes Gen habe nur eine Wirkung, ist falsch, und die frühe Wirkung ist gerade der Schlüssel zur Auflösung."},{"option":3,"text":"Selektion wirkt keineswegs „nie“ auf Individuen: Sie setzt an deren unterschiedlichem Fortpflanzungserfolg an, die Folgen zeigen sich in der Population. Der Fehler des Schlusses liegt woanders: Späte Schäden fallen für die Selektion kaum ins Gewicht."}],"familie":"auslese-statt-plan","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Austad, S. N.; Hoffman, J. M. (2018): Is antagonistic pleiotropy ubiquitous in aging biology? Evolution, Medicine, and Public Health 2018(1), 287–294","oeffentlich":true,"doi":"10.1093/emph/eoy033","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Williams, G. C. (1957): Pleiotropy, natural selection, and the evolution of senescence. Evolution 11(4), 398–411 (doi 10.1111/j.1558-5646.1957.tb02911.x)","oeffentlich":false}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"4ebdffba74876370"}},{"id":"qc-16","status":"entwurf","clusterId":"C","werkstueckRef":"C.4.10","stufe":4,"question":"Was ist an diesem Schluss fehlerhaft?","options":["Der Schluss übersieht, dass ein Organismus kein abgeschlossenes System ist: Er kann seine Ordnung halten, solange er Energie aufnimmt und Entropie abgibt. Das Altern hat andere, biologische Gründe.","Der Schluss ist richtig, denn jede Reparatur erhöht die Entropie des Universums, und deshalb muss jeder Organismus nach einiger Zeit unweigerlich zerfallen und altern.","Der Schluss ist richtig, denn Lebewesen sind abgeschlossene Systeme, die keine Energie von außen aufnehmen und deshalb ihre Ordnung nicht dauerhaft halten können.","Der Schluss gilt nur für Vielzeller, denn bei ihnen verbietet der Zweite Hauptsatz den dauerhaften Erhalt der Ordnung ausdrücklich, bei Einzellern dagegen nicht."],"correctIndex":0,"explanation":"Der Zweite Hauptsatz sagt, dass die Gesamtentropie wächst, nicht dass jedes Teilsystem zerfallen muss. Ein offenes System darf seine Ordnung halten, solange es Energie aufnimmt und Entropie nach außen abgibt. Manche Einzellerklone halten offenbar als Kultur ihr gleichmäßiges Wachstum aufrecht (auch wenn die einzelne Zelle mit der Zahl ihrer Teilungen ein steigendes Sterberisiko hat), und beim Süßwasserpolypen Hydra steigt die Sterblichkeit im Labor über Jahre nicht an. Unsterblich ist deshalb noch kein Vielzeller – auch Hydren sterben, nur nicht häufiger mit zunehmendem Alter. Dass Reparatur bei den meisten Lebewesen auf Dauer unvollständig bleibt, weil sie mit allem anderen um Energie konkurriert, ist ein biologischer Befund, kein Naturgesetz. Der Blog schließt von einem Gesetz über das gesamte Universum auf ein Verbot für ein einzelnes offenes System.","coreRule":"⚡ Ordnung halten kostet Energie, ist aber nicht verboten: Prüfe bei Berufung auf ein Naturgesetz, ob es für das betrachtete System überhaupt gilt. Die Grenzen des Alterns sind biologisch, nicht thermodynamisch.","quote":"","quoteLabel":"","scenario":"Ein Wissenschaftsblog behauptet: „Jede Reparatur im Körper kostet Energie, und jede Energieumwandlung erhöht die Entropie des Universums. Nach dem Zweiten Hauptsatz der Thermodynamik kann ein Organismus deshalb gar nicht dauerhaft intakt bleiben, Altern ist ein Naturgesetz.“","kurz":"Der Zweite Hauptsatz verlangt, dass die Gesamtentropie wächst, nicht dass jedes Teilsystem zerfällt. Ein Organismus ist offen: Er kann Ordnung halten, wenn er Energie aufnimmt und Entropie abgibt. Der Blog schließt vom Universum auf ein einzelnes Lebewesen.","prueffrage":"Was nimmt ein Lebewesen ständig aus seiner Umgebung auf, und was gibt es an sie ab?","rueckmeldung":[{"option":1,"text":"Jede Reparatur kostet Energie und erhöht die Gesamtentropie, das stimmt. Daraus folgt aber nicht, dass jedes Lebewesen zerfallen muss: Ein offenes System kann seine Ordnung halten, indem es Energie aufnimmt und Entropie nach außen abgibt."},{"option":2,"text":"Der Zweite Hauptsatz schließt sinkende Entropie tatsächlich nur für abgeschlossene Systeme ohne Austausch mit der Umgebung aus. Lebewesen sind aber keine: Sie nehmen ständig Energie und Stoffe auf und geben Wärme und Entropie ab."},{"option":3,"text":"Dass manche Einzellerklone als Kultur offenbar gleichmäßig weiterwachsen, macht die Unterscheidung verlockend. Der Zweite Hauptsatz unterscheidet aber nicht zwischen Ein- und Vielzellern und verbietet keinem offenen System, seine Ordnung zu halten."}],"familie":"bilanz-pruefen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Schaible u. a. 2015, Constant mortality and fertility over age in Hydra, PNAS 112(51) (PMC4697432)","oeffentlich":true,"doi":"10.1073/pnas.1521002112","abruf":"2026-10-12"},{"typ":"doi","kurz":"Wang u. a. 2010, Robust Growth of Escherichia coli, Current Biology 20(12) (PMC2902570)","oeffentlich":true,"doi":"10.1016/j.cub.2010.04.045","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Williams 1957, Pleiotropy, natural selection, and the evolution of senescence, Evolution 11(4)","oeffentlich":false,"doi":"10.1111/j.1558-5646.1957.tb02911.x"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"82a1e652d8f42a65"}},{"id":"qc-17","status":"entwurf","clusterId":"C","werkstueckRef":"C.4.11","stufe":2,"question":"Eine Forscherin liest: „Grönlandhaie leben im eiskalten Nordatlantik und werden mehrere Jahrhunderte alt. Das Wasser ist also die Ursache für das lange Leben.“ Welcher Einwand prüft diesen Schluss am besten?","options":["Es fehlt der Vergleich: Man müsste wissen, ob verwandte Haie in wärmerem Wasser kürzer leben, und ob die Kälte über einen langsameren Stoffwechsel wirken könnte, statt bloß gleichzeitig vorzukommen.","Es fehlt der Vergleich: Man müsste wissen, ob das Wasser des Nordatlantiks mehr Sauerstoff enthält, denn nur ein hoher Sauerstoffgehalt kann ein langes Leben erklären.","Die Aussage ist unbrauchbar, weil Altersschätzungen von Tieren nie belegbar sind und deshalb jede Erklärung zum Alter reine Spekulation bleibt.","Die Aussage stimmt zwangsläufig, weil ein Tier, das lange lebt, nach Definition einen besonders effizienten Reparaturmechanismus in seinen Zellen besitzen muss."],"correctIndex":0,"explanation":"Dass zwei Dinge zusammen auftreten (kaltes Wasser, hohes Alter), beweist noch keinen ursächlichen Zusammenhang. Ein starker Test ist der Vergleich: Leben nahe verwandte oder ähnlich gebaute Tiere in wärmerem Wasser kürzer? Zusätzlich braucht es einen plausiblen Mechanismus: Chemische Reaktionen laufen bei niedriger Temperatur langsamer ab, also auch der Stoffwechsel wechselwarmer Tiere, und ein verlangsamter Stoffwechsel gilt als einer der Hauptgründe für das hohe Alter des Grönlandhais. Dass nur ein hoher Sauerstoffgehalt ein langes Leben erklären könne, wird dagegen ohne jede Begründung behauptet und schließt andere Ursachen willkürlich aus. Dass Altersschätzungen ungenau sind, ist ein Grund für vorsichtige Formulierungen, kein Grund, jede Erklärung zu verwerfen. Und „lebt lange, also hat er gute Reparatur“ ist ein Zirkelschluss, der nichts erklärt.","coreRule":"⚡ Aus „zusammen aufgetreten“ folgt noch keine Ursache: Prüfe Vergleichsfälle und frage nach einem Mechanismus, der zur Ursache passt.","quote":"Chemische Reaktionen laufen bei höheren Temperaturen schneller ab.","quoteLabel":"Merksatz:","scenario":"Eine Schlagzeile zu Grönlandhaien: „Kaltes Wasser macht Haie fast unsterblich.“ Der Artikel stützt sich darauf, dass die Tiere in Wassertemperaturen knapp über dem Gefrierpunkt leben und Altersschätzungen von mehreren Jahrhunderten vorliegen.","kurz":"Dass kaltes Wasser und hohes Alter zusammen auftreten, zeigt noch keine Ursache. Stark wird der Schluss erst durch den Vergleich mit Haien in wärmerem Wasser und einen plausiblen Mechanismus: Kälte verlangsamt den Stoffwechsel wechselwarmer Tiere.","prueffrage":"Was außer dem kalten Wasser zeichnet Grönlandhaie noch aus, das ihr langes Leben ebenso erklären könnte?","rueckmeldung":[{"option":1,"text":"Ein Vergleich ist tatsächlich der richtige Ansatz. Dass aber nur Sauerstoff ein langes Leben erklären könne, wird ohne jede Begründung behauptet und lenkt von der Frage ab, ob die Kälte über einen langsameren Stoffwechsel wirkt."},{"option":2,"text":"Altersschätzungen sind unsicher, deshalb sind vorsichtige Formulierungen angebracht. Daraus folgt aber nicht, dass jede Erklärung Spekulation bleibt: Ob Kälte mitwirkt, lässt sich durch Vergleiche und einen plausiblen Mechanismus durchaus prüfen."},{"option":3,"text":"Hier dient das lange Leben selbst als Beweis für die vermutete Ursache, und genau das ist ein Zirkelschluss. Er klingt logisch, erklärt aber nichts und prüft den Schluss auf das Wasser auch nicht."}],"familie":"korrelation-und-ursache","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Ste-Marie u. a. 2020, A first look at the metabolic rate of Greenland sharks (Somniosus microcephalus) in the Canadian Arctic, Scientific Reports 10 (PMC7653932)","oeffentlich":true,"doi":"10.1038/s41598-020-76371-0","abruf":"2026-10-12"},{"typ":"url","kurz":"Nielsen u. a. 2016, Eye lens radiocarbon reveals centuries of longevity in the Greenland shark, Science 353 (PubMed-Abstract)","oeffentlich":true,"doi":"10.1126/science.aaf1703","url":"https://pubmed.ncbi.nlm.nih.gov/27516602/","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"a203d333f4cc681b"}},{"id":"qc-18","status":"entwurf","clusterId":"C","werkstueckRef":"C.5.1","stufe":1,"question":"Ein Politiker hält an einem eiskalten Wintertag einen Schneeball in die Kamera und erklärt, die globale Erwärmung sei damit widerlegt. Was ist an seinem Argument fehlerhaft?","options":["Er schließt von einer kurzfristigen Beobachtung an einem Ort auf einen langfristigen, globalen Durchschnitt.","Er misst die Lufttemperatur am Boden, obwohl allein die Meerestemperatur für den Klimatrend zählt.","Er blendet aus, dass der Treibhauseffekt im Winter grundsätzlich schwächer wirkt als im Sommer.","Er verwechselt Ursache und Wirkung, denn Kälte im Winter verstärkt den Treibhauseffekt."],"correctIndex":0,"explanation":"Wetter ist der kurzfristige, chaotische Zustand der Atmosphäre an einem Ort, Klima der statistische Durchschnitt über Jahrzehnte (üblicherweise etwa 30 Jahre). Ein Bild dafür: Ein Hund an der Leine läuft wild hin und her, der Spaziergänger geht trotzdem stetig in eine Richtung. Wer nur fünf Sekunden auf den Hund schaut, kann den Weg des Spaziergängers nicht beurteilen. Genauso sagt ein einzelner kalter Tag so wenig über den Klimatrend aus wie ein einzelner warmer Tag. Auch eine sich erwärmende Welt hat weiterhin kalte Tage und harte Kälteeinbrüche; sie werden nur seltener und milder, während Hitzewellen häufiger und heftiger werden.","coreRule":"⚡ Ein einzelner Tag ist Wetter, kein Klimatrend: Prüfe, ob eine Beobachtung für den langfristigen Durchschnitt repräsentativ ist.","quote":"Ein einzelner kalter Tag sagt genauso wenig über den Klimatrend aus wie ein einzelner warmer Tag.","quoteLabel":"Merksatz:","scenario":"","beleg":"Werkstück C.5.1 (Das Klimasystem), Abschnitt „Kontext & Tiefe“ und Fußnote gl-c-ipcc-extreme (IPCC 2021, SPM A.3.1/A.3.2)","kurz":"Ein Schneeball an einem kalten Tag zeigt das Wetter an einem Ort; bei der Erwärmung geht es um den weltweiten Durchschnitt über Jahrzehnte. Ein einzelner kalter Tag sagt darüber so wenig wie ein einzelner heißer.","prueffrage":"Wie war das Wetter am selben Tag in anderen Teilen der Erde, etwa auf der Südhalbkugel, wo dann Sommer ist?","rueckmeldung":[{"option":1,"text":"Die Messgröße ist hier nicht das Problem: Für Klimatrends zählen viele Größen, etwa Lufttemperatur, Ozeane und Eis, nicht nur das Meer. Das Argument scheitert daran, dass ein einzelner Moment an einem Ort über einen Trend nichts aussagt."},{"option":2,"text":"Jahreszeiten erklären, warum es im Winter kalt ist, aber nicht, was am Argument falsch ist: Auch in einer wärmeren Welt gibt es kalte Wintertage, und ein einzelner davon sagt nichts über den langfristigen, weltweiten Trend."},{"option":3,"text":"Hier wird ein Zusammenhang behauptet, der nicht besteht: Kälte verstärkt den Treibhauseffekt nicht. Der Fehler des Politikers liegt nicht in einer vertauschten Kausalrichtung, sondern darin, einen einzelnen kalten Tag für den Klimatrend zu halten."}],"familie":"trend-statt-einzelfall","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"NOAA National Centers for Environmental Information: WMO Climate Normals","oeffentlich":true,"url":"https://ncei.noaa.gov/products/wmo-climate-normals","abruf":"2026-10-12"},{"typ":"url","kurz":"IPCC (2021): Summary for Policymakers. In: Climate Change 2021: The Physical Science Basis, A.3.1","oeffentlich":true,"doi":"10.1017/9781009157896.001","url":"https://www.ipcc.ch/report/ar6/wg1/downloads/report/IPCC_AR6_WGI_SPM.pdf","seite":"8","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"98798731f7eadf93"}},{"id":"qc-19","status":"entwurf","clusterId":"C","werkstueckRef":"C.5.3","stufe":2,"question":"Was ist an diesem Argument fehlerhaft?","options":["Der Schluss setzt voraus, dass die Lebensdauer allein am Flugzeug liegt, und lässt außer Acht, dass die Luft in Flughöhe unterschiedlich feucht sein kann.","Der Schluss ist fehlerhaft, weil sich die Streifen in der Höhe wegen der Kälte grundsätzlich nie auflösen und die Dauer daher nichts besagt.","Der Schluss ist fehlerhaft, weil er mit zwei Streifen zu wenige Beobachtungen nutzt und erst hundert Streifen etwas beweisen würden.","Der Schluss setzt voraus, dass die Streifen sichtbar sind, obwohl man in dieser Höhe mit bloßem Auge gar nichts erkennen kann."],"correctIndex":0,"explanation":"Der Schluss behandelt „schnelles Verschwinden“ als Normalfall und jede Abweichung als Beweis für Eingriff von außen. Bei der Verbrennung im Triebwerk entstehen vor allem CO₂ und Wasserdampf; der Wasserdampf gefriert in großer Höhe zu Eiskristallen. Ob diese Kristalle schnell verschwinden oder wachsen, hängt von der Feuchtigkeit der Umgebungsluft ab: In trockener Luft lösen sie sich rasch auf, in eisübersättigter Luft bleiben sie stundenlang und breiten sich aus. Die Luftfeuchte in zehn Kilometern Höhe ist aber unsichtbar und wechselt von Tag zu Tag. Wer sie nicht kennt, kann aus der Dauer der Streifen nichts über Chemikalien ableiten. Auch die Gittermuster brauchen keine Absicht: Auf viel beflogenen Luftstraßen kreuzen sich die Routen, und bei passendem Wetter bleiben die Streifen unterschiedlicher Flugzeuge nebeneinander sichtbar. Das Wetter erklärt die Beobachtung einfacher als ein geheimes Programm, das viele Mitwissende bräuchte (Ockhams Rasiermesser).","coreRule":"⚡ Die Variation im Aussehen der Streifen ist ein Abbild des unsichtbaren Wetters in der Höhe, kein Beleg für eine geheime Zutat. Bevor du Absicht annimmst, frage nach der einfachsten Erklärung.","quote":"","quoteLabel":"","scenario":"Zwei Menschen sehen am Himmel lange, sich ausbreitende Streifen, die sich zu einem Gittermuster kreuzen. Ihr Schluss: „Normale Kondensstreifen lösen sich nach Sekunden auf. Diese hier stehen stundenlang am Himmel. Also werden hier Chemikalien versprüht.“","kurz":"Wie lange Streifen stehen, hängt von der Luftfeuchte in großer Höhe ab, die man vom Boden nicht sieht. Der Fehler: Schnelles Verschwinden gilt als Normalfall, jede Abweichung als Beweis für einen Eingriff.","prueffrage":"Bleiben die Streifen über derselben Gegend jeden Tag gleich lange stehen, obwohl dort Tag für Tag ähnliche Flugzeuge fliegen?","rueckmeldung":[{"option":1,"text":"Dass es dort oben sehr kalt ist, stimmt, und Kälte lässt den Wasserdampf überhaupt erst zu Eis gefrieren. Ob sich die Kristalle danach halten, hängt aber von der Luftfeuchte ab: In trockener Luft lösen sie sich rasch auf."},{"option":2,"text":"Mehr Beobachtungen klingen nach solider Prüfung. Auch hundert lange Streifen würden aber nichts über Chemikalien zeigen, solange die Luftfeuchte unbekannt bleibt. Das Problem liegt im Schluss selbst, nicht in der Zahl der Fälle."},{"option":3,"text":"Aus großer Höhe wirkt alles winzig, deshalb leuchtet der Einwand ein. Die Streifen sind aber gut sichtbar, sonst gäbe es die Beobachtung nicht. Unsichtbar ist die Luftfeuchte, und sie entscheidet über die Dauer."}],"familie":"bekannte-ursache-zuerst","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"U.S. EPA: Information on Contrails from Aircraft","oeffentlich":true,"url":"https://www.epa.gov/regulations-emissions-vehicles-and-engines/Contrails","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Schumann, U. (1996): On conditions for contrail formation from aircraft exhausts. Meteorologische Zeitschrift 5(1), 4–23 (doi 10.1127/metz/5/1996/4)","oeffentlich":false}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"278f9f387d86d56e"}},{"id":"qd-1","status":"entwurf","clusterId":"D","werkstueckRef":"D.1.1","stufe":1,"question":"Ein Epidemiologe legt Daten zur Wirksamkeit einer Impfung vor. Jemand entgegnet: „Was weiß der schon? Der fährt einen dicken Mercedes und ist arrogant!“ Was ist an dieser Entgegnung das Kernproblem?","options":["Sie greift die Person an, ohne die vorgelegten Daten inhaltlich zu prüfen","Sie verzerrt die Position des Epidemiologen und widerlegt dann die Verzerrung","Sie hält dem Epidemiologen vor, selbst gegen seine eigene Empfehlung zu handeln","Sie hält die Aussage allein wegen des Ranges des Sprechers für wahr"],"correctIndex":0,"explanation":"Die logische Gültigkeit eines Arguments hängt nie von den Eigenschaften der Person ab, die es ausspricht. Ein Epidemiologe kann arrogant sein und trotzdem korrekte Zahlen vorlegen. Die Entgegnung wechselt von der Sachebene auf die persönliche Ebene und lässt die Daten unberührt. Dieses Ausweichen heißt Ad hominem („gegen den Menschen“). Ein Argument muss nach seiner eigenen Stimmigkeit und den Beweisen bewertet werden, die es stützen.","coreRule":"⚡ Trenne die Botschaft vom Boten: Prüfe das Argument, nicht den Sprecher.","quote":"","quoteLabel":"","scenario":"","kurz":"Ob Daten stimmen, hängt nicht davon ab, wer sie vorlegt: Ein Epidemiologe kann arrogant sein und trotzdem korrekte Zahlen liefern. Die Entgegnung wechselt von der Sache zur Person und lässt die Daten unberührt.","prueffrage":"Welche Wörter der Entgegnung beziehen sich auf die Impfung oder die Daten, und welche auf etwas anderes?","rueckmeldung":[{"option":1,"text":"Eine Verzerrung würde voraussetzen, dass die Position des Epidemiologen falsch wiedergegeben und dann widerlegt wird. Hier wird aber keine Position wiedergegeben, weder richtig noch verzerrt: Die Daten bleiben schlicht unerwähnt."},{"option":2,"text":"Der Vorwurf, gegen den eigenen Rat zu handeln, wäre ein anderer Angriff auf die Person. Bemängelt werden hier aber Auto und Auftreten, die mit der Impfung nichts zu tun haben, und selbst ein echter Widerspruch ließe die Daten unberührt."},{"option":3,"text":"Hier geht es um die umgekehrte Richtung: Der Person wird Glaubwürdigkeit abgesprochen, statt ihrer Aussage wegen ihres Ranges Wahrheit zuzusprechen. Der Fehler liegt also nicht im Rang, sondern darin, dass die Daten außen vor bleiben."}],"familie":"inhalt-statt-absender","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy (Eintrag Ad Hominem)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Walton, D. (1998): Ad Hominem Arguments. Tuscaloosa: University of Alabama Press","oeffentlich":false,"seite":"S. xiv–xv (laut Landkarte-Fußnote gl-d-fehlschluss)"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"d18a18a6d2a04e65"}},{"id":"qd-2","status":"entwurf","clusterId":"D","werkstueckRef":"D.1.3","stufe":1,"question":"Was ist an der Aussage fehlerhaft, und wie reagierst du am besten?","options":["Sie lässt nur zwei Extreme zu und verschweigt Zwischenwege; du fragst, welche weiteren Positionen es gibt, etwa Zustimmung zum Ziel bei Kritik an Maßnahmen.","Sie behauptet, ein kleiner Schritt führe zwangsläufig in die Katastrophe; du fragst, wie wahrscheinlich jede einzelne Stufe dieser Kette ist.","Sie verzerrt die Gegenposition und bekämpft dann nur die Verzerrung; du fragst, was Kritiker der Initiative tatsächlich gesagt haben.","Sie setzt die Behauptung zugleich als ihren eigenen Beleg voraus; du fragst, welche unabhängige Begründung es dafür tatsächlich gibt."],"correctIndex":0,"explanation":"Der Sprecher präsentiert eine komplexe Lage als Entweder-oder: volle Zustimmung oder Feindschaft. Dass man das Ziel teilen und einzelne Maßnahmen dennoch kritisieren oder verbessern kann, kommt nicht vor; Kritik an einem Teil wird so automatisch als Ablehnung des Ganzen gedeutet. Das ist ein falsches Dilemma. Am besten sprengst du den Rahmen: Du fragst nach den Optionen, die fehlen, und nennst selbst mindestens eine, etwa „Ziel ja, diese Maßnahme überarbeiten“. Ein echtes Dilemma gäbe es nur, wenn tatsächlich keine weiteren Möglichkeiten existierten.","coreRule":"⚡ Spreng den Rahmen: Frage nach den Optionen C, D und E!","quote":"Die Speisekarte des Tyrannen: Fauliger Fisch oder Glasscherben.","quoteLabel":"Bild zum Merken:","scenario":"In einer Bürgerversammlung über eine geplante Initiative sagt ein Sprecher: „Entweder du unterstützt unsere Initiative zu 100 %, oder du bist ein Feind der Gerechtigkeit!“ Du hältst das Ziel für richtig, hast aber Zweifel an einzelnen Maßnahmen.","beleg":"Werkstück D.1.3, Abschnitte „Kernidee“, „Red Flags“, „Anti-Denkmuster“ (Parabel „Speisekarte des Tyrannen“)","kurz":"Die Aussage kennt nur volle Zustimmung oder Feindschaft und blendet aus, dass man das Ziel teilen und einzelne Maßnahmen dennoch kritisieren kann. Dieser Fehler heißt falsches Dilemma; er lässt sich lösen, indem man die fehlenden Positionen benennt.","prueffrage":"Welche der Möglichkeiten im Satz des Sprechers beschreibt deine eigene Haltung zu Ziel und Maßnahmen?","rueckmeldung":[{"option":1,"text":"Eine Dammbruch-Warnung baut eine Kette von Folgen auf, deren Stufen man einzeln prüfen kann. Hier gibt es aber keine Kette: Der Sprecher stellt zwei Pole gegenüber und lässt alles dazwischen weg."},{"option":2,"text":"Kritiker als „Feinde der Gerechtigkeit“ abzustempeln, überzeichnet sie tatsächlich. Der Kern liegt aber woanders: Der Sprecher gibt keine Kritik falsch wieder, sondern lässt nur zwei Haltungen zu; benennen muss man die fehlenden Zwischenpositionen."},{"option":3,"text":"Nach einer unabhängigen Begründung zu fragen, ist an sich ein guter Reflex. Hier führt er aber am Fehler vorbei: Der Sprecher dreht sich nicht im Kreis, er verengt die Auswahl auf zwei Extreme, und das bliebe auch mit guter Begründung so."}],"familie":"falsches-dilemma","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy (Einträge False Dilemma, Black-or-White)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"d74add9a38a3db64"}},{"id":"qd-3","status":"entwurf","clusterId":"D","werkstueckRef":"D.2.5","stufe":3,"question":"Zwei Zeitungsberichte über dieselbe Stadt enthalten identische Kriminalzahlen. Nur der erste Satz unterscheidet sich: Bericht A nennt Kriminalität „ein wildes Tier, das die Stadt heimsucht“, Bericht B nennt sie „ein Virus, das die Stadt infiziert“. Leser von A fordern danach deutlich häufiger Polizei und Gefängnisse, Leser von B häufiger Prävention und Sozialreformen. Gefragt, was ihr Urteil geprägt habe, nennen fast alle die Zahlen. Welche Erklärung ist am sparsamsten?","options":["Das Bild legt unbemerkt fest, welche Lösungen naheliegend wirken, und die Leser schreiben ihr Urteil trotzdem den Zahlen zu.","Die Leser durchschauen die Bildsprache als Manipulation und urteilen aus Trotz entgegengesetzt zum Bild.","Die Berichte liefern unterschiedliche Sachinformationen, daher folgen die Leser schlicht verschiedenen Fakten.","Nur Leser mit Fachwissen reagieren auf Bildsprache, deshalb entsteht der Unterschied zwischen den Gruppen."],"correctIndex":0,"explanation":"Die Zahlen sind in beiden Berichten identisch, also können sie den Unterschied nicht erklären. Ein einzelnes Bild genügt, um den Raum der als plausibel empfundenen Lösungen zu verschieben: Ein Tier verlangt Einsperren und Bekämpfen, ein Virus Diagnose und Heilung. Dass die Leser danach die Statistik als Grund nennen, passt dazu: Der Einfluss wirkt unbemerkt, deshalb suchen sie die Ursache dort, wo sie sie sehen können. Die anderen Erklärungen scheitern an den Angaben: Die Berichte unterscheiden sich nur im Bild des ersten Satzes, nicht in den Sachinformationen, und Trotz gegen die Bildsprache würde voraussetzen, dass die Leser sie als Einfluss wahrnehmen; in der Originalstudie von Thibodeau und Boroditsky (2011) nannten aber nur 15 von 485 Teilnehmenden die Metapher als einflussreich. Dass nur Fachleute reagierten, ist weder im Experiment angelegt noch durch einen Beleg gestützt; der Effekt wurde bei Versuchspersonen allgemein gemessen. Wichtig bleibt die Vorsicht beim Ausmaß: Spätere Studien fanden den Effekt kleiner oder gar nicht, sodass offen ist, wie robust er ist.","coreRule":"⚡ Wenn bei identischen Fakten das Urteil kippt, ist die Formulierung der Verdächtige, auch wenn niemand sie als Einfluss nennt.","quote":"Welches Bild benutzt dieser Text gerade -- und welche Lösung würde ich für naheliegend halten, wenn er stattdessen ein völlig anderes Bild benutzt hätte, bei identischen Fakten?","quoteLabel":"Prüffrage:","scenario":"","beleg":"Werkstück D.2.5; Fußnote gl-d-thibodeau; Anmerkung anm-gl-d-thibodeau (Experiment 1: 74% vs. 56%, 15 von 485 nennen die Metapher). Beleglage: Replikation Steen et al. 2014 ohne Effekt, Metaanalyse Brugman et al. 2019 nur schwach.","kurz":"Die Zahlen sind identisch, also muss das Bild den Unterschied machen: Tier und Virus lassen jeweils andere Lösungen naheliegend wirken. Dass die Leser dennoch die Zahlen nennen, passt dazu, denn der Einfluss bleibt unbemerkt und sie suchen den Grund, den sie sehen können.","prueffrage":"Worin unterscheiden sich die beiden Berichte tatsächlich, und worin nicht?","rueckmeldung":[{"option":1,"text":"Trotz würde voraussetzen, dass die Leser das Bild als Einfluss bemerken; gefragt nennen aber fast alle die Zahlen. Zudem gehen die Urteile in Richtung des Bildes: Tier führt zu Polizei, Virus zu Prävention."},{"option":2,"text":"Unterschiedliche Wirkung lässt zuerst an unterschiedliche Inhalte denken. Beide Berichte enthalten aber dieselben Zahlen, nur der erste Satz mit seinem Bild weicht ab; weitere Informationsunterschiede müsste man hinzuerfinden."},{"option":3,"text":"Von Fachwissen ist nirgends die Rede. Die Annahme fügt eine Bedingung hinzu, die nichts stützt und die niemand braucht: Der Unterschied zwischen beiden Lesergruppen ergibt sich schon aus dem unterschiedlichen Bild."}],"familie":"rahmen-wechseln","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Thibodeau, P. H.; Boroditsky, L. (2011): Metaphors We Think With: The Role of Metaphor in Reasoning. PLoS ONE 6(2), e16782","oeffentlich":true,"doi":"10.1371/journal.pone.0016782","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"fff56b76b040c401"}},{"id":"qd-4","status":"entwurf","clusterId":"D","werkstueckRef":"D.3.2","stufe":2,"question":"Bei Gegenwind wird die radikale Aussage „Unsere Methode heilt jede Krankheit“ plötzlich zu „Ich sage ja nur, dass eine positive Einstellung beim Heilen hilft“. Kaum lässt du die Kritik fallen, wiederholt er die Ausgangsbehauptung wie zuvor. Welche Reaktion ist die klügste?","options":["Du erkennst an, dass beide Aussagen zusammengehören, und widerlegst nur die erste, weil die zweite sie ohnehin stützt.","Du bestreitest auch die zweite Aussage entschieden und ausführlich, damit er keinen Rückzugsort mehr hat.","Du stimmst der vernünftigen zweiten Aussage zu und fragst, ob er weiter dazu steht, dass die Methode jede Krankheit heilt.","Du wirfst ihm vor, unaufrichtig zu sein, und beendest das Gespräch, weil mit ihm keine Diskussion möglich ist."],"correctIndex":2,"explanation":"Die zweite Aussage ist harmlos und weithin akzeptiert, die erste ist außergewöhnlich und nicht belegt. Beide sind nicht dasselbe, denn aus „Einstellung kann beim Heilungsprozess helfen“ folgt nicht „Die Methode heilt jede Krankheit“. Wer bei Kritik auf die harmlose Aussage ausweicht und später zur kühnen zurückkehrt, nutzt die Zustimmung zur einen, um die andere unbemerkt durchzubringen. Das ist die Motte-and-Bailey-Täuschung (so benannt von Nicholas Shackel 2005): eine schwer zu verteidigende Vorburg und ein leicht zu verteidigender Turmhügel, zwischen denen man hin- und herwechselt. Die klügste Reaktion trennt beide Aussagen sauber: Du stimmst dem Vernünftigen zu, ohne dass daraus Zustimmung zum Radikalen wird, und bringst das Gespräch auf die ursprüngliche Behauptung zurück. So muss er sich festlegen. Der Gegner wird weder durch Bestreiten auch der harmlosen Aussage noch durch einen Gesprächsabbruch zur Klarheit gezwungen. Und die zweite Aussage als Stütze der ersten zu behandeln, würde den Fehler selbst begehen.","coreRule":"⚡ Stimme der harmlosen Aussage zu, aber kehre zur ursprünglichen, kühnen Behauptung zurück: Lass den Gegner nicht in den Fluchtturm entwischen.","quote":"Lass uns zur ursprünglichen, viel stärkeren („Bailey“) Aussage zurückkehren, die du zu Beginn gemacht hast. Stehst du immer noch zu dieser?","quoteLabel":"Merksatz","scenario":"Du diskutierst mit einem Anhänger einer spirituellen Bewegung. Er behauptet: „Unsere Methode kann jede Krankheit heilen, Krebs und AIDS eingeschlossen.“ Du fragst nach kontrollierten Studien. Daraufhin sagt er: „Was ich eigentlich meinte: Eine positive Einstellung und spirituelles Wohlbefinden sind wichtig für den Heilungsprozess.“ Dem stimmst du zu, und prompt erklärt er wieder, seine Methode heile jede Krankheit.","kurz":"Du stimmst dem Vernünftigen zu und holst das Gespräch zur ursprünglichen Behauptung zurück, damit er sich festlegen muss. Der Fehler wäre, die harmlose Aussage als Stütze der radikalen zu behandeln, denn aus ihr folgt „heilt jede Krankheit“ gerade nicht.","prueffrage":"Behauptet er am Ende des Gesprächs dasselbe wie am Anfang, oder hat sich zwischendurch etwas verschoben?","rueckmeldung":[{"option":0,"text":"Dass die zweite Aussage vernünftig ist, stimmt. Sie stützt die erste aber nicht: Wer beide als zusammengehörig behandelt, lässt die kühne Behauptung durch, denn aus „Einstellung hilft“ folgt nicht „heilt jede Krankheit“."},{"option":1,"text":"Ihm den Rückzugsort nehmen zu wollen, klingt konsequent. Die zweite Aussage ist aber weithin akzeptiert, sie ausführlich zu bestreiten wäre unbegründet und zwingt ihn nicht, zur ursprünglichen Behauptung Stellung zu nehmen."},{"option":3,"text":"Das ständige Hin und Her ist tatsächlich ärgerlich. Doch der Vorwurf unterstellt eine Absicht, die du nicht kennst, und mit dem Abbruch endet auch die Möglichkeit, ihn auf eine klare Aussage festzulegen."}],"familie":"rueckzug-auf-harmloses","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Shackel, N. (2014): Motte and Bailey Doctrines. Practical Ethics (Oxford Uehiro Centre), Blog, 05.09.2014","oeffentlich":true,"url":"https://blog.uehiro.ox.ac.uk/2014/09/motte-and-bailey-doctrines/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Shackel, N. (2005): The Vacuity of Postmodernist Methodology. Metaphilosophy 36(3), 295–320","oeffentlich":false}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"54e7493c1900681b"}},{"id":"qd-5","status":"entwurf","clusterId":"D","werkstueckRef":"D.3.8","stufe":2,"question":"Eine Rednerin stellt eine Theorie vor, die alle Fachleute für falsch halten. Auf die Kritik antwortet sie: „Über Galilei und Semmelweis haben die Leute damals auch gelacht. Also muss an meiner Theorie etwas dran sein!“ Was ist an diesem Schluss fehlerhaft?","options":["Dass manche Entdecker zunächst abgelehnt wurden, heißt nicht, dass jeder Abgelehnte ein Entdecker ist; abgelehnt wurden auch unzählige Irrtümer.","Die Rednerin verallgemeinert aus zu wenigen Beispielen, denn es gibt nur Galilei und Semmelweis; die Fachwelt hat sich sonst nie geirrt.","Wer von der Fachwelt abgelehnt wird, hat meist ein übersteigertes Geltungsbedürfnis, und deshalb ist die Theorie von vornherein unglaubwürdig.","Eine Theorie ist erst dann ernst zu nehmen, wenn die Mehrheit der Fachwelt sie akzeptiert, bis dahin ist sie für jede Frage wertlos."],"correctIndex":0,"explanation":"Der Schluss kehrt eine Aussage ungültig um: Dass manche spätere Durchbrüche zunächst abgelehnt wurden, sagt nichts darüber, ob jede abgelehnte Idee ein Durchbruch ist. Abgelehnt wurden ebenso zahllose Ideen, die zu Recht verworfen blieben, nur erzählt von denen niemand. Für die Frage, ob eine These stimmt, ist „abgelehnt“ bei beiden Gruppen gleich und trägt deshalb keine Information. Galilei überzeugte, weil seine Beobachtungen (Venusphasen, Jupitermonde) jeder mit einem Fernrohr nachprüfen konnte, nicht weil er auf Widerstand stieß. Dass Fachleute sich irren können, ist richtig, rechtfertigt aber keine einzelne Außenseiter-These; dort entscheiden prüfbare Vorhersagen und Daten. Auch die Gegenposition, erst Mehrheitsbeifall mache eine These wertvoll, ist falsch: Entscheidend sind prüfbare Vorhersagen und Daten, nicht Zustimmung oder Ablehnung.","coreRule":"⚡ Ablehnung ist kein Beweis für Wahrheit: Wo ist dein Fernrohr?","quote":"","quoteLabel":"","scenario":"","kurz":"Aus „Manche späteren Durchbrüche wurden zunächst abgelehnt“ folgt nicht „Jede abgelehnte Idee ist ein Durchbruch“. Abgelehnt wurden auch zahllose Irrtümer, daher sagt die Ablehnung nichts darüber, ob die Theorie stimmt.","prueffrage":"Was hat die Rednerin mit Galilei und Semmelweis nachweislich gemeinsam, und was davon spricht für ihre Theorie?","rueckmeldung":[{"option":1,"text":"Zwei Beispiele sind tatsächlich dünn. Der Fehler liegt aber tiefer: Auch mit hundert Beispielen bliebe der Schluss ungültig. Und die Fachwelt hat sich durchaus schon oft geirrt; das macht aber keine einzelne Außenseiter-These richtig."},{"option":2,"text":"Hier wird die Rednerin als Person bewertet statt ihre Theorie. Selbst wenn ihr Geltungsbedürfnis groß wäre, ließe sich daraus nicht ableiten, ob die Theorie stimmt; das zeigen prüfbare Vorhersagen und Daten."},{"option":3,"text":"Dass die Fachwelt oft verlässlich urteilt, ist ein vernünftiger Anhaltspunkt. Zustimmung selbst entscheidet aber nicht, ob eine These stimmt, und wertlos wäre eine noch unakzeptierte Theorie nicht: Maßgeblich bleiben prüfbare Vorhersagen und Daten."}],"familie":"ablehnung-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Miller, D. M. (Rev. 2025): „Galileo Galilei“, Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/galileo/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Sagan, C. (1979): Broca's Brain: Reflections on the Romance of Science, Kap. 5 „Night Walkers and Mystery Mongers“","oeffentlich":false},{"typ":"url","kurz":"Internet Encyclopedia of Philosophy: „Fallacies“ (Eintrag „Affirming the Consequent“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"a7b559bb9e11c348"}},{"id":"qd-6","status":"entwurf","clusterId":"D","werkstueckRef":"D.3.9","stufe":3,"question":"Was ist an diesem Austausch das Entscheidende?","options":["Lena hat ihre Aussage öffentlich gemacht und muss deshalb jede Nachfrage so lange beantworten, bis der Nutzer zufrieden ist.","Die Nachfragen sind berechtigt, weil Quellen zu verlangen zu jeder Debatte gehört; Lena sollte lediglich ruhiger bleiben.","Der Nutzer nutzt Höflichkeit und Beleg-Forderungen, um Lena zu zermürben; Lena schuldet ihm nach ihren Antworten keine weiteren Belege.","Der Nutzer verpackt eine unbelegte Behauptung in eine Frage, um sie streuen zu können, ohne sie belegen zu müssen; Lena schuldet ihm deshalb keine weitere Antwort."],"correctIndex":2,"explanation":"Wer behauptet, muss belegen – aber einmal, nicht endlos. Ein ehrlich Fragender arbeitet mit der Antwort, prüft sie oder sagt, was ihn noch nicht überzeugt; hier folgt auf jede Antwort nur die nächste Forderung. Dieses Muster heißt Sealioning: Eine Frage kostet Sekunden, eine belegte Antwort oft Stunden, und so wird endloses Nachfragen für den Fragenden billig und für Lena teuer. Quellen zu verlangen ist berechtigt, solange mit den Antworten gearbeitet wird; eine Pflicht zur Dauerverteidigung folgt daraus nicht. Die letzte Frage enthält zwar eine Unterstellung, doch der Nutzer streut keine eigene These, sondern zermürbt Lena mit immer neuen Forderungen.","coreRule":"⚡ Grenze setzen: Du schuldest Belege für deine Behauptung einmal – danach erst wieder, wenn dein Gegenüber mit dem Beleg gearbeitet hat.","quote":"","quoteLabel":"","scenario":"Unter Lenas Beitrag über ihre schlechten Erfahrungen mit einem Paketdienst fragt ein Nutzer freundlich: „Hast du dafür eine Quelle?“ Lena nennt eine Verbraucherumfrage. Er antwortet: „Danke! Und eine zweite?“ Dann: „Was meinst du genau mit ‚schlecht'?“ Dann: „Warum wirst du jetzt unfreundlich?“ Auf keine ihrer drei Antworten geht er inhaltlich ein.","beleg":"Werkstück D.3.9, Fußnote gl-d-sealioning: Malki, D. (2014): „The Terrible Sea Lion“. Wondermark Nr. 1062; Johnson, A. (2017): „The Multiple Harms of Sea Lions“.","kurz":"Wer behauptet, muss belegen, aber einmal. Lena hat geantwortet, der Nutzer arbeitet mit nichts davon und fordert nur Neues, was Lena erschöpft. Hier zählt nicht der freundliche Ton einer Frage, sondern ob die Antworten verarbeitet werden.","prueffrage":"Was macht der Nutzer mit Lenas Antworten, bevor er die nächste Frage stellt?","rueckmeldung":[{"option":0,"text":"Lena muss ihre Aussage tatsächlich belegen, und das hat sie getan. Daraus folgt aber keine Pflicht, so lange weiterzuantworten, bis jemand zufrieden ist; belegen muss sie einmal, nicht endlos."},{"option":1,"text":"Eine Quellenfrage gehört zur Debatte, und die erste war berechtigt. Das gilt aber nur, solange mit den Antworten gearbeitet wird; hier geht der Nutzer auf keine ein. Dass Lena unfreundlich wurde, unterstellt nur er."},{"option":3,"text":"Die Frage nach Lenas Unfreundlichkeit enthält tatsächlich eine Unterstellung. Der Kern ist aber ein anderer: Der Nutzer verlangt immer neue Belege, ohne mit den Antworten zu arbeiten, und zermürbt Lena so."}],"familie":"kraefte-und-ausstieg","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Johnson, A. (2017): „The Multiple Harms of Sea Lions“, in: Perspectives on Harmful Speech Online, Berkman Klein Center, Harvard","oeffentlich":true,"url":"https://cyber.harvard.edu/sites/cyber.harvard.edu/files/2017-08_harmfulspeech.pdf","seite":"S. 13","abruf":"2026-10-12"},{"typ":"url","kurz":"Malki, D. (2014): „The Terrible Sea Lion“, Wondermark Nr. 1062","oeffentlich":true,"url":"https://wondermark.com/c/1062/","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"c100daa0f6ce352d"}},{"id":"qd-7","status":"entwurf","clusterId":"D","werkstueckRef":"D (Kasten zu den Etiketten)","stufe":2,"question":"Jemand sagt: „Schau dir diesen heißen Sommer an, der Klimawandel ist real!“ Das verwechselt Wetter und Klima. Was folgt daraus für die Schlussfolgerung, dass sich das Klima erwärmt?","options":["Sie ist damit widerlegt, denn ein fehlerhaftes Argument macht seine Schlussfolgerung zwangsläufig falsch.","Sie bleibt davon unberührt: Das Argument ist schwach, aber den Trend zeigen Messreihen über Jahrzehnte, egal wie schlecht ihn jemand verteidigt.","Sie ist bestätigt, weil Wetter und Klima im Kern dasselbe messen und der heiße Sommer ein gültiges Beispiel dafür ist.","Sie lässt sich nie beurteilen, weil jede Aussage über Wetter oder Klima von Einzelereignissen abhängt und nichts belegt."],"correctIndex":1,"explanation":"Ein fehlerhaftes Argument stützt seine Schlussfolgerung nicht; falsch wird sie dadurch aber nicht. Wer aus dem Fehler folgert, an der Erwärmung sei nichts dran, begeht selbst einen Fehlschluss, den sogenannten Fehlschluss-Fehlschluss. Auch ein Name für einen Denkfehler widerlegt noch nichts: Es kommt auf die Belege für die Schlussfolgerung selbst an. Für die Erwärmung sind das langjährige Messreihen, nicht ein einzelner heißer Sommer.","coreRule":"⚡ Ein schlechtes Argument macht den Schluss nicht falsch: Prüfe die Schlussfolgerung getrennt vom Argument.","quote":"Ein Name für einen Denkfehler widerlegt noch nichts.","quoteLabel":"Merksatz:","kurz":"Der schwache Beleg widerlegt die Schlussfolgerung nicht, er stützt sie nur nicht. Wer aus dem Fehler schließt, an der Erwärmung sei nichts dran, macht selbst einen Fehler. Entscheidend sind die Belege zur Sache.","prueffrage":"Wenn der nächste Sommer kühl ausfiele, was wüsstest du dann über das Klima?","rueckmeldung":[{"option":0,"text":"Wer ein schlechtes Argument entdeckt, hält die Behauptung schnell für entlarvt. Das Argument trägt sie zwar nicht, über ihre Wahrheit sagt der Fehler aber nichts. Sie kann aus ganz anderen Gründen zutreffen."},{"option":2,"text":"Beides spielt sich in der Atmosphäre ab, deshalb wirkt es gleichartig. Wetter beschreibt aber das kurzfristige Geschehen, Klima den Durchschnitt über Jahrzehnte. Ein einzelner heißer Sommer kann ein Ausreißer sein und belegt keinen Trend."},{"option":3,"text":"Dass ein Einzelereignis nichts beweist, stimmt. Daraus folgt aber nicht, dass sich die Aussage nie beurteilen ließe: Langjährige Messreihen zeigen, ob sich das Klima verändert. Man muss nur an der richtigen Stelle nach Belegen suchen."}],"familie":"fehlschluss-macht-nichts-falsch","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Internet Encyclopedia of Philosophy: „Validity and Soundness“ (anonymer Verfasser)","oeffentlich":true,"url":"https://iep.utm.edu/val-snd/","abruf":"2026-10-12"},{"typ":"doi","kurz":"IPCC (2021): Summary for Policymakers. Climate Change 2021: The Physical Science Basis, WG I, AR6","oeffentlich":true,"doi":"10.1017/9781009157896.001","seite":"Abschnitt A.1.2","abruf":"2026-10-04"},{"typ":"literatur","kurz":"Novella, S. u. a. (2018): The Skeptics' Guide to the Universe, Kap. 10, Abschnitt „Fallacy Fallacy“ (E-Book ohne Seitenzahlen)","oeffentlich":false}],"thema":"Natur und Klima"},{"id":"qd-8","status":"entwurf","clusterId":"D","werkstueckRef":"D.3.8","stufe":3,"question":"Ein Redner sagt: „Mein Plan wird von allen Fachleuten abgelehnt. Das ist ein gutes Zeichen, denn auch Kolumbus wurde verlacht, und am Ende hatte er recht.“ Du schaust nach: Eine Kommission hat Kolumbus' Plan damals tatsächlich abgelehnt. Was ist die stärkste Antwort auf das Argument des Redners?","options":["Der Vergleich trägt: Die Kommission hielt die Erde für eine Scheibe, wurde von der Seefahrt widerlegt, und genauso wird es den Kritikern des Redners ergehen.","Der Vergleich trägt nicht: Ablehnung trifft Genies wie Irrtümer, und Kolumbus' Kritiker hatten sogar recht, weil er sich verrechnet hatte.","Der Vergleich trägt nicht: Kolumbus wurde nie abgelehnt, denn die Kommission hat seinen Plan damals sofort und ohne Einwände angenommen.","Der Vergleich trägt: Die Fachleute lehnten den Plan ab und Kolumbus erreichte am Ende doch Land, also kann Ablehnung ein Hinweis auf Richtigkeit sein."],"correctIndex":1,"explanation":"Das Argument des Redners schließt von „Manche Genies wurden abgelehnt“ auf „Wer abgelehnt wird, ist ein Genie“. Das ist ein ungültiger Schluss: Auch über Bozo den Clown wurde gelacht (Carl Sagan). Dazu kommt, dass das Beispiel selbst nicht passt. Die königliche Kommission unter Hernando de Talavera lehnte den Plan 1490 zwar ab, aber keiner ihrer Einwände stellte die Kugelgestalt der Erde in Frage. Sie hielt den Ozean für zu breit, und ihre Zweifel waren berechtigt, weil Kolumbus seine Rechnung geschönt hatte. Die Kritiker hatten also recht. Die Ablehnung durch Fachleute ist für echte Außenseiter und für Irrtümer dieselbe, sie ist daher kein Beleg. Ein Beleg wäre eine prüfbare Vorhersage, die der Redner vorlegen müsste.","coreRule":"⚡ Ablehnung durch Fachleute ist kein Beweis: Sie trifft Genies und Irrtümer gleichermaßen, und die berühmten Beispiele stimmen oft nicht.","quote":"","quoteLabel":"","scenario":"","kurz":"Dass auch Genies abgelehnt wurden, macht nicht jeden Abgelehnten zum Genie, denn Irrtümer werden genauso abgelehnt. Außerdem passt das Beispiel nicht: Die Kritiker an Kolumbus' Plan hatten recht, weil er sich verrechnet hatte.","prueffrage":"Womit begründete die Kommission damals ihre Ablehnung, und erreichte Kolumbus eigentlich das Ziel, das er angekündigt hatte?","rueckmeldung":[{"option":0,"text":"Die Geschichte mit der Erdscheibe ist bekannt und passt gut in die Erzählung vom verlachten Entdecker. Die Kommission bezweifelte aber nicht die Kugelgestalt, sondern hielt den Ozean für zu breit, und damit lag sie richtig."},{"option":2,"text":"Der Einwand sucht den Fehler im Beispiel, doch die Ablehnung durch die Kommission ist historisch belegt, so steht es auch in deiner Recherche. Mit dieser Behauptung ginge die berechtigte Kritik am Argument verloren."},{"option":3,"text":"Ablehnung und späterer Erfolg gab es bei Kolumbus tatsächlich. Daraus folgt aber nichts für den Redner: Auch Irrtümer werden abgelehnt, und Kolumbus' Kritiker hatten mit ihrer Rechnung recht. Ein Hinweis auf Richtigkeit ist die Ablehnung nicht."}],"familie":"ablehnung-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"literatur","kurz":"Russell, J. B. (1991): Inventing the Flat Earth: Columbus and Modern Historians. New York: Praeger","oeffentlich":false},{"typ":"literatur","kurz":"Sagan, C. (1979): Broca's Brain, Kap. 5 („Bozo the Clown“-Zitat)","oeffentlich":false},{"typ":"url","kurz":"Internet Encyclopedia of Philosophy: „Fallacies“ (Eintrag „Affirming the Consequent“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"42274fd677150796"}},{"id":"qd-9","status":"entwurf","clusterId":"D","werkstueckRef":"D (Einleitung, Prebunking)","stufe":4,"question":"Ein Medienbildungsprojekt wirbt: „Nach unseren kurzen Prebunking-Videos erkennen Menschen manipulative Tricks nachweislich besser.“ Ein Kollege antwortet: „Dann ist das Problem der Desinformation ja gelöst.“ Welche Reaktion wird der Sachlage am besten gerecht?","options":["Das Ergebnis ist nützlich, aber begrenzt: Ein Effekt von rund fünf Prozent, binnen eines Tages gemessen, rechtfertigt weder Triumph noch Abwinken.","Ein so kleiner Effekt zeigt, dass Prebunking wirkungslos ist und man das Geld besser woanders einsetzt.","Weil die Wirkung nachgewiesen ist, kann man davon ausgehen, dass sie sich auch nach Wochen unverändert hält.","Der Effekt gilt für jede Art von Desinformation gleichermaßen, also genügt ein kurzes Video als vollständige Lösung."],"correctIndex":0,"explanation":"Wer Wirkung und Grenze zusammen nennt, urteilt am genauesten. Die Forschung zur Inokulation zeigt, dass sich das Erkennen solcher Techniken schulen lässt, aber nur in Grenzen: Im Feldversuch auf YouTube (22.632 Antworten, Roozenbeek u. a. 2022, Science Advances) stieg die Erkennung im Mittel um rund 5 % und verfehlte knapp die vorab festgelegte kleinste bedeutsame Effektgröße. „Messbar“ heißt also nicht „groß“, und „klein“ heißt nicht „null“. Ein Schluss auf Wochen oder auf alle Formen von Desinformation wäre über die Messung hinausgeschossen, denn gemessen wurde innerhalb eines Tages und nur bei bestimmten Kniffen. Und dass ein Problem „gelöst“ sei, folgt aus einem Effekt dieser Größe erst recht nicht.","coreRule":"⚡ Prebunking hilft, aber der Effekt ist begrenzt: Nenne Wirkung und Grenze zusammen.","quote":"","quoteLabel":"","scenario":"Prebunking bedeutet: Man zeigt Menschen vorab kurz, wie typische Manipulationskniffe funktionieren (etwa emotional aufgeladene Sprache oder falsche Dilemmata), bevor sie ihnen im Netz begegnen. In einem Feldversuch auf YouTube mit rund 22.600 Antworten stieg die Erkennung solcher Kniffe im Mittel um etwa 5 %, gemessen innerhalb eines Tages.","kurz":"Der Effekt ist messbar, aber klein: rund 5 % mehr Erkennung, gemessen innerhalb eines Tages. Weder „Problem gelöst“ noch „wirkungslos“ trifft das; genauer urteilt, wer Wirkung und Grenze zusammen nennt.","prueffrage":"Welche Formen von Desinformation und welche Zeitspanne hat der Feldversuch überhaupt erfasst?","rueckmeldung":[{"option":1,"text":"Ein kleiner Effekt lässt sich leicht als Misserfolg lesen. Klein heißt aber nicht null: Die Erkennung stieg messbar, und ob sich der Aufwand lohnt, folgt aus dieser einen Zahl allein nicht."},{"option":2,"text":"Nachgewiesene Effekte wirken leicht dauerhaft. Gemessen wurde hier aber nur innerhalb eines Tages, und was nach Wochen davon übrig bleibt, sagt diese Messung nicht."},{"option":3,"text":"Dass sich Erkennen schulen lässt, stimmt. Gemessen wurden aber nur bestimmte Kniffe, und ein Zuwachs von rund 5 % macht aus einem kurzen Video keine vollständige Lösung für jede Art von Desinformation."}],"familie":"befund-reichweite","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Roozenbeek, J. u. a. (2022): Psychological inoculation improves resilience against misinformation on social media. Science Advances 8(34), eabo6254","oeffentlich":true,"doi":"10.1126/sciadv.abo6254","seite":"S. 1 und 4–5 (laut Belegregister)","abruf":"2026-10-12"}],"thema":"Netz und Medien"},{"id":"qe-1","status":"entwurf","clusterId":"E","werkstueckRef":"E.1.1","stufe":1,"question":"Ein Freund sagt: „Ein Ball und ein Schläger kosten zusammen 1,10 €, der Schläger kostet genau 1 € mehr als der Ball. Der Ball kostet also 10 Cent – das sah ich sofort.“ Was ist hier der beste Rat?","options":["Die schnelle Antwort ist nur dann sicher, wenn sie sich sofort richtig anfühlt, deshalb sollte er ihr vertrauen.","Er sollte nachrechnen und prüfen, ob beide genannten Bedingungen zusammen stimmen.","Er sollte die Rechnung ignorieren, denn bei so einfachen Zahlen liegt das erste Gefühl meist richtig.","Er sollte nach dem Kassenbon fragen, denn ohne den echten Preis lässt sich die Aufgabe nicht prüfen."],"correctIndex":1,"explanation":"Mit 10 Cent für den Ball müsste der Schläger 1,10 € kosten, zusammen wären das 1,20 €. Die Bedingung „zusammen 1,10 €“ ist verletzt. Richtig ist: Der Ball kostet 5 Cent, der Schläger 1,05 €. Gerade bei Aufgaben, die sich auf den ersten Blick mühelos lösen lassen, lohnt sich die Gegenprobe, denn dass sich eine Antwort sofort richtig anfühlt, sagt nichts darüber, ob sie stimmt. Bei dieser Aufgabe liegt die intuitive Antwort bei vielen Menschen daneben, und selbst wer richtig rechnet, denkt oft zuerst an 10 Cent. Wer die Probe macht, setzt das langsame, bewusste Denken ein und fängt den Fehler des schnellen, intuitiven Denkens ab.","coreRule":"Fühlt sich eine Antwort sofort richtig an, mach die Gegenprobe: Stimmen alle Bedingungen gemeinsam?","quote":"","quoteLabel":"","scenario":"","kurz":"Mit 10 Cent für den Ball käme der Schläger auf 1,10 €, zusammen also 1,20 €. Dass sich eine Antwort sofort richtig anfühlt, ist kein Beleg; erst die Gegenprobe zeigt, ob beide Bedingungen stimmen.","prueffrage":"Wenn der Ball 10 Cent kostet und der Schläger einen Euro mehr, was kosten dann beide zusammen?","rueckmeldung":[{"option":0,"text":"Schnelle Urteile liegen oft richtig, und ein sicheres Gefühl ist angenehm. Es sagt aber nichts darüber, ob das Ergebnis stimmt, und hier liegt gerade die intuitive Antwort bei vielen daneben."},{"option":2,"text":"Einfache Zahlen laden dazu ein, dem ersten Eindruck zu folgen. Gerade dann lohnt die Gegenprobe: Hier ergibt sie 1,20 € statt 1,10 €, die Aufgabe ist nur scheinbar mühelos."},{"option":3,"text":"Eine Prüfung braucht eine Grundlage, die hat er aber schon: Die beiden genannten Bedingungen genügen, um die Antwort nachzurechnen. Ein Kassenbon ist dafür nicht nötig."}],"familie":"innehalten-bei-druck","fertigkeit":"F5","quellen":[{"typ":"doi","kurz":"Frederick, S. (2005): Cognitive Reflection and Decision Making. Journal of Economic Perspectives 19(4), S. 25–42","oeffentlich":true,"doi":"10.1257/089533005775196732","abruf":"2026-10-12"},{"typ":"url","kurz":"Kahneman, D. (2002): Maps of Bounded Rationality: A Perspective on Intuitive Judgment and Choice. Nobelpreis-Vortrag, Nobel Foundation","oeffentlich":true,"url":"https://www.nobelprize.org/uploads/2018/06/kahnemann-lecture.pdf","seite":"PDF-S. 3","abruf":"2026-10-12"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"caf67a1a45ebd9b3"}},{"id":"qe-2","status":"entwurf","clusterId":"E","werkstueckRef":"E.1.2","stufe":2,"question":"Was ist die sparsamste Erklärung für diesen Befund?","options":["Die gut bezahlte Gruppe hat der Aufgabe gegenüber Misstrauen entwickelt und sie deshalb im Nachhinein besonders streng bewertet.","Mit nur 1 Dollar lässt sich die Lüge kaum rechtfertigen, also passen die Studierenden ihre Einstellung zur Aufgabe an.","Die 1-Dollar-Gruppe hat die Aufgabe besser erledigt und ihr deshalb im Rückblick mehr Wert zugeschrieben.","Die 20-Dollar-Gruppe hat sich bei der Bewertung nicht ernsthaft Mühe gegeben, weil ihr das Geld wichtiger war."],"correctIndex":1,"explanation":"Wer gegen seine Überzeugung redet, erlebt einen Widerspruch zwischen seinem Selbstbild und seinem Verhalten. Bei 20 Dollar gibt es eine bequeme Begründung („Ich hab’s für das Geld getan“), der Widerspruch bleibt klein. Bei 1 Dollar fehlt diese Begründung: „Ich bin ein ehrlicher Mensch“ und „Ich habe für einen mickrigen Dollar gelogen“ passen schlecht zusammen. Der einfachste Ausweg ist, die eigene Einstellung nachzujustieren: „Eigentlich war die Aufgabe gar nicht so langweilig.“ Die anderen Antworten führen Gründe an, für die im Versuch nichts spricht: Weder Misstrauen noch bessere Leistung noch mangelnde Mühe sind belegt. Allerdings ist die Befundlage nicht ganz so eindeutig, wie sie klingt: Eine große Wiederholung testete nicht die 1-/20-Dollar-Anordnung selbst, sondern eine Variante desselben Paradigmas (Aufsatz gegen die eigene Überzeugung, Wahlfreiheit statt Bezahlung) und fand den erwarteten Effekt der Wahlfreiheit nicht. Die Erklärung gilt daher als plausibel, nicht als endgültig bewiesen.","coreRule":"⚡ Wenn Verhalten und Überzeugung kollidieren, passen wir oft die Überzeugung an, vor allem dann, wenn eine äußere Rechtfertigung fehlt.","quote":"","quoteLabel":"","scenario":"In einem Experiment mussten Studierende eine extrem langweilige Aufgabe erledigen. Danach sollten sie dem nächsten Teilnehmer erzählen, die Aufgabe sei interessant gewesen. Die einen bekamen dafür 20 Dollar, die anderen nur 1 Dollar. Später sollten alle die Aufgabe bewerten: Die 1-Dollar-Gruppe fand sie deutlich interessanter als die 20-Dollar-Gruppe.","beleg":"Werkstück E.1.2; Fn. gl-e-festinger (Festinger & Carlsmith 1959; Replikation Vaidis u. a. 2024 mit Einschränkung) und Anm. anm-gl-e-festinger","kurz":"Mit 1 Dollar fehlt eine bequeme Begründung für die Lüge, also wird die eigene Einstellung nachjustiert. Misstrauen, bessere Leistung oder Unlust wären Zusatzannahmen, für die der Versuch nichts liefert; endgültig bewiesen ist aber auch diese Erklärung nicht.","prueffrage":"Worin unterscheiden sich die beiden Gruppen außer in der Bezahlung überhaupt?","rueckmeldung":[{"option":0,"text":"Dass die Bezahlung den Unterschied ausmacht, ist ein guter Ansatz. Misstrauen der 20-Dollar-Gruppe wird im Versuch aber nirgends sichtbar, die Erklärung fügt eine Annahme hinzu, für die es keinen Beleg gibt."},{"option":2,"text":"Eine bessere Leistung der 1-Dollar-Gruppe könnte höhere Wertschätzung erklären, doch dafür gibt es keinen Hinweis. Alle erledigten dieselbe langweilige Aufgabe; ein Leistungsunterschied wäre reine Spekulation."},{"option":3,"text":"Geld kann tatsächlich die Motivation verschieben. Für mangelnde Mühe der 20-Dollar-Gruppe gibt es hier aber keinen Hinweis, und sie erklärt nicht, warum die 1-Dollar-Gruppe die Aufgabe als so interessant erlebt."}],"familie":"selbstrechtfertigung-erkennen","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Festinger, L.; Carlsmith, J. M. (1959): Cognitive Consequences of Forced Compliance. Journal of Abnormal and Social Psychology 58(2), S. 203–210 (Volltext: Classics in the History of Psychology, York University)","oeffentlich":true,"url":"https://psychclassics.yorku.ca/Festinger/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Vaidis, D. C. u. a. (2024): A Multilab Replication of the Induced-Compliance Paradigm of Cognitive Dissonance. Advances in Methods and Practices in Psychological Science 7(1)","oeffentlich":true,"doi":"10.1177/25152459231213375","url":"https://research-repository.uwa.edu.au/en/publications/cea91f86-625c-4f4d-85ff-d41f3d22a503","abruf":"2026-10-12"},{"typ":"url","kurz":"Solovjeva, M.; Buttlar, B.; Daniel, A.; Vaidis, D. C. (2026): Cognitive Dissonance. In: Rahal, R.-M. (Hg.): Open Social Psychology. Open Press Tilburg University (CC BY 4.0)","oeffentlich":true,"url":"https://forrt.org/open-social-psychology/chapter3.html","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"4bb787bc4bbb64fc"}},{"id":"qe-3","status":"entwurf","clusterId":"E","werkstueckRef":"E.2.2","stufe":2,"question":"Ein Kommilitone sagt: „Dass fast zwei Drittel der Teilnehmer in Milgrams Gehorsamsexperiment bis zum vermeintlich tödlichen Schock gingen, zeigt, dass die meisten Menschen im Kern grausam sind.“ Welche Reaktion prüft diese Schlussfolgerung am besten?","options":["Man fragt, ob die Persönlichkeit das Verhalten allein erklärt oder ob die Situation (Autorität, Verantwortungsabgabe, kleine Schritte) mitentscheidend war.","Man fragt, ob die Teilnehmer vorher einen Persönlichkeitstest gemacht haben, denn nur dann lässt sich überhaupt etwas über ihren Charakter sagen.","Man fragt, ob die Mehrheit aller Menschen so gehandelt hätte, denn nur eine Mehrheit zeigt, was als normal gelten darf und was nicht.","Man fragt, ob die Teilnehmer ihr Verhalten später bereut haben, denn nur dann war es wirklich ein Fehler und kein vernünftiges Handeln."],"correctIndex":0,"explanation":"Die Schlussfolgerung springt von einem Verhalten in einer ganz bestimmten Situation auf einen Charakterzug. Dabei war die Situation sehr speziell: Eine angesehene Institution, ein Versuchsleiter, der die Verantwortung übernahm, und Schocks, die in 15-Volt-Schritten langsam stiegen, sodass es nie eine klare Grenze zum Aufhören gab. Wie stark die Situation wirkt, zeigt sich auch daran, dass die Gehorsamsquote in den Varianten des Experiments zwischen null und über neunzig Prozent schwankte, je nachdem, wie Autorität, Distanz zum Opfer und Rahmen gestaltet waren. Wer ein Verhalten erklärt, muss deshalb zuerst prüfen, welchen Anteil die Umstände haben, bevor er auf feste Eigenschaften der Person schließt. Dass Menschen unter starkem situativem Druck oft gehorchen, heißt nicht, dass sie im Kern böse sind.","coreRule":"⚡ Erkläre Verhalten nicht vorschnell mit Charakter: Prüfe zuerst, welche Kraft die Situation hatte.","quote":"","quoteLabel":"","scenario":"","beleg":"Werkstück E.2.2; Fußnote gl-e-milgram (Milgram 1963: 26 von 40 = 65 % bis 450 V). Die Schwankungsbreite der Gehorsamsquote von null bis über neunzig Prozent in den Varianten steht im Fließtext des Abschnitts „Die situativen Faktoren des Gehorsams“; Fußnote gl-e-milgram-varianten verweist dazu auf Milgram 1974 und Haslam/Reicher 2012. Die Frage wurde von der reinen Prozentabfrage zur Denkaufgabe (Fundamentaler Attributionsfehler: Situation vs. Charakter) umgebaut.","kurz":"Aus Verhalten in einer sehr besonderen Lage folgt nicht automatisch ein Charakterzug. Gehorsam schwankte je nach Autorität und Rahmen zwischen null und über neunzig Prozent, also muss man zuerst klären, wie viel die Umstände erklären.","prueffrage":"Welches Verhalten wurde in welcher Lage beobachtet, und auf welche Eigenschaft schließt der Kommilitone daraus?","rueckmeldung":[{"option":1,"text":"Ein Persönlichkeitstest wirkt methodisch sauber, und Charakter kann durchaus mitspielen. Er klärt aber nicht, wie viel die Umstände ausmachen; genau das zeigen die Varianten mit stark schwankender Gehorsamsquote."},{"option":2,"text":"Zu fragen, wie verbreitet das Verhalten ist, klingt nach einem Maßstab. Häufigkeit sagt aber nichts über den Grund des Verhaltens und nichts darüber, was richtig ist. Ob Situation oder Charakter entscheidend war, bleibt damit offen."},{"option":3,"text":"Spätere Reue sagt etwas darüber, wie die Teilnehmer ihr Handeln sahen. Warum sie damals gehorchten, erklärt sie nicht. Und ob etwas ein Fehler war, hängt nicht davon ab, ob man es bereut."}],"familie":"umstaende-vor-absicht","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Milgram, S. (1963): Behavioral Study of Obedience. Journal of Abnormal and Social Psychology 67(4), S. 371–378 (Kopie auf einer Seite der University of Miami)","oeffentlich":true,"url":"https://www.psy.miami.edu/_assets/pdf/rpo-articles/milgram-1963.pdf","abruf":"2026-10-12"},{"typ":"url","kurz":"Uzelac, E.; Yang, Y.-F. (2026): Obedience to Authority. In: Rahal, R.-M. (Hg.): Open Social Psychology. Open Press Tilburg University (CC BY 4.0)","oeffentlich":true,"url":"https://forrt.org/open-social-psychology/chapter4.html","abruf":"2026-10-12"},{"typ":"doi","kurz":"Haslam, S. A.; Reicher, S. D. (2012): Contesting the ‚Nature‘ of Conformity: What Milgram and Zimbardo’s Studies Really Show. PLOS Biology 10(11), e1001426","oeffentlich":true,"doi":"10.1371/journal.pbio.1001426","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"6a910b37caa9ff8c"}},{"id":"qe-4","status":"entwurf","clusterId":"E","werkstueckRef":"E.2.4","stufe":1,"question":"In einer Finanzausschuss-Sitzung wird ein Kraftwerksprojekt für 10 Millionen Euro in zweieinhalb Minuten abgenickt. Über einen Fahrradschuppen für 350 Euro wird 45 Minuten gestritten: Holz oder Aluminium, Blau oder Grün. Welche Erklärung für diesen Verlauf ist am plausibelsten?","options":["Beim Schuppen kann jeder mitreden und sich profilieren, beim Kraftwerk fehlt vielen das Verständnis für kluge Fragen, und niemand will unwissend wirken.","Der Ausschuss hält das Kraftwerk für so wichtig, dass er es besonders sorgfältig vorbereitet hat und daher kaum noch Diskussionsbedarf bestand.","Der Fahrradschuppen ist für die Beteiligten finanziell riskanter, deshalb prüfen sie ihn gründlicher als das Kraftwerk.","Bei großen Summen einigt sich eine Gruppe erfahrungsgemäß schneller, weil sie dann stärker auf die Einschätzung der Fachleute vertraut."],"correctIndex":0,"explanation":"Die Zeit, die eine Gruppe auf ein Thema verwendet, folgt nicht der Wichtigkeit, sondern der Mitredbarkeit. Zum Fahrradschuppen hat jeder eine Meinung, und mit einem Vorschlag zur Farbe lässt sich Kompetenz risikolos zeigen. Beim Kraftwerk ist das anders: Die Technik ist komplex, und wer eine Frage stellt, riskiert, unwissend zu wirken. Also schweigen viele, und der Antrag wird durchgewunken. Dass das Kraftwerk besonders gründlich vorbereitet war, ist im Szenario nirgends angelegt. Es wäre eine bloße Zusatzannahme und würde nicht erklären, warum der Fahrradschuppen so lange debattiert wird. Auch das Argument finanzieller Risiken passt nicht, denn 350 Euro sind kaum ein Risiko. Und dass die Gruppe bei großen Summen einfach den Fachleuten vertraut, trifft es nicht: Sätze wie „Das überlassen wir den Experten“ sind ein Warnsignal, mit dem komplexe Themen schnell vom Tisch gewischt werden. Das ist ein Symptom des Musters, nicht seine Erklärung. Dieses Muster hat C. Northcote Parkinson 1957 satirisch als „Gesetz der Trivialität“ (Bikeshedding) beschrieben.","coreRule":"⚡ Teile Sitzungszeiten nach Budget und Risiko ein, nicht nach Streitlust!","quote":"Die Debatte über das Atomkraftwerk dauert exakt zweieinhalb Minuten.","quoteLabel":"Merksatz:","scenario":"","beleg":"Werkstück E.2.4, Fußnote gl-e-parkinson: Parkinson, Parkinson's Law, and Other Studies in Administration (1957), Kapitel „High Finance, or The Point of Vanishing Interest“; Beispiel Reaktor vs. Fahrradschuppen.","kurz":"Die Redezeit richtet sich nach der Mitredbarkeit, nicht nach der Bedeutung: Zum Schuppen hat jeder eine Meinung, und beim Kraftwerk riskiert eine Frage, unwissend zu wirken. Wichtigkeit allein erklärt den Verlauf nicht.","prueffrage":"Worum ging es im Streit über den Schuppen, und wie viel stand dabei auf dem Spiel?","rueckmeldung":[{"option":1,"text":"Eine gründliche Vorbereitung würde tatsächlich Diskussion ersparen, von ihr ist aber nirgends die Rede. Und sie erklärt nicht, warum über Farbe und Material des Schuppens 45 Minuten gestritten wird."},{"option":2,"text":"Mit Risiko lässt sich eine längere Prüfung gut begründen. Hier ist es aber umgekehrt: Beim Schuppen stehen 350 Euro auf dem Spiel, beim Kraftwerk 10 Millionen. Die Prüfzeit folgt dem Risiko also gerade nicht."},{"option":3,"text":"Vertrauen in Fachleute kommt vor und kann berechtigt sein. Oft steckt hinter „Das überlassen wir den Experten“ aber Scheu, Fragen zu stellen. Der Satz ist dann ein Symptom des Musters und erklärt nicht, warum der Verlauf so ausfällt."}],"familie":"aufmerksamkeit-nach-folgen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Wikipedia: Law of triviality (Sekundärquelle)","oeffentlich":true,"url":"https://en.wikipedia.org/wiki/Law_of_triviality","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Parkinson, C. N. (1957): Parkinson's Law, and Other Studies in Administration. Boston: Houghton Mifflin, Kap. „High Finance, or The Point of Vanishing Interest“","oeffentlich":false}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"7bfb8e4cf2a1e970"}},{"id":"qe-5","status":"entwurf","clusterId":"E","werkstueckRef":"E.3.2","stufe":2,"question":"Ein Freund sagt: „Geld ist doch nur bedrucktes Papier. Es hat keinen echten Wert, also existiert es gar nicht wirklich.“ Welche Antwort trifft die Sachlage am besten?","options":["Geld ist zwar nur Papier, aber gerade deshalb unwirklich: Es wirkt nur, weil man sich einbildet, es habe Wert.","Geld hat keinen eigenen Stoffwert, wirkt aber trotzdem, weil sehr viele Menschen gemeinsam darauf vertrauen und danach handeln.","Geld ist real, weil der Staat es per Gesetz verordnet hat und es deshalb in jedem Land der Welt gleich viel wert ist.","Geld ist real, weil es wie ein Baum oder ein Berg unabhängig davon existiert, was Menschen darüber denken."],"correctIndex":1,"explanation":"Der Freund verwechselt „keine physische Existenz“ mit „nicht wirklich vorhanden“. Es gibt nicht nur zwei Kategorien, die objektive Realität (ein Baum, die Schwerkraft) und die rein persönliche (ein Traum, ein Kopfschmerz). Geld gehört zu einer dritten: Es existiert im gemeinsamen Glauben und in der Kommunikation eines großen Netzwerks von Menschen. Der Test zeigt den Unterschied: Wenn du allein aufhörst, an den Euro zu glauben, bist du nicht erleuchtet, sondern pleite. Ein Schimpanse nimmt dagegen eine Banane, aber keinen Geldschein, weil er nicht Teil dieses Netzwerks des Glaubens ist. Und weil Geld vom gemeinsamen Glauben abhängt, kann es zusammenbrechen, wenn eine kritische Masse von Menschen aufhört, an die gemeinsame Geschichte zu glauben; ein Beispiel dafür ist der Wertverfall einer Währung bei Hyperinflation. Ein Berg verschwindet dagegen nicht, nur weil niemand mehr an ihn denkt.","coreRule":"⚡ Real ist nicht nur, was man anfassen kann: Vieles wirkt, weil viele gemeinsam daran glauben und danach handeln.","quote":"","quoteLabel":"","scenario":"","kurz":"Geld hat keinen Stoffwert, wirkt aber, weil sehr viele Menschen darauf vertrauen und danach handeln. Der Fehler: „nicht physisch“ mit „nicht wirklich“ gleichzusetzen. Es gibt neben Baum und Traum eine dritte Art von Wirklichkeit, den gemeinsamen Glauben.","prueffrage":"Was passiert morgen an der Supermarktkasse, wenn du mit einem Zwanzig-Euro-Schein bezahlst?","rueckmeldung":[{"option":0,"text":"Daran stimmt, dass Geld ohne gemeinsames Vertrauen wertlos wäre. „Unwirklich“ ist es deshalb aber nicht: Wer allein nicht mehr an den Euro glaubt, ist nicht erleuchtet, sondern pleite. Geld wirkt, weil es kein bloßes Hirngespinst Einzelner ist."},{"option":2,"text":"Der Staat stützt Währungen tatsächlich, doch ihr Wert hängt am Vertrauen vieler, nicht allein am Gesetz. Gleich viel wert ist Geld auch nicht überall: Währungen haben verschiedene Kurse, und bei Hyperinflation schützt kein Gesetz vor dem Verfall."},{"option":3,"text":"Dass Geld real ist, stimmt. Die Begründung trägt aber nicht: Ein Berg bleibt, auch wenn niemand an ihn denkt, Geld dagegen nicht. Sein Wert hängt am gemeinsamen Glauben und kann zusammenbrechen, wenn genug Menschen aufhören, ihm zu vertrauen."}],"familie":"gemeinsamer-glaube","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Social Ontology (2018, überarbeitet 2024)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/social-ontology/","abruf":"2026-10-12"},{"typ":"url","kurz":"Beran, M. J.; Parrish, A. E. (2021): Non-human primate token use shows possibilities but also limitations for establishing a form of currency. Philosophical Transactions of the Royal Society B 376(1819), 20190675 (PMC-Volltext)","oeffentlich":true,"doi":"10.1098/rstb.2019.0675","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7815425/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Harari, Y. N. (2013): Eine kurze Geschichte der Menschheit (Sapiens). München: DVA","oeffentlich":false}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"80b765d02e216902"}},{"id":"qe-6","status":"entwurf","clusterId":"E","werkstueckRef":"E.4.3","stufe":2,"question":"Was folgt daraus für die Auswahl der Beiträge, die das System bevorzugt ausspielt?","options":["Das System verbreitet bevorzugt, was viele Reaktionen auslöst. Empörendes setzt sich durch, auch ohne dass jemand Wut gezielt fördern will.","Das System erkennt, dass empörende Beiträge häufiger falsch sind, und verbreitet sie deshalb bevorzugt, weil Falsches mehr Aufmerksamkeit bringt.","Das System wird von Mitarbeitern so eingestellt, dass wütende Beiträge von Hand ausgewählt und nach oben gestuft werden.","Das System bevorzugt empörende Beiträge, weil es Meinungsvielfalt abbilden und Konflikte sichtbar machen soll."],"correctIndex":0,"explanation":"Ein System, das nur auf Verweildauer und Reaktionen optimiert ist, kennt weder Wahrheit noch Wut. Es merkt sich lediglich, welche Inhalte Menschen zum Bleiben, Kommentieren und Teilen bringen. Studien zeigen, dass Beiträge über die Gegenseite etwa doppelt so oft geteilt werden – so ergab es die Auswertung von rund 2,7 Millionen Beiträgen von US-Medien und Abgeordneten (Rathje et al. 2021). Ein System, das auf Reaktionen optimiert ist, bevorzugt daher solche Inhalte, ohne böse Absicht und ohne Handauswahl. Das ist eine emergente Eigenschaft: Die Bevorzugung entsteht aus dem Optimierungsziel, nicht aus einem bösartigen Plan der Programmierer. Das heißt noch nicht, dass solche Feeds Menschen messbar radikalisieren: Dazu fanden große Feldexperimente keinen Effekt, ein kleineres nur eine geringe, kurzfristige Verschiebung. Und dass Falschnachrichten sich weiter verbreiten, liegt vor allem daran, dass Menschen sie häufiger teilen, nicht an Algorithmen oder Bots (Vosoughi et al. 2018).","coreRule":"⚡ Frag bei jedem System zuerst, worauf es optimiert ist. Was dieses Ziel belohnt, verbreitet sich, ob es wahr oder wichtig ist oder nicht.","quote":"","quoteLabel":"","scenario":"Eine Plattform will, dass Nutzer möglichst lange bleiben, und lässt ihr Empfehlungssystem selbstständig lernen, welche Beiträge dafür am besten funktionieren. Nach einigen Monaten zeigt sich: Beiträge über die politische Gegenseite, oft empört oder abwertend formuliert, werden etwa doppelt so oft geteilt wie Beiträge über die eigene Seite.","beleg":"Werkstück E.4.3; Fußnote gl-e-empoerung (Rathje et al. 2021, 2,7 Mio. Beiträge, doppelt so oft geteilt), Fußnote gl-e-kaninchenbau (Hinweis zur Beleglage), Fußnote gl-e-vosoughi (Menschen verbreiten Falschnachrichten, Bots beschleunigen beides gleich).","kurz":"Das System kennt nur sein Ziel, Reaktionen und Verweildauer zu steigern, und bevorzugt, was geteilt wird. Das Muster entsteht aus dem Optimierungsziel, ohne Plan und ohne Handauswahl. Daraus folgt nicht, dass es Menschen radikalisiert.","prueffrage":"Welche Beiträge werden häufiger geteilt, und was misst das System, während es lernt?","rueckmeldung":[{"option":1,"text":"Empörende Beiträge können falsch sein, doch das System prüft keine Wahrheit: Es lernt nur, was Reaktionen und Verweildauer bringt. Dass solche Beiträge häufiger falsch wären, steht zudem nirgends."},{"option":2,"text":"Hinter einer Bevorzugung steckt oft Absicht, nahe liegt daher eine Handauswahl. Hier lernt das System aber selbstständig, nur aus Verweildauer und Teilen. Die Bevorzugung folgt aus dem Optimierungsziel, niemand wählt sie aus."},{"option":3,"text":"Vielfalt oder sichtbare Konflikte wären denkbare Ziele, vorgegeben ist dem System aber nur, Nutzer möglichst lange zu halten. Empörende Beiträge setzen sich durch, weil sie Reaktionen auslösen, nicht weil jemand Vielfalt wollte."}],"familie":"anreize-durchschauen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Rathje, S.; Van Bavel, J. J.; van der Linden, S. (2021): Out-group animosity drives engagement on social media. PNAS 118(26)","oeffentlich":true,"doi":"10.1073/pnas.2024292118"},{"typ":"url","kurz":"MIT News (Dizikes, P., 8.3.2018): Study: On Twitter, false news travels faster than true stories","oeffentlich":true,"url":"https://news.mit.edu/2018/study-twitter-false-news-travels-faster-true-stories-0308","abruf":"2026-10-12"},{"typ":"doi","kurz":"Guess, A. M. u. a. (2023): How Do Social Media Feed Algorithms Affect Attitudes and Behavior in an Election Campaign? Science 381(6656)","oeffentlich":false,"doi":"10.1126/science.abp9364"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"cb53142d82051429"}},{"id":"qe-7","status":"entwurf","clusterId":"E","werkstueckRef":"E.2.1","stufe":2,"question":"Welche Schlussfolgerung zieht ein Forscher am sinnvollsten aus dieser Beobachtung?","options":["Sie hielt die Gruppe für besser informiert und hat deshalb ihre eigene Wahrnehmung für falsch gehalten.","Sie fürchtete, die Versuchsleiter zu enttäuschen, und wollte den Ablauf des Experiments nicht stören.","Sie war unsicher, was sie sieht, weil sich die Linien im Versuch tatsächlich kaum unterscheiden ließen.","Sie beugte sich dem sozialen Druck der Gruppe, nicht einem Zweifel an ihrer eigenen Wahrnehmung."],"correctIndex":3,"explanation":"Die Person sagt selbst, dass sie die richtige Linie gesehen hat. Damit scheiden die Erklärungen aus, sie habe an ihrer Wahrnehmung gezweifelt oder die Linien seien schwer zu unterscheiden gewesen: Wer richtig sieht und trotzdem falsch antwortet, gibt dem Druck der Gruppe nach, nicht der Unsicherheit. Dieser soziale Druck, dazuzugehören und nicht negativ aufzufallen, heißt normativer Einfluss. Er wirkt stärker, wenn man unter den Augen der Gruppe antworten muss; die Befundlage dazu ist allerdings uneinheitlich. Die Sorge, die Versuchsleiter zu enttäuschen, taucht in der Schilderung nicht auf und wäre eine bloße Zusatzannahme. Ein Gegenstück ist der informative Einfluss: Hier hält man die Gruppe für besser informiert („Wenn alle das sagen, müssen sie etwas wissen, was ich nicht weiß“). In Aschs Nachbefragungen (1956) kamen beide Motive vor; die meisten Nachgebenden hielten allerdings die Mehrheit für im Recht (Verzerrung des Urteils), und nur ein Teil wusste die richtige Antwort und passte sich an, um nicht unterlegen zu wirken (Verzerrung der Handlung). Die Person im Beispiel gehört zu diesem zweiten Typ. Wer eine Aussage erklären will, sollte die Begründung der Person selbst ernst nehmen und prüfen, welche Erklärung zu den genannten Fakten passt.","coreRule":"⚡ Wer richtig sieht und trotzdem falsch antwortet, gibt oft nicht der Information nach, sondern dem Wunsch, dazuzugehören.","quote":"Wir passen uns an, weil wir von der Gruppe gemocht, akzeptiert und nicht bestraft werden wollen.","quoteLabel":"Merksatz:","scenario":"In einem Wahrnehmungsversuch sitzt eine Versuchsperson mit sieben anderen Personen im Raum. Man zeigt eine Linie und drei Vergleichslinien; eine davon ist eindeutig gleich lang. Die sieben anderen (Eingeweihte) nennen einstimmig und überzeugt die falsche Linie. Als die Versuchsperson an der Reihe ist, schließt sie sich in vielen Fällen der falschen Antwort an. Später sagt sie: „Ich habe die richtige Linie gesehen, wollte aber nicht als Einzige aus der Reihe fallen.“","beleg":"Werkstück E.2.1; Fn. gl-e-asch-gruende (Asch 1956, S. 32 und 70: häufigste Begründung „painfulness of standing alone against the majority“; andere zweifelten an ihren Augen); Fn. gl-e-einfluss. Korrigiert 12.10.2026 nach dem von Sturm zitierten Studientext: „distortion of judgment“ war die häufigste Gruppe der Nachgebenden, „distortion of action“ („wollten nicht unterlegen scheinen“) die seltenere; die frühere Angabe „Druck am häufigsten genannt“ entfällt.","kurz":"Die Person sagt selbst, sie habe die richtige Linie gesehen, und gab trotzdem die falsche Antwort. Wer richtig sieht und falsch antwortet, gibt dem Druck der Gruppe nach, nicht eigener Unsicherheit: Er will dazugehören und nicht als Einziger auffallen.","prueffrage":"Was sagt die Person selbst darüber, was sie gesehen hat, und wie passt das zu ihrer Antwort?","rueckmeldung":[{"option":0,"text":"Dass man der Gruppe mehr Wissen zutraut, kommt vor und wurde in Nachbefragungen auch genannt. Hier passt es aber nicht: Die Person sagt, sie habe die richtige Linie gesehen, also hielt sie ihre Wahrnehmung gar nicht für falsch."},{"option":1,"text":"Von den Versuchsleitern ist nirgends die Rede, und die Person nennt selbst ein anderes Motiv: nicht als Einzige aus der Reihe fallen. Sorge um den Ablauf wäre eine Zusatzannahme, die ihre eigene Begründung übergeht."},{"option":2,"text":"Unsicherheit würde zu schwer unterscheidbaren Linien passen. Eine Vergleichslinie ist aber eindeutig gleich lang, und die Person sagt selbst, sie habe die richtige gesehen; das Problem lag also nicht im Sehen."}],"familie":"schweigen-ist-keine-zustimmung","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Asch, S. E. (1955): Opinions and Social Pressure. Scientific American 193(5) (Sonderdruck auf einer Lehrseite der University of Vermont, inoffizielle Kopie)","oeffentlich":true,"url":"https://pdodds.w3.uvm.edu/teaching/courses/2009-08UVM-300/docs/others/everything/asch1955a.pdf","seite":"PDF-S. 4","abruf":"2026-10-12"},{"typ":"url","kurz":"Open Social Psychology, Kap. 7: Conformity. In: Rahal, R.-M. (Hg.): Open Social Psychology. Open Press Tilburg University (CC BY 4.0)","oeffentlich":true,"url":"https://forrt.org/open-social-psychology/chapter21.html","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Asch, S. E. (1956): Studies of Independence and Conformity: I. A Minority of One Against a Unanimous Majority. Psychological Monographs 70(9), Whole No. 416","oeffentlich":false,"doi":"10.1037/h0093718"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"9d2039aea13dfac9"}},{"id":"qe-8","status":"entwurf","clusterId":"E","werkstueckRef":"E.2.3","stufe":4,"question":"Eine Kollegin sagt: „In Labor-Experimenten meldeten Menschen Rauch viel seltener, wenn andere im Raum waren. Also bleibt jeder Notfall vor Publikum unbeantwortet, und Umstehende greifen im Alltag kaum je ein.“ Was ist an diesem Schluss problematisch?","options":["Er macht aus einer gesunkenen Hilfechance ein „nie“, obwohl in einer Menge schon ein einziger Helfer genügt.","Er geht von einem echten Effekt aus, obwohl Laborergebnisse grundsätzlich nichts über das Alltagsverhalten aussagen.","Er unterstellt weniger Hilfe in Gruppen, obwohl die Anwesenheit anderer die Hilfsbereitschaft jedes Einzelnen erhöht.","Er verwechselt Verantwortungsgefühl mit Hilfsbereitschaft, obwohl Menschen in Gruppen und allein gleich oft helfen."],"correctIndex":0,"explanation":"Im Rauchexperiment meldeten Menschen seltener, wenn andere im Raum waren, etwa weil sich die gefühlte Verantwortung verteilt oder man sich an der Ruhe der anderen orientiert; dieser Befund ist echt. Er zeigt aber eine gesunkene Chance, keine völlige Untätigkeit: Selbst in den Dreiergruppen meldete in 38 % der Fälle jemand den Rauch. Weil schon eine helfende Person genügt, kann eine Menge als Ganzes trotzdem oft helfen. Das zeigten gefilmte Konflikte aus Amsterdam, Lancaster und Kapstadt: Dort griff in gut neun von zehn Fällen mindestens ein Umstehender ein, und die Chance auf Hilfe stieg mit der Zahl der Anwesenden eher. Der Fehler liegt im Sprung von einer gesunkenen Hilfechance auf „jeder Notfall bleibt unbeantwortet“ und „kaum je“.","coreRule":"⚡ Eine Wahrscheinlichkeit für die einzelne Person ist keine Aussage über die Menge: Wenn jeder seltener handelt, kann die Gruppe trotzdem handeln.","quote":"","quoteLabel":"","scenario":"In einem Rauchexperiment meldeten 75 % derer, die allein im Raum waren, den Rauch; in Dreiergruppen meldete nur in 38 % der Gruppen überhaupt jemand den Rauch. Eine Auswertung von 219 gefilmten Konflikten in drei Ländern zeigte dagegen, dass in gut neun von zehn Fällen mindestens ein Umstehender eingriff.","kurz":"Die Laborzahlen zeigen, dass in Gruppen seltener gemeldet wurde, nicht dass niemand hilft: Auch in 38 % der Dreiergruppen meldete jemand. Im Alltag griff in gut neun von zehn Konflikten mindestens einer ein. Der Fehler ist der Sprung von „seltener“ auf „nie“ und „kaum je“.","prueffrage":"Wie oft griff in den 219 gefilmten Konflikten mindestens ein Umstehender ein, und wie passt das zu „kaum je“?","rueckmeldung":[{"option":1,"text":"Den Laborbefund gibt die Kollegin richtig wieder, und aus dem Labor lässt sich durchaus etwas lernen. Nicht tragfähig ist ihr Sprung von „seltener“ auf „nie“; wie es im Alltag aussieht, zeigen die gefilmten Konflikte."},{"option":2,"text":"Dass mit mehr Umstehenden eher geholfen wurde, zeigen die gefilmten Konflikte, und das verführt. Es gilt aber für die Gruppe als Ganzes: Im Rauchexperiment meldete der Einzelne in Gruppen seltener."},{"option":3,"text":"Verantwortung und Hilfsbereitschaft hängen zusammen, eine Verwechslung steckt im Schluss aber nicht. Dass allein und in Gruppen gleich oft geholfen wird, zeigen die Laborzahlen nicht: Allein meldeten 75 %, in Dreiergruppen nur 38 % der Gruppen."}],"familie":"verantwortung-benennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Philpot, R.; Liebst, L. S.; Levine, M.; Bernasco, W.; Lindegaard, M. R. (2020): Would I Be Helped? Cross-National CCTV Footage Shows That Intervention Is the Norm in Public Conflicts. American Psychologist 75(1), S. 66–75 (Manuskriptfassung, Lancaster University)","oeffentlich":true,"doi":"10.1037/amp0000469","url":"https://eprints.lancs.ac.uk/id/eprint/134891/1/Would_I_be_Helped_Cross_National_CCTV_Footage_Shows_That_Intervention_Is_the_Norm_in_Public_Conflicts_Postprint.pdf","seite":"PDF-S. 2, 11","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Latané, B.; Darley, J. M. (1968): Group Inhibition of Bystander Intervention in Emergencies. Journal of Personality and Social Psychology 10(3), S. 215–221","oeffentlich":false,"doi":"10.1037/h0026570"},{"typ":"literatur","kurz":"Fischer, P.; Krueger, J. I.; Greitemeyer, T. u. a. (2011): The bystander-effect: A meta-analytic review on bystander intervention in dangerous and non-dangerous emergencies. Psychological Bulletin 137(4), S. 517–537","oeffentlich":false,"doi":"10.1037/a0023304"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"fe00d5571929949f"}},{"id":"qe-9","status":"entwurf","clusterId":"E","werkstueckRef":"E.2.5","stufe":2,"question":"Ein Team beschließt in einer Sitzung eine Regel, die offensichtlich unsinnig ist. Niemand widerspricht. Später erfährst du: Fast alle hielten die Regel insgeheim für Unsinn und hielten sich für den Einzigen mit diesem Zweifel. Was erklärt das Schweigen am besten?","options":["Eine kleine Minderheit hat sich einer tatsächlich vorhandenen Mehrheitsmeinung angepasst, weil sie Ausgrenzung fürchtete.","Das Team hat die Regel gründlich geprüft und ihr nach Abwägung zugestimmt, weil kein Einwand überzeugte.","Die Verantwortung für einen Einspruch hat sich auf alle verteilt, sodass sich am Ende niemand zuständig fühlte.","Fast alle deuteten das Schweigen der anderen als Zustimmung und beugten sich so einer Mehrheitsmeinung, die es gar nicht gab."],"correctIndex":3,"explanation":"Entscheidend ist die Lücke zwischen privater Überzeugung und öffentlichem Verhalten. Wer sich unsicher ist, orientiert sich an den anderen und liest deren Schweigen als Zustimmung. Da alle dasselbe tun, wirkt jedes Schweigen wie ein weiterer Beleg dafür, dass alle einverstanden sind. So entsteht eine Mehrheit, die es privat nie gab. Das ist etwas anderes als gewöhnliche Anpassung an eine echte Mehrheit: Dort stimmt das Bild der Gruppe, hier ist es eine kollektive Täuschung. Es ist auch keine sorgfältige Prüfung, denn die Zweifel wurden nie ausgesprochen, und keine bloße Verantwortungsdiffusion, denn hier schweigen die Leute, weil sie die Meinung der anderen falsch einschätzen, nicht weil sie sich nicht zuständig fühlen. Ein bekanntes Beispiel ist der Hörsaal: Nach „Gibt es Fragen?“ meldet sich niemand, obwohl vielen etwas unklar ist, und jeder deutet das Schweigen der anderen als Verständnis. Das Märchen von des Kaisers neuen Kleidern zeigt denselben Kreislauf des Schweigens.","coreRule":"⚡ Das Schweigen der anderen ist kein Beleg für ihre Zustimmung. Prüfe, ob du nur ihr Verhalten siehst, nicht ihre Überzeugung.","quote":"Ich sehe nichts … aber alle anderen scheinen die prächtigen Stoffe zu sehen. Ich muss wohl der einzige Dumme hier sein.","quoteLabel":"Gedanke der Bürger im Märchen:","scenario":"Du bist neu im Team und wunderst dich über eine Regel, die laut Protokoll „einstimmig“ beschlossen wurde. Auf Nachfrage räumen mehrere Kolleginnen und Kollegen einzeln ein, sie hätten die Regel von Anfang an für sinnlos gehalten.","kurz":"Alle lasen das Schweigen der anderen als Zustimmung und schwiegen selbst, obwohl fast alle privat zweifelten. So entstand der Anschein einer Mehrheit, die es gar nicht gab. Der Fehler liegt darin, Schweigen für Einverständnis zu halten.","prueffrage":"Woran könntest du erkennen, was die Einzelnen wirklich dachten, als niemand etwas sagte?","rueckmeldung":[{"option":0,"text":"Anpassung an eine Mehrheit kommt tatsächlich vor. Hier gab es aber keine: Fast alle zweifelten privat. Die Gruppe passte sich also einem Bild an, das nicht stimmte, nicht einer vorhandenen Mehrheitsmeinung."},{"option":1,"text":"Eine einstimmige Zustimmung im Protokoll sieht nach gründlicher Prüfung aus. Dafür hätten Zweifel aber geäußert und abgewogen werden müssen. Sie blieben ungesagt, also wurde nichts geprüft."},{"option":2,"text":"Verantwortung kann sich in Gruppen tatsächlich verteilen, bis sich niemand zuständig fühlt. Hier schwiegen die Leute jedoch, weil sie die Meinung der anderen falsch einschätzten, nicht weil sie sich nicht zuständig fühlten."}],"familie":"schweigen-ist-keine-zustimmung","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Schroeder, C. M.; Prentice, D. A. (1998): Exposing Pluralistic Ignorance to Reduce Alcohol Use Among College Students. Journal of Applied Social Psychology 28(23), S. 2150–2180 (Kopie Stanford SPARQ)","oeffentlich":true,"url":"https://sparq.stanford.edu/sites/g/files/sbiybj19021/files/media/file/schroeder_prentice_1998_-_exposing_pluralistic_ignorance.pdf","seite":"S. 2151–2153","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Prentice, D. A.; Miller, D. T. (1993): Pluralistic ignorance and alcohol use on campus. Journal of Personality and Social Psychology 64(2), S. 243–256","oeffentlich":false,"doi":"10.1037/0022-3514.64.2.243"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"cf356d484a27f0bd"}},{"id":"qe-10","status":"entwurf","clusterId":"E","werkstueckRef":"E.2.7","stufe":4,"question":"Welche Reaktion prüft diese Behauptung am besten?","options":["Ich frage, ob die Forschenden das Verhalten der Wärter beeinflusst haben und ob andere Studien mit weniger Eingriff dasselbe Ergebnis zeigen.","Ich frage, wie viele Menschen das Experiment schon kennen, denn ein so bekannter Befund wird kaum falsch sein.","Ich frage, ob die Teilnehmenden freiwillig mitgemacht haben, denn wer mitmacht, ist ohnehin anfälliger für Brutalität.","Ich frage, ob der Leiter ein angesehener Professor war, denn dann dürfte man seiner Deutung weitgehend vertrauen."],"correctIndex":0,"explanation":"Ein berühmter Befund ist noch kein belastbarer Befund; entscheidend ist, wie das Ergebnis zustande kam. Eine Archivrecherche zeigt, dass die Studienleitung einen zögerlichen Wärter ausdrücklich zu mehr Härte aufforderte, und ein früherer „Gefangener“ sagte später, er habe sich in seinen Nervenzusammenbruch bewusst hineingesteigert, um entlassen zu werden (der Leiter bestritt das). Weil die Studienleitung ins Geschehen eingriff, sagt das Ergebnis wenig darüber, was Menschen von selbst tun. In der BBC Prison Study, in der die Forscher keine Führungsrolle übernahmen, fügte sich niemand automatisch in seine Rolle; Tyrannei entstand erst durch die Identifikation mit einer Gruppe und ihrer Führung. Bekanntheit und Ansehen des Leiters prüfen weder die Entstehung des Ergebnisses noch seine Wiederholbarkeit, und die bloße Frage nach der Freiwilligkeit greift zu kurz: Wer sich für eine Gefängnisstudie meldet, kann sich zwar von anderen unterscheiden, doch das wäre erst zu prüfen und erklärt die Eingriffe der Studienleitung nicht.","coreRule":"⚡ Prüfe bei einem berühmten Beleg, wie das Ergebnis zustande kam und ob es sich unter anderen Bedingungen wiederholt.","quote":"","quoteLabel":"","scenario":"In der Mittagspause diskutiert ihr über Macht und Führung. Eine Kollegin sagt: „Das Stanford-Gefängnis-Experiment von 1971 beweist, dass ganz normale Menschen unter Macht automatisch zu Tyrannen werden.“","kurz":"Berühmt ist nicht belastbar: Die Studienleitung forderte einen Wärter zu mehr Härte auf, und eine spätere Studie ohne solche Eingriffe zeigte kein „automatisches“ Tyrannisieren. Wer Zustandekommen und Wiederholbarkeit prüft, durchschaut den Fehlschluss.","prueffrage":"Was genau behauptet die Kollegin über normale Menschen, und was müsste ein Versuch zeigen, damit „automatisch“ stimmt?","rueckmeldung":[{"option":1,"text":"Was viele kennen, wirkt schnell gesichert. Bekanntheit sagt aber nichts darüber, wie ein Ergebnis zustande kam oder ob es sich wiederholen lässt, und genau das entscheidet über seine Belastbarkeit."},{"option":2,"text":"Die Auswahl der Teilnehmenden zu hinterfragen, ist an sich sinnvoll. Ob jemand freiwillig mitmacht, klärt aber weder, wie die Studienleitung das Ergebnis beeinflusst hat, noch ob es sich ohne solche Eingriffe wiederholen lässt."},{"option":3,"text":"Das Ansehen eines Professors macht seine Deutung bekannter, aber nicht richtiger. Geprüft wird die Behauptung erst, wenn man fragt, wie das Ergebnis zustande kam und ob andere Studien es bestätigen."}],"familie":"wiederholung-abwarten","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Haslam, S. A.; Reicher, S. D. (2012): Contesting the „Nature“ of Conformity: What Milgram and Zimbardo's Studies Really Show. PLOS Biology 10(11), e1001426","oeffentlich":true,"doi":"10.1371/journal.pbio.1001426","abruf":"2026-10-12"},{"typ":"doi","kurz":"Le Texier, T. (2019): Debunking the Stanford Prison Experiment. American Psychologist 74(7), 823–839","oeffentlich":false,"doi":"10.1037/amp0000401"},{"typ":"literatur","kurz":"Reicher, S. D.; Haslam, S. A. (2006): Rethinking the Psychology of Tyranny: The BBC Prison Study. British Journal of Social Psychology 45(1), 1–40","oeffentlich":false}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"7f53a02b71972a37"}},{"id":"qe-11","status":"entwurf","clusterId":"E","werkstueckRef":"E.3.4","stufe":1,"question":"Welche dieser Schlussfolgerungen aus dem Fall ist am besten begründet?","options":["Das schlechte Ergebnis beweist, dass die Einschätzung der Lehrerin von Anfang an richtig war, denn ihre Vorhersage ist eingetroffen.","Das Ergebnis kann zum Teil durch das Verhalten der Lehrerin mitverursacht sein, sodass es ihre Erwartung nicht unabhängig bestätigt.","Das Verhalten der Lehrerin kann das Ergebnis nicht beeinflusst haben, weil der Schüler ihre Erwartung gar nicht bewusst wahrgenommen hat.","Das Ergebnis zeigt nur, dass der Schüler zu wenig Trotz entwickelt hat, denn wer es wirklich will, widerlegt jede Erwartung."],"correctIndex":1,"explanation":"Wenn eine Erwartung das eigene Handeln lenkt, kann sie mitverursachen, was sie vorhersagt: Wer weniger gefordert, beachtet und ermutigt wird, hat schlechtere Chancen, gut abzuschneiden. Das Eintreffen der Vorhersage ist dann kein unabhängiger Beleg dafür, dass sie von Anfang an stimmte. Diesen Mechanismus nennt man Golem-Effekt, die negative Seite des Pygmalion-Effekts. Solche Effekte sind nach der Forschungslage meist nur klein und wenig dauerhaft; hier lässt sich nur sagen, dass das Eintreffen die Erwartung nicht unabhängig bestätigt. Dass Erwartungen oft auch deshalb zutreffen, weil sie schlicht richtig waren, bleibt möglich. Um das zu klären, bräuchte man Leistungsdaten, die vom Verhalten der Lehrerin unabhängig sind. Dass die Erwartung unbemerkt wirkt, schließt Folgen nicht aus: Sie kann über das Handeln der Lehrerin und die Gelegenheiten, die der Schüler bekommt, wirken. Auch die Erklärung allein durch den Schüler blendet den Beitrag der Lehrerin aus, den der Mechanismus des Golem-Effekts gerade nahelegt.","coreRule":"⚡ Wenn eine Erwartung das Handeln lenkt, kann ihr Eintreffen nicht als unabhängiger Beweis für ihre Richtigkeit gelten.","quote":"","quoteLabel":"","scenario":"Eine Lehrerin ist überzeugt, dass ein Schüler „nicht viel auf dem Kasten hat“. Sie ruft ihn selten auf, gibt ihm nur einfache Aufgaben und lobt ihn kaum. Am Schuljahresende schneidet er schlecht ab. Die Lehrerin sagt: „Ich hab's ja gleich gewusst.“","beleg":"Werkstück E.3.4, Abschnitt „Kontext & Tiefe“ (Golem-Effekt), Hinweis zur Beleglage; Fußnote gl-e-rosenthal (Jussim/Harber 2005: Lehrererwartungen sagen Leistungen oft deshalb voraus, weil sie zutreffen).","kurz":"Wer weniger gefordert, beachtet und gelobt wird, hat schlechtere Chancen, gut abzuschneiden. Das Eintreffen der Vorhersage bestätigt die Erwartung daher nicht unabhängig, denn sie kann das Ergebnis mitverursacht haben.","prueffrage":"Welche Gelegenheiten hatte der Schüler im Lauf des Jahres, zu zeigen, was er kann?","rueckmeldung":[{"option":0,"text":"Die Vorhersage ist eingetroffen, und die Einschätzung kann tatsächlich richtig gewesen sein. Als Beweis taugt das aber nicht: Die Lehrerin hat den Schüler selten aufgerufen und kaum gefördert, was das Ergebnis mitverursacht haben kann."},{"option":2,"text":"Dass der Schüler die Erwartung nicht bewusst bemerkt hat, ist gut möglich. Die Wirkung läuft aber über das Handeln der Lehrerin und die Gelegenheiten, die er bekommt, und die wirken auch ohne sein Wissen."},{"option":3,"text":"Eigener Einsatz spielt sicher eine Rolle. Alles in den Schüler zu verlegen, blendet aber aus, dass er kaum aufgerufen, nur mit einfachen Aufgaben bedacht und selten gelobt wurde; „wer es wirklich will, widerlegt jede Erwartung“ ist viel zu absolut."}],"familie":"erwartung-erfuellt-sich","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Jussim, L.; Harber, K. D. (2005): Teacher Expectations and Self-Fulfilling Prophecies: Knowns and Unknowns, Resolved and Unresolved Controversies. Personality and Social Psychology Review 9(2), 131–155 (Abstract, PubMed)","oeffentlich":true,"doi":"10.1207/s15327957pspr0902_3","url":"https://pubmed.ncbi.nlm.nih.gov/15869379/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"c613cae397991bb2"}},{"id":"qe-12","status":"entwurf","clusterId":"E","werkstueckRef":"E.3.5","stufe":2,"question":"Welche Erklärung für das Vorgehen der Gruppe folgt der verbreiteten Deutung des Overton-Fensters?","options":["Die Gruppe will durch sachliche Aufklärung jeden Wähler einzeln vom konkreten Vorhaben überzeugen, bevor sich das Fenster der Akzeptanz überhaupt bewegt und es zur Abstimmung kommt.","Die Gruppe prüft, welche Ideen schon im Fenster der Akzeptanz liegen und mehrheitsfähig sind, damit Parteien künftig nur noch Populäres vertreten.","Die Gruppe will das Fenster der Akzeptanz verschieben, damit ihre Position später akzeptabel wirkt und Politiker sie ohne Risiko aufgreifen können.","Die Gruppe will die Idee lächerlich machen, damit sie aus dem Fenster der Akzeptanz fällt und die politische Mitte gestärkt wird."],"correctIndex":2,"explanation":"Politiker, die wiedergewählt werden wollen, bewegen sich meist nur innerhalb dessen, was als akzeptabel gilt. Eine Position, die als undenkbar gilt, können sie nicht vertreten, ohne ihre Karriere zu riskieren. Nach der verbreiteten Deutung des Overton-Fensters zielt die Arbeit an den Rändern deshalb darauf, die Grenze des Diskutablen selbst zu verschieben. Overtons Kollegen beschreiben das nüchterner: als langsamen Wandel von Werten und Normen, zu dem unter anderem Thinktank-Forschung und Debatte beitragen. Das Beispiel des Rauchverbots zeigt das Muster: Zuerst galt es als Spinnerei, dann als radikal, dann kam der „Kompromiss“ für Krankenhäuser, später wurde es selbstverständlich. Niemand wurde über Nacht überzeugt, sondern der Rahmen des Akzeptablen hat sich verschoben. Die anderen Erklärungen passen nicht zum Beobachteten: Wer Wähler einzeln überzeugen wollte, würde nicht auf Jahre der Randdebatte setzen. Wer nur Populäres abbilden wollte, würde keine Außenseiterposition vertreten. Wer die Idee lächerlich machen wollte, würde sie nicht mit Studien und Weiterreden voranbringen.","coreRule":"⚡ Wer verschiebt, was als diskutabel gilt, verändert, was später als vernünftig durchgeht.","quote":"","quoteLabel":"","scenario":"Eine Gruppe vertritt öffentlich eine Position, die in der Gesellschaft bisher als so extrem gilt, dass kaum jemand sie ernsthaft diskutiert; eine Mehrheit bei der nächsten Wahl strebt sie nicht an. Sie veröffentlicht Studien zu ihrer Idee. Politiker, die wiedergewählt werden wollen, halten Abstand. Medien berichten darüber, meist spöttisch, aber sie berichten. Nach einigen Jahren schlagen gemäßigte Gruppen eine abgeschwächte Version „als Kompromiss“ vor.","beleg":"Werkstück E.3.5, Fußnote gl-e-overton: Lehman, J. G.: „The legacy of the Overton Window“, Mackinac Center, 30.06.2023","kurz":"Politiker, die wiedergewählt werden wollen, meiden als undenkbar geltende Positionen. Nach der verbreiteten Deutung des Overton-Fensters arbeitet eine Gruppe, die eine solche Position trotzdem vertritt, daran, die Grenze des Diskutablen zu verschieben.","prueffrage":"Was geschieht nach einigen Jahren mit der Idee, und wer greift sie dann auf?","rueckmeldung":[{"option":0,"text":"Aufklärung kann zum Meinungswandel beitragen. Die Gruppe setzt aber auf Jahre der Randdebatte statt auf eine baldige Abstimmung; wer Wähler einzeln gewinnen wollte, ginge anders vor. Nach dieser Deutung will sie verschieben, was diskutierbar ist."},{"option":1,"text":"Zu wissen, was mehrheitsfähig ist, hilft Parteien bei ihrer Planung. Eine Gruppe, die eine Außenseiterposition vertritt, bildet das Populäre aber gerade nicht ab, sondern will es verändern."},{"option":3,"text":"Spott kommt vor, geht aber von den Medien aus. Die Gruppe selbst bringt die Idee mit Studien ins Gespräch, und am Ende steht eine abgeschwächte Version als Kompromiss: Die Idee rückt näher ans Akzeptable heran, statt weiter davon abzurücken."}],"familie":"sagbarkeit-verschiebt-sich","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Mackinac Center for Public Policy: The Overton Window","oeffentlich":true,"url":"https://www.mackinac.org/OvertonWindow","abruf":"2026-10-12"},{"typ":"url","kurz":"Lehman, J. G. (2023): The legacy of the Overton Window. Mackinac Center for Public Policy, Blog, 30.06.2023","oeffentlich":true,"url":"https://www.mackinac.org/blog/2023/the-legacy-of-the-overton-window","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"0e38637ce91d2f77"}},{"id":"qe-13","status":"entwurf","clusterId":"E","werkstueckRef":"E.3.6","stufe":2,"question":"Eine Schwester und ein Bruder erinnern sich beide „ganz genau“ an einen Familienausflug, bei dem die Schwester als Kind im Einkaufszentrum verloren ging. Die Eltern sagen, so etwas sei nie passiert. Der Bruder hat die Geschichte aber über Jahre immer wieder erzählt bekommen, und die Schwester wurde vor Kurzem suggestiv danach gefragt. Welche Schlussfolgerung ist am vernünftigsten?","options":["Zwei unabhängige Erinnerungen, die übereinstimmen, belegen das Ereignis, auch wenn die Eltern es nicht bestätigen.","Wer sich lebhaft und mit starken Gefühlen erinnert, irrt sich selten, daher ist die Erinnerung der Geschwister am glaubwürdigsten.","Die Eltern müssen sich irren, denn ein Ereignis, an das sich beide Kinder erinnern, kann man nicht erfunden haben.","Lebhaftigkeit und Übereinstimmung beweisen wenig, denn Erinnerungen lassen sich durch Erzählungen und Nachfragen formen."],"correctIndex":3,"explanation":"Das Gedächtnis ist kein Archiv, sondern wird bei jedem Abruf neu zusammengesetzt, und dabei können Erwartungen, wiederholte Erzählungen und suggestive Fragen die Erinnerung verändern. Die Forschung von Elizabeth Loftus zeigt: Manchen Menschen lassen sich falsche Erinnerungen an ganze Ereignisse einpflanzen, etwa ein Verlorengehen im Einkaufszentrum; wie vielen und wie vollständig, ist umstritten. Lebhaftigkeit, Sicherheit und Gefühl sagen daher wenig darüber, ob etwas geschah. Beim Bruder kann die oft gehörte Erzählung, bei der Schwester die suggestive Nachfrage die Erinnerung geformt haben; die Übereinstimmung beweist daher wenig. Entscheidend ist, eine Erinnerung nicht schon deshalb für wahr zu halten, weil sie sich lebhaft anfühlt.","coreRule":"⚡ Lebhaftigkeit und Sicherheit sind kein Beweis: Erinnerung ist Rekonstruktion, kein Archiv.","quote":"Das Gedächtnis ist kein Archiv, sondern ein Wikipedia-Eintrag -- es kann bei jedem Abruf neu geschrieben und bearbeitet werden.","quoteLabel":"Zum Weiterdenken:","scenario":"Ein Familienstreit um eine gemeinsame Kindheitserinnerung: Zwei Geschwister berichten übereinstimmend und lebhaft von einem Ereignis, das die Eltern nicht bestätigen.","kurz":"Eine Erinnerung kann sich echt anfühlen und trotzdem durch oft gehörte Erzählungen oder suggestive Fragen entstanden sein. Lebhaftigkeit und Übereinstimmung beweisen darum wenig, wenn beide Erinnerungen auf solchen Wegen geformt sein können.","prueffrage":"Wer außer den Geschwistern hätte das Verlorengehen miterlebt, und was sagen diese Personen dazu?","rueckmeldung":[{"option":0,"text":"Zwei übereinstimmende Erinnerungen würden mehr beweisen, wenn sie unabhängig entstanden wären. Hier hat der Bruder die Geschichte oft erzählt bekommen und die Schwester wurde suggestiv gefragt, sodass die Übereinstimmung wenig besagt."},{"option":1,"text":"Dass sich lebhafte, gefühlsstarke Erinnerungen verlässlich anfühlen, ist verständlich. Wie genau und wie sicher eine Erinnerung wirkt, sagt aber wenig darüber, ob das Ereignis stattfand; auch falsche Erinnerungen können sehr lebhaft sein."},{"option":2,"text":"Gemeinsam etwas zu erfinden, wirkt unwahrscheinlich. Erinnerungen können aber durch Erzählungen und Nachfragen entstehen, ohne dass jemand bewusst etwas erfindet; dass die Eltern sich irren müssen, folgt daraus nicht."}],"familie":"erinnerung-ist-rekonstruktion","fertigkeit":"F5","quellen":[{"typ":"doi","kurz":"Murphy, G. u. a. (2023): Lost in the mall again: a preregistered replication and extension of Loftus & Pickrell (1995). Memory 31(6)","oeffentlich":true,"doi":"10.1080/09658211.2023.2198327"},{"typ":"doi","kurz":"Wade, K. A.; Riesthuis, P.; Bücken, C.; Otgaar, H.; Loftus, E. F. (2025): Still Lost in the Mall – False Memories Happen and That's What Matters. Applied Cognitive Psychology 39(1)","oeffentlich":true,"doi":"10.1002/acp.70028"},{"typ":"literatur","kurz":"Loftus, E. F.; Pickrell, J. E. (1995): The Formation of False Memories. Psychiatric Annals 25(12), 720–725","oeffentlich":false}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"30461ba2af4da677"}},{"id":"qe-14","status":"entwurf","clusterId":"E","werkstueckRef":"E.4.4","stufe":4,"question":"Welche Frage prüft seine Behauptung am besten?","options":["Wer behauptet die Fälschung, und welche Belege legt er dafür vor, während die Herkunft des Videos unabhängig bestätigt ist?","Wirkt das Video technisch so perfekt, dass sich ein Deepfake nicht ausschließen lässt?","Ist die Möglichkeit von Deepfakes so bekannt, dass jede Aufnahme grundsätzlich unter Fälschungsverdacht steht?","Passt die Äußerung so wenig zum bisherigen Auftreten des Politikers, dass sie unglaubwürdig erscheint?"],"correctIndex":0,"explanation":"Wer ein Video als Fälschung bezeichnet, behauptet etwas und muss das belegen. Die bloße Möglichkeit von Deepfakes ist kein Beleg, sonst ließe sich jede unbequeme Aufnahme abtun („Lügner-Dividende“). Hier ist die Herkunft durch Augenzeugen und zwei unabhängige Agenturen bestätigt, während für die Fälschung nichts vorgelegt wird. Die anderen Fragen führen in die Irre: Technische Perfektion oder die allgemeine Existenz von Fälschungen machen eine Aufnahme nicht unecht, und dass eine Äußerung überrascht, ist kein Beweis, dass sie gefälscht ist. Entscheidend sind Quelle, Bestätigung und Belege.","coreRule":"⚡ Die Möglichkeit einer Fälschung ist kein Beleg für eine Fälschung: Die Beweislast liegt bei dem, der sie behauptet.","quote":"Wenn ein Politiker behauptet, ein echtes Video sei ein Fake -- wo sind seine Beweise für die Fälschung?","quoteLabel":"Prüffrage:","scenario":"Ein Politiker wird bei einer skandalösen Äußerung gefilmt, in einem Saal mit etwa hundert Anwesenden. Das Video stammt von mehreren Augenzeugen und wurde von zwei voneinander unabhängigen Nachrichtenagenturen aus verschiedenen Quellen bestätigt. Als es viral geht, sagt der Politiker: „Das ist bestimmt ein Deepfake.“ Belege dafür legt er nicht vor.","kurz":"Wer ein Video für gefälscht erklärt, muss das belegen; die bloße Möglichkeit von Deepfakes genügt nicht. Hier ist die Herkunft unabhängig bestätigt, für die Fälschung wird nichts vorgelegt. Auf Quelle, Bestätigung und Belege kommt es an.","prueffrage":"Wie viele Menschen waren im Saal, und wie viele von ihnen bestreiten, was das Video zeigt?","rueckmeldung":[{"option":1,"text":"Dass Deepfakes sehr überzeugend sein können, stimmt. Doch aus „lässt sich nicht ausschließen“ folgt keine Fälschung, sonst wäre jede Aufnahme verdächtig. Die unabhängige Bestätigung durch Augenzeugen und zwei Agenturen bleibt dabei außen vor."},{"option":2,"text":"Deepfakes sind tatsächlich real und bekannt, deshalb ist Vorsicht sinnvoll. Ein Generalverdacht prüft aber nicht den konkreten Fall und ließe jede unbequeme Aufnahme abtun. Die bloße Möglichkeit einer Fälschung ist kein Beleg dafür."},{"option":3,"text":"Eine untypische Äußerung kann Anlass zu genauerem Hinsehen sein. Überraschung ist aber kein Beweis für eine Fälschung, und hier sprechen Augenzeugen sowie zwei unabhängige Agenturen für Echtheit, während für die Fälschung nichts vorliegt."}],"familie":"beweislast-klaeren","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Chesney, B.; Citron, D. (2019): Deep Fakes: A Looming Challenge for Privacy, Democracy, and National Security. California Law Review 107","oeffentlich":true,"doi":"10.15779/Z38RV0D15J"},{"typ":"doi","kurz":"Barari, S.; Lucas, C.; Munger, K. (2025): Political Deepfakes Are as Credible as Other Fake Media and (Sometimes) Real Media. The Journal of Politics 87(2)","oeffentlich":false,"doi":"10.1086/732990"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"b7b8296575c741da"}},{"id":"qe-15","status":"entwurf","clusterId":"E","werkstueckRef":"E.4.4 / Anhang VII.2","stufe":4,"question":"Was ist von dieser Begründung zu halten?","options":["Sie taugt nicht als Beleg: Das Modell kann kaum wissen, wo ein Bild erschienen ist, und fehlende Veröffentlichung macht ein Foto nicht unecht.","Sie ist schlüssig: Echte Pressefotos erscheinen in Nachrichtenmedien, also spricht eine fehlende Veröffentlichung deutlich für ein erzeugtes Bild.","Sie ist verlässlich, denn Sprachmodelle kennen alle veröffentlichten Bilder und würden ein echtes Pressefoto sofort wiedererkennen.","Sie ist unerheblich: Ob ein Bild echt ist, zeigt allein die Untersuchung der Pixel, die Herkunft eines Fotos sagt dazu nichts."],"correctIndex":0,"explanation":"Ein Sprachmodell schlägt die Herkunft eines Bildes nicht nach, es formuliert eine plausibel klingende Antwort. Wo ein Foto erschienen ist, kann es deshalb oft gar nicht wissen, und selbst wenn: Fehlende Veröffentlichung macht ein Foto nicht unecht, denn Fotos können neu, unveröffentlicht oder nur in Archiven zu finden sein. Wie unzuverlässig solche Urteile sind, zeigte ein kleiner Test des Tow Center for Digital Journalism (Columbia Journalism Review, 2025): Alle getesteten Bilder waren echte, vielfach veröffentlichte Fotos professioneller Fotojournalisten, und trotzdem hielt jedes der sieben Modelle mindestens eines davon für KI-erzeugt. Vorbehalt: Es war ein kleiner Test mit Modellversionen vom Sommer 2025. Wer ein Foto prüft, klärt die Herkunft selbst: Urheber, Erstveröffentlichung, Bestätigung durch Dritte.","coreRule":"⚡ Auch ein „Das ist KI“ vom Sprachmodell ist kein Beleg: Prüfe die Herkunft des Bildes selbst.","quote":"Das Modell erklärt Echtes für erfunden.","quoteLabel":"Merksatz:","kurz":"Ein Sprachmodell kann die Herkunft eines Bildes nicht nachschlagen, und fehlende Veröffentlichung macht ein Foto nicht unecht. Im Tow-Test hielt jedes der sieben Modelle mindestens ein echtes Pressefoto für KI-erzeugt. Die Herkunft prüft man selbst.","prueffrage":"Worauf stützt das Modell seine Aussage, und wie könntest du selbst nachprüfen, ob und wo das Foto erschienen ist?","rueckmeldung":[{"option":1,"text":"Dass echte Pressefotos meist veröffentlicht werden, stimmt. Umgekehrt folgt daraus nichts: Auch echte Fotos sind oft neu, unveröffentlicht oder nur in Archiven zu finden, und das Modell kann gar nicht sicher wissen, wo ein Bild erschienen ist."},{"option":2,"text":"Sprachmodelle geben Wahrscheinliches wieder, sie schlagen keine Bildherkunft nach und kennen nicht jedes veröffentlichte Foto. Dass eine Antwort selbstsicher klingt, belegt nichts: Im Tow-Test hielt jedes der sieben Modelle mindestens ein echtes Foto für KI-erzeugt."},{"option":3,"text":"Die Herkunft ist gerade ein wichtiger Anhaltspunkt: Urheber, Erstveröffentlichung und Bestätigung durch Dritte lassen sich nachprüfen. Falsch ist die Begründung des Modells, nicht die Frage nach der Herkunft."}],"familie":"ki-ausgabe-pruefen","fertigkeit":"F1","scenario":"Du zeigst einem Sprachmodell ein Pressefoto und fragst, ob es KI-erzeugt ist. Es antwortet selbstsicher: „Ja, das Bild ist KI-erzeugt, denn es ist in keinem Nachrichtenmedium erschienen.“","beleg":"Chandrasekar, A.; Jaźwińska, K. (2025): Tow Center for Digital Journalism, Columbia Journalism Review, Test von sieben Sprachmodellen mit echten Pressefotos. Wortlaut (von Sturm am 12.10.2026 im Bericht geprüft): „Although all the pictures we tested were authentic, widely published photos taken by professional photojournalists and published by reputable publications, each model we tested misidentified at least one real photo as AI-generated when we asked.“ Die Begründung „in keinem Nachrichtenmedium erschienen“ ist eine Erfindung für das Beispiel.","quellen":[{"typ":"url","kurz":"Chandrasekar, A.; Jaźwińska, K. (2025): Why AI Models Are Bad at Verifying Photos. Columbia Journalism Review, 26.08.2025","oeffentlich":true,"url":"https://www.cjr.org/tow_center/why-ai-models-are-bad-at-verifying-photos.php","abruf":"2026-10-08"}],"thema":"Technik und KI"},{"id":"qf-1","status":"entwurf","clusterId":"F","werkstueckRef":"F.1.1","stufe":2,"question":"Eine Forscherin erklärt: „Meine Idee klingt seltsam, aber seltsam heißt nicht falsch.“ Woran erkennst du, ob ihre Idee eher spekulative Forschung am Rand der Wissenschaft oder Pseudowissenschaft ist?","options":["Entscheidend ist, wie neuartig und ungewöhnlich die Hypothese im Vergleich zu etablierten Theorien ist.","Entscheidend ist, ob die Idee testbar bleibt und die Gruppe bereit ist, sie bei Gegenbeweisen aufzugeben.","Entscheidend ist, ob die Gruppe an einer Universität oder einem anerkannten Institut arbeitet.","Entscheidend ist, ob sich die Idee am Ende bestätigt, denn erst dann lässt sich ihr Status beurteilen."],"correctIndex":1,"explanation":"Seltsamkeit allein sagt nichts: Auch Grenzwissenschaft kann spekulativ und seltsam aussehen, bleibt aber eine testbare Hypothese. Pseudowissenschaft erkennst du am Verhalten gegenüber Gegenbeweisen: Sie ahmt die äußere Form der Wissenschaft nach (Jargon, Rituale, angebliche „Beweise“), macht ihre Behauptungen aber durch Ad-hoc-Ausreden unwiderlegbar und erklärt Misserfolge weg. Neuartigkeit taugt als Kriterium nicht, denn auch gute neue Ideen sind neuartig. Der Ort ist nicht entscheidend, denn Pseudowissenschaft gründet eigene „Institute“ und „Fachzeitschriften“. Und dass sich eine Idee später bestätigt, kannst du erst hinterher wissen; du brauchst ein Kriterium, das schon vorher greift.","coreRule":"⚡ Die Methode entscheidet, nicht die Seltsamkeit der Idee.","quote":"Eine Idee kippt in Pseudowissenschaft, wenn sie aufhört, eine testbare Hypothese zu sein, und zu einem dogmatischen, unfehlbaren Glaubenssystem wird.","quoteLabel":"Merksatz:","scenario":"Zwei Gruppen vertreten jeweils eine ungewöhnliche Idee. Gruppe X plant Experimente, die ihre Hypothese klar widerlegen könnten, und hat vorab festgelegt, welche Ergebnisse sie als Scheitern werten würde. Gruppe Y bleibt bei einer Erklärung, die seit Jahrhunderten unverändert ist; bleibt ein Effekt aus, heißt es, die Skepsis der Testpersonen habe ihn blockiert.","beleg":"Werkstück F.1.1 (Kernidee, Checkliste Punkt 2, 4 und 6, Kipppunkt); Fußnote gl-f-cargo nicht einschlägig","kurz":"Wissenschaftlich ist eine Idee, solange sie sich widerlegen lässt und man bereit ist, sie bei Gegenbefunden aufzugeben. Seltsamkeit allein sagt nichts. Wer Misserfolge mit Ausreden wegerklärt, macht die Idee unwiderlegbar und damit pseudowissenschaftlich.","prueffrage":"Beide Gruppen vertreten eine ungewöhnliche Idee: Worin unterscheiden sie sich dann überhaupt?","rueckmeldung":[{"option":0,"text":"Dass eine Idee ungewöhnlich ist, fällt sofort auf und wirkt wie ein Warnsignal. Als Kriterium taugt es nicht, denn auch gute neue Ideen sind neuartig, und Gruppe Y hält gerade an einer jahrhundertealten Erklärung fest."},{"option":2,"text":"Eine Universität oder ein Institut vermittelt Vertrauen und lässt sich leicht prüfen. Doch auch Pseudowissenschaft gründet eigene „Institute“ und „Fachzeitschriften“. Der Ort sagt daher wenig darüber, wie jemand mit Gegenbeweisen umgeht."},{"option":3,"text":"Ob sich eine Idee bestätigt, ist am Ende das, was zählt. Das weißt du aber erst hinterher, und eine testbare Hypothese bleibt auch dann wissenschaftlich, wenn sie scheitert. Gebraucht wird ein Kriterium, das schon vorher greift."}],"familie":"wissenschaft-abgrenzen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: „Science and Pseudo-Science“","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","seite":"Abschn. 3.2, 4.3, 5.1","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"f157395560afd93d"}},{"id":"qf-2","status":"entwurf","clusterId":"F","werkstueckRef":"F.1.4","stufe":3,"question":"Du fragst dich, ob eine Gruppe, der eine Freundin beigetreten ist, kontrollierend arbeitet. Welche Beobachtung ist ein Hinweis auf Informationskontrolle?","options":["Die Gruppe hält Mitglieder von kritischen Quellen fern und gibt zentrales Wissen nur gestuft weiter.","Die Gruppe gibt ihren Mitgliedern viel Zeit und Raum für gemeinsame Aktivitäten.","Die Gruppe bindet ihre Mitglieder durch eine herzliche Atmosphäre und viel Zuwendung.","Die Gruppe legt Wert auf einen klaren gemeinsamen Glauben und verbindliche Überzeugungen."],"correctIndex":0,"explanation":"Informationskontrolle zeigt sich daran, dass kritische Quellen verboten oder abgewertet werden und Wissen nur gestuft weitergegeben wird. Genau das schildert deine Freundin: Kritik wird vorab als „Propaganda von Abtrünnigen“ abgestempelt, und die wichtigen Lehren sind nur höheren Stufen zugänglich, sodass niemand die Behauptungen der Gruppe von außen prüfen kann. Herzlichkeit, gemeinsame Zeit und feste Überzeugungen sind dagegen keine Informationskontrolle und gehören zu fast jeder engagierten Gemeinschaft; übertriebene Zuwendung beim Anwerben kann allerdings ein eigenes Warnsignal sein. Erst wenn mehrere Kontrollmerkmale (bei Verhalten, Information, Denken und Gefühlen) zusammenkommen und stark ausgeprägt sind, spricht das für manipulative Kontrolle; ein einzelnes Merkmal beweist noch nichts. Checklisten wie das BITE-Modell sind dabei Beratungshilfen, keine gesicherten Messinstrumente.","coreRule":"⚡ Prüfe bei einer Gruppe die Struktur, nicht das Bekenntnis: Darf man ihre Behauptungen von außen überprüfen und kritisieren?","quote":"","quoteLabel":"","scenario":"Seit einigen Monaten ist deine Freundin Mitglied einer Gruppe, die sich „Aufbruch“ nennt. Sie erzählt, dass dort alle sehr herzlich miteinander umgehen. Neuerdings ruft sie kaum noch an. Als du sie auf einen kritischen Zeitungsartikel über die Gruppe ansprichst, sagt sie: „Das ist Propaganda von Abtrünnigen, so etwas lesen wir nicht. Die wichtigen Lehren gibt es sowieso erst für Mitglieder der höheren Stufen.“","kurz":"Wenn Kritik vorab als „Propaganda“ abgestempelt wird und die wichtigen Lehren nur oberen Stufen offenstehen, kann niemand die Behauptungen der Gruppe von außen prüfen. Informationskontrolle zeigt sich nicht an der Wärme der Gruppe, sondern an dieser Struktur.","prueffrage":"Was erzählt die Freundin über die Gruppe, und was davon fände man in einem Sportverein genauso?","rueckmeldung":[{"option":1,"text":"Gemeinsame Zeit klingt nach Vereinnahmung, ist aber bei fast jeder engagierten Gemeinschaft hoch, vom Sportverein bis zur Gemeinde. Sie sagt nichts darüber, ob sich die Behauptungen der Gruppe prüfen lassen."},{"option":2,"text":"Die Herzlichkeit fällt auf, weil deine Freundin sie hervorhebt. Übertriebene Zuwendung kann ein Warnsignal sein, betrifft aber nicht den Zugang zu Wissen; Informationskontrolle zeigt sich daran, ob Kritik ferngehalten und Wissen zurückgehalten wird."},{"option":3,"text":"Feste Überzeugungen haben auch Parteien, Kirchen und Vereine, und das ist für sich nicht bedenklich. Die Frage ist nicht, wie überzeugt die Gruppe ist, sondern ob sie verhindert, dass man ihre Überzeugungen überprüfen kann."}],"familie":"kontrolle-statt-bekenntnis","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Freedom of Mind Resource Center (S. Hassan): „Undoing Undue Influence and the BITE Model of Authoritarian Control“ (Handout)","oeffentlich":true,"url":"https://freedomofmind.com/wp-content/uploads/2024/04/BITE-Model-of-Authoritarian-Control-Handout.pdf","seite":"Abschnitt II. Information Control","abruf":"2026-10-12"},{"typ":"url","kurz":"Deutscher Bundestag (1998): Endbericht der Enquete-Kommission „Sogenannte Sekten und Psychogruppen“, Drucksache 13/10950","oeffentlich":true,"url":"https://dserver.bundestag.de/btd/13/109/1310950.pdf","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"229e7f1b4f3ed53e"}},{"id":"qf-3","status":"entwurf","clusterId":"F","werkstueckRef":"F.0","stufe":2,"question":"Ein Kritiker sagt über die Suche nach außerirdischer Intelligenz (SETI): „Das ist genauso schlimm wie Astrologie, denn gefunden wurde bisher nichts.“ Welcher Denkfehler steckt in diesem Argument?","options":["Er verwechselt Wissenschaft mit Technik, denn die Suche baut nur Empfangsgeräte und stellt selbst keine Hypothesen auf.","Er überschätzt die Beweislast, denn Hypothesen über Leben im All gelten grundsätzlich als nicht überprüfbar.","Er setzt „nicht bewiesen“ mit „widerlegt“ gleich und ignoriert, dass SETI prinzipiell überprüfbar ist.","Er misst am falschen Maßstab, denn Astrologie ist eine anerkannte Randwissenschaft mit vielen offenen Fragen."],"correctIndex":2,"explanation":"Ein Ausbleiben von Funden ist nicht dasselbe wie Widerlegung oder fehlende Methode. Die Suche nach außerirdischer Intelligenz zählt zur Grenzwissenschaft: spekulativ, aber prinzipiell empirisch überprüfbar. Ihr Zustand ist „nicht bewiesen“, nicht „widerlegt“. Eine Hypothese darf also unbewiesen sein und trotzdem ehrlich geprüft werden. Astrologie unterscheidet sich darin: Widersprüchliche Befunde werden ignoriert oder wegerklärt, und die Lehren bleiben seit ihrer Gründung oft unverändert und dogmatisch. Entscheidend ist also die Methode, nicht der bisherige Erfolg oder die Seltsamkeit der Idee.","coreRule":"⚡ „Nicht bewiesen“ und „widerlegt“ sind zwei verschiedene Zustände. Beurteile die Methode, nicht den bisherigen Misserfolg.","quote":"Konzentriere dich auf die Methode, nicht auf die Seltsamkeit der Behauptung.","quoteLabel":"Merksatz","beleg":"Werkstück F.0, Red Flags und Abschnitt Grenzwissenschaft (SETI als Beispiel); Fußnote gl-f-string zur Prüfbarkeitsdebatte","kurz":"Kein Fund heißt noch nicht „widerlegt“: SETI ist spekulativ, aber prinzipiell überprüfbar, und sein Stand ist „nicht bewiesen“. Der Kritiker misst am bisherigen Erfolg statt an der Methode, die Astrologie gerade fehlt.","prueffrage":"Welchen Teil des Himmels und der möglichen Funkfrequenzen hat die Suche bisher überhaupt abgedeckt?","rueckmeldung":[{"option":0,"text":"Empfangsgeräte sind bei SETI zwar zentral, aber sie dienen dazu, Annahmen über mögliche Signale an Daten zu prüfen. Genau das macht die Suche zu einem methodischen, überprüfbaren Unterfangen."},{"option":1,"text":"Dass es bisher keinen Fund gibt, macht die Hypothese nicht unprüfbar. Man weiß ziemlich genau, was ein Treffer wäre und wonach man sucht. Unbestätigt und unprüfbar sind zwei verschiedene Dinge."},{"option":3,"text":"„Falscher Maßstab“ wirkt treffend, doch die Begründung stimmt nicht: Astrologie ist keine anerkannte Randwissenschaft. Der Kritiker irrt woanders, denn er hält „bisher nichts gefunden“ für „widerlegt“."}],"familie":"wissenschaft-abgrenzen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: „Science and Pseudo-Science“","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","seite":"Abschn. 4.3, 4.5, 5.1","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"de73ad537bf63812"}},{"id":"qf-4","status":"entwurf","clusterId":"F","werkstueckRef":"F.1.2","stufe":1,"question":"Welche Erklärung ist am sparsamsten, und wie ließe sie sich am besten prüfen?","options":["Der Kollege hat recht: Das Futter kam jedes Mal nach dem Ritual. Eine Abfolge, die sich ständig wiederholt, spricht für einen Zusammenhang. Prüfen ließe sich das, indem man zählt, wie oft das Ritual dem Futter vorausgeht.","Der Kollege könnte falsch liegen: Das Futter kam im festen Takt, egal was die Tauben taten. Ein Verhalten kurz vor dem Futter kann zufällig mit ihm zusammengefallen sein. Prüfen ließe sich das, indem man schaut, ob das Futter ohne Ritual genauso kommt.","Der Kollege hat recht: Hungrige Tiere handeln stets zielgerichtet. Ein wirkungsloses Verhalten würden sie rasch wieder aufgeben. Prüfen ließe sich das mit Tauben, die man länger hungern lässt.","Der Kollege könnte falsch liegen: Rituale entstehen bei Tieren nur durch Nachahmung anderer Tiere. Ein Verhalten kann nur von Artgenossen übernommen worden sein. Prüfen ließe sich das mit jeder Taube allein in der Box."],"correctIndex":1,"explanation":"Die Fütterung folgte einem starren Zeittakt und hing von keiner Handlung ab. Skinner deutete die Rituale so, dass sich ein Verhalten, das zufällig kurz vor dem Futter auftrat, eingeprägt haben könnte: Gelernt haben die Tauben also durchaus etwas, aber ihr Ritual holte das Futter nicht herbei. Die sparsamste Erklärung braucht deshalb keinen echten Zusammenhang, denn bei festem Takt folgt das Futter immer irgendeinem Verhalten, und wie oft sich eine Abfolge wiederholt, beweist keine Ursache. Prüfen lässt sich das, indem man schaut, ob das Futter auch ohne Ritual genauso kommt. Spätere, genauere Wiederholungen des Versuchs deuteten vieles, was nach Ritual aussah, als gewöhnliches Pickverhalten kurz vor dem Futter oder als vom Fütterungstakt selbst hervorgelockt; eine gut passende Deutung ist also noch nicht die einzig mögliche.","coreRule":"⚡ Danach heißt nicht deswegen: Ein „wirksames“ Ritual belegt noch keine Ursache, solange nicht geprüft ist, was ohne das Ritual geschieht.","quote":"","quoteLabel":"","scenario":"Eine Forscherin setzt hungrige Tauben einzeln in eine Box, in der alle 15 Sekunden automatisch für einige Sekunden Futter erscheint, egal was die Tauben tun. Nach einiger Zeit zeigen mehrere Tauben auffällige Rituale: Eine dreht sich ständig im Kreis, eine andere stößt immer wieder mit dem Kopf in eine Ecke. Ein Kollege sagt: „Die Tauben haben offenbar gelernt, dass ihr Ritual das Futter herbeiholt.“","beleg":"Werkstück F.1.2, Fußnote gl-f-4 (Skinner 1948; Staddon & Simmelhag 1971)","kurz":"Das Futter kam im festen Takt, egal was die Tauben taten, und folgte so immer irgendeinem Verhalten. Was zufällig kurz davor geschah, kann sich eingeprägt haben, ohne das Futter zu bewirken; prüfen lässt sich das, indem man schaut, ob das Futter ohne Ritual genauso kommt.","prueffrage":"Wann genau kam das Futter, und was taten die Tauben jeweils unmittelbar davor?","rueckmeldung":[{"option":0,"text":"Das Futter kam tatsächlich oft nach dem Ritual, denn bei festem Takt folgt es immer irgendeinem Verhalten. Wie oft das geschieht, belegt aber keine Ursache: Das Futter wäre auch ohne Ritual gekommen."},{"option":2,"text":"Dass Hunger Tiere antreibt, ist plausibel, daraus folgt aber nicht, dass jedes Verhalten zielgerichtet ist oder Wirkungsloses rasch verschwindet. Längeres Hungern ändert die Motivation und sagt nichts darüber, ob das Ritual das Futter bewirkt."},{"option":3,"text":"Nachahmung erklärt Rituale hier kaum, denn die Tauben saßen einzeln in der Box und hatten kein Vorbild. Auch Verhalten ohne Vorbild kann sich einprägen. Eine Taube allein in der Box ist zudem schon die Ausgangslage und kein Vergleich."}],"familie":"was-waere-ohne","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Skinner, B. F. (1948): „'Superstition' in the Pigeon“, Journal of Experimental Psychology 38 (Nachdruck Classics in the History of Psychology)","oeffentlich":true,"url":"https://psychclassics.yorku.ca/Skinner/Pigeon/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Staddon, J. E. R.; Simmelhag, V. L. (1971): „The ‚Superstition‘ Experiment: A Reexamination …“, Psychological Review 78(1)","oeffentlich":false,"doi":"10.1037/h0030305"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"7c3ee1b9594d3319"}},{"id":"qf-5","status":"entwurf","clusterId":"F","werkstueckRef":"F.1.3","stufe":2,"question":"Ein Bekannter sagt: „Verschwörungen gibt es nicht. Dass Menschen im Geheimen zusammenarbeiten, ist reine Fantasie.“ Ein anderer behauptet: „Ein Konzern hält seit 40 Jahren zusammen mit Tausenden Mitwissern ein Geheimnis, und bisher hat niemand geplaudert.“ Welche Prüffrage trennt eine reale Verschwörung am besten von einem Verschwörungsmythos?","options":["Wie viele Personen müssten eingeweiht sein, welches begrenzte Ziel verfolgen sie, und wie lange hielte das Geheimnis?","Wie viele Menschen glauben an die Behauptung, und wie überzeugt und engagiert vertreten sie ihre Sicht im Netz?","Wie bedrohlich ist das behauptete Szenario, und wie sehr beschäftigt es die Öffentlichkeit und die Medien?","Wie lange gibt es die Behauptung schon, und wie oft wurde sie von anderen weitererzählt und geteilt?"],"correctIndex":0,"explanation":"Echte Verschwörungen wie Watergate oder der Iran-Contra-Skandal hatten eine begrenzte Zahl von Beteiligten und erreichbare Ziele, und sie wurden durch Lecks, Inkompetenz oder Recherche aufgedeckt. Je mehr Mitwisser, desto schneller fliegt ein Geheimnis auf. Eine Behauptung, die Tausende Eingeweihte über Jahrzehnte hinweg perfekt schweigen lässt, ist deshalb extrem unwahrscheinlich. Wie viele daran glauben, wie bedrohlich sie klingt und wie alt oder verbreitet sie ist, sagt dagegen nichts darüber, ob sie stimmt. Die pauschale Leugnung jeder Verschwörung ist ebenfalls falsch, denn echte Fälle existieren.","coreRule":"⚡ Zähle Mitwisser, Ziele und Lecks: Echte Verschwörungen sind begrenzt, Mythen grenzenlos.","quote":"","quoteLabel":"","scenario":"","kurz":"Reale Verschwörungen hatten eine begrenzte Zahl Beteiligter und erreichbare Ziele, und je mehr Mitwisser, desto schneller fliegt ein Geheimnis auf. Jede Verschwörung zu leugnen ist falsch, Tausende perfekt schweigende Mitwisser über Jahrzehnte sind extrem unwahrscheinlich.","prueffrage":"Könnten beide Aussagen zugleich falsch sein, und woran würdest du das jeweils festmachen?","rueckmeldung":[{"option":1,"text":"Viele Gläubige und lautes Engagement machen eine Behauptung sichtbar und wirken wie ein Hinweis auf etwas Wahres. Sie belegen aber nur, dass sie ankommt: Auch falsche Behauptungen finden begeisterte Anhänger."},{"option":2,"text":"Was bedrohlich klingt und die Medien beschäftigt, wirkt wie ein Hinweis auf große Wahrheit. Bedrohlichkeit sagt aber nichts darüber, ob etwas stimmt: Harmlose Absprachen können real sein, schreckliche Geschichten erfunden."},{"option":3,"text":"Eine Behauptung, die schon lange kursiert und oft geteilt wird, wirkt bewährt. Doch auch Mythen halten sich über Jahrzehnte, und Weitererzählen ist kein Beleg. Alter und Verbreitung sagen etwas über Beliebtheit, nicht über Wahrheit."}],"familie":"verschwoerung-pruefen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Grimes, D. R. (2016): „On the Viability of Conspiratorial Beliefs“, PLOS ONE 11(1), e0147905","oeffentlich":true,"doi":"10.1371/journal.pone.0147905","abruf":"2026-10-12"},{"typ":"url","kurz":"Lewandowsky, S.; Cook, J. (2020): The Conspiracy Theory Handbook","oeffentlich":true,"url":"https://skepticalscience.com/docs/ConspiracyTheoryHandbook.pdf","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"aa031c42d650da6c"}},{"id":"qf-6","status":"entwurf","clusterId":"F","werkstueckRef":"F.1.3.1","stufe":2,"question":"Ein Video raunt: „Dass wir keine Beweise finden, beweist nur, wie perfekt alles vertuscht wird!“ Was ist an diesem Schluss fehlerhaft?","options":["Er kehrt die Beweislast um: Wer widerspricht, soll erst beweisen, dass es nicht so gewesen ist.","Er greift winzige Auffälligkeiten heraus und bläht sie auf, während der große Rest der Daten verschwindet.","Er wertet fehlende Belege als Beleg für perfekte Tarnung, sodass jede Suche die Behauptung nur bestätigt.","Er verzerrt die gängige Erklärung zur Karikatur, damit sie bei den Zuschauern Wut und Angst auslöst."],"correctIndex":2,"explanation":"Der Schluss ist so gebaut, dass nichts ihn widerlegen kann: Findet man keine Beweise, gilt das als Zeichen perfekter Vertuschung; und auch ein Gegenbeweis würde als Teil der Verschwörung umgedeutet. Genau das ist das Warnsignal „Das Fehlen von Beweisen wird als Beweis gewertet“ (Argument aus Unwissenheit); zugleich ist die Erzählung unfalsifizierbar, denn es gibt kein Ereignis, das den Gläubigen von seiner Meinung abbringen könnte. Eine Behauptung, die kein Ereignis widerlegen kann, ist keine robuste Hypothese, sondern eine Festung des Glaubens. Die anderen Muster kommen in Verschwörungserzählungen ebenfalls vor, stecken aber nicht in diesem einen Satz.","coreRule":"⚡ Fehlende Belege sind kein Beleg für perfekte Tarnung.","quote":"","quoteLabel":"","scenario":"","beleg":"Werkstück F.1.3.1, Warnsignal 3 (Argument aus Unwissenheit, B.11); Warnsignal 4 (Unfalsifizierbarkeit, A.3)","kurz":"Findet man keine Beweise, gilt das als Zeichen perfekter Vertuschung, und selbst ein Gegenbeweis würde umgedeutet. So werden fehlende Belege zum Beleg, und die Behauptung ist gegen jede Prüfung abgeschirmt.","prueffrage":"Was hat die Suche nach Beweisen laut dem Video ergeben, und wie wird dieses Ergebnis gedeutet?","rueckmeldung":[{"option":0,"text":"Beweislastumkehr kommt in solchen Erzählungen tatsächlich oft vor. Im Satz verlangt aber niemand, etwas zu widerlegen; er deutet das Ausbleiben von Belegen selbst zum Beleg um. Genau dort liegt das Problem."},{"option":1,"text":"Das Herausgreifen kleiner Auffälligkeiten ist ein verbreitetes Muster, und es klingt hier nach Verschwörungsdenken. Der Satz stützt sich aber auf keine einzelnen Daten, sondern darauf, dass keine gefunden werden."},{"option":3,"text":"Eine verzerrte Gegenposition und gezielte Angstmache gehören oft zu solchen Erzählungen. In diesem Satz wird aber keine Erklärung angegriffen; er schützt vielmehr die eigene Behauptung davor, jemals widerlegt zu werden."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","seite":"Eintrag „Appeal to Ignorance“","abruf":"2026-10-12"},{"typ":"url","kurz":"Lewandowsky, S.; Cook, J. (2020): The Conspiracy Theory Handbook","oeffentlich":true,"url":"https://skepticalscience.com/docs/ConspiracyTheoryHandbook.pdf","seite":"Abschnitt CONSPIR, „Immune to evidence“","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"8e30be1af01c22e4"}},{"id":"qf-7","status":"entwurf","clusterId":"F","werkstueckRef":"F.1.5","stufe":2,"question":"Ein unbekanntes „Institut“ behauptet, ein Nahrungsergänzungsmittel senke den Blutdruck. Die Studie hat keine Kontrollgruppe, bleibt unveröffentlicht, ist aber voller Fachjargon und Grafiken. Welche Frage prüft am besten, ob hier echte Forschung vorliegt oder nur ihre äußere Form?","options":["Hätte ein Ergebnis, das der Behauptung widerspricht, überhaupt eine Chance gehabt, berichtet zu werden?","Wie viele Grafiken enthält die Studie, und sind sie so professionell gestaltet wie bei seriösen Veröffentlichungen?","Wie bekannt ist das Institut in den Medien, und wie lange gibt es das Mittel schon auf dem Markt?","Verwendet die Studie genug Fachbegriffe, um dem Thema gerecht zu werden und seriös zu wirken?"],"correctIndex":0,"explanation":"Entscheidend ist nicht, wie die Studie aussieht, sondern ob sie ehrlich scheitern könnte. Echte Forschung berichtet auch Beweise, die der eigenen Theorie widersprechen, und sucht aktiv nach Wegen, sie zu widerlegen; Kontrollgruppen und Replizierbarkeit gehören zu dieser methodischen Strenge. Jargon, Grafiken und Institutsname lassen sich beliebig kopieren, ohne dass die Methode dahintersteht. Der Nobelpreisträger Richard Feynman nannte das „Cargo-Kult-Wissenschaft“: Inselbewohner im Pazifik ahmten nach dem Abzug der US-Soldaten deren Rituale nach, legten Landebahnen an, zündeten Feuer an und setzten einen Mann mit Holzkopfhörern in eine Hütte. Die Form stimmte, aber ihnen fehlte das Verständnis der zugrundeliegenden Prinzipien, und die Flugzeuge kamen nicht. Die Frage nach der Chance auf Widerlegung trennt Landebahn und Flugzeug. Die anderen Fragen messen nur Oberfläche, Bekanntheit oder Fachsprache, und genau die lassen sich leicht fälschen.","coreRule":"⚡ Prüfe nicht, wie wissenschaftlich etwas aussieht, sondern ob es scheitern könnte: Kontrollgruppe, Replikation, berichtete Gegenbefunde.","quote":"Er hat die Landebahn, aber ihm fehlt der Geist der Wissenschaft.","quoteLabel":"Cargo-Kult-Wissenschaft","scenario":"Ein Freund schickt dir die Studie und sagt: „Das ist doch wissenschaftlich belegt, sieh dir allein die vielen Grafiken an!“","beleg":"Werkstück F.1.5, Fußnote gl-f-7 (Feynman, „Cargo Cult Science“, Caltech 1974)","kurz":"Echte Forschung könnte ehrlich scheitern und berichtet auch Ergebnisse, die ihrer Theorie widersprechen. Der naheliegende Fehler ist, Grafiken und Jargon für Wissenschaft zu halten, obwohl sich beides kopieren lässt, ohne dass eine Methode dahintersteht.","prueffrage":"Womit wurden die Werte der Teilnehmenden verglichen, und wo lässt sich die Studie nachlesen?","rueckmeldung":[{"option":1,"text":"Viele und gut gestaltete Grafiken wirken nach Arbeit und Sorgfalt, genau darauf setzt dein Freund. Grafiken lassen sich aber ohne jede Methode erzeugen und zeigen nicht, ob die Studie ihre Behauptung überhaupt hätte widerlegen können."},{"option":2,"text":"Ein bekanntes Institut und ein lange verkauftes Mittel vermitteln Vertrauen. Medienpräsenz und Marktdauer sagen aber nichts darüber, wie die Studie gearbeitet hat; ohne Kontrollgruppe und Veröffentlichung bleibt die Frage nach der Methode offen."},{"option":3,"text":"Fachbegriffe wirken wie ein Zeichen von Fachwissen, und echte Studien nutzen sie auch. Sie lassen sich aber leicht nachahmen: Hier gibt es reichlich Jargon, doch keine Kontrollgruppe. Fachsprache sagt nichts über die Methode."}],"familie":"wissenschaft-abgrenzen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Feynman, R. P. (1974): „Cargo Cult Science“, Engineering and Science 37(7), Caltech-Scan","oeffentlich":true,"url":"https://calteches.library.caltech.edu/51/2/CargoCult.pdf","seite":"S. 11–12","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"2afedb48b9346d2b"}},{"id":"qf-8","status":"entwurf","clusterId":"F","werkstueckRef":"F.1.6","stufe":4,"question":"Ein hochintelligenter Autor, berühmt für einen streng logisch denkenden Romandetektiv, hält inszenierte Feenfotos nach schweren persönlichen Verlusten im Ersten Weltkrieg für Beweise einer geistigen Welt. Seine Kritiker fragen, wie das möglich ist. Welche Erklärung ist am sparsamsten und erklärt zugleich, warum seine Intelligenz ihn nicht schützte?","options":["Er kannte die Fototechnik seiner Zeit zu wenig und deutete die Papierfiguren und Nadeln auf den Bildern daher falsch.","Er setzte seinen Verstand ein, um einen tröstlichen Glauben zu verteidigen, statt die Bilder ergebnisoffen zu prüfen.","Er wurde von den beiden Mädchen über Jahre planvoll getäuscht, die ihn gezielt für ihre eigenen Zwecke benutzten.","Er prüfte die Bilder gründlich, fand keinen Fälschungsnachweis und musste sie deshalb als echt behandeln."],"correctIndex":1,"explanation":"Gesucht ist eine Erklärung, die das Fehlurteil erklärt und zugleich, warum Intelligenz nicht davor schützte. Das gelingt, wenn man Intelligenz als Werkzeug versteht: Wer unbedingt glauben will, setzt seinen Verstand ein, um für den Glauben zu argumentieren, statt ihn ergebnisoffen zu prüfen. Conan Doyle suchte nach den Verlusten des Ersten Weltkriegs Trost im Fortleben der Toten, und die Fotos waren für ihn eher Bestätigung als offene Frage. Zwar wurden die Bilder begutachtet, doch dass kein Fälschungsnachweis gefunden wurde, belegt noch keine Echtheit. Die Mädchen hatten mit einem Scherz begonnen und gaben erst Jahrzehnte später zu, mit Papierfiguren und Nadeln gearbeitet zu haben; dass sie ihn gezielt für eigene Zwecke benutzten, ist nicht belegt, und weder ihre Täuschung noch mangelndes Wissen über Fototechnik erklärt, warum ein scharfer Denker so bereitwillig darauf hereinfiel.","coreRule":"⚡ Kritisches Denken ist eine Praxis, die man anwenden muss, keine Eigenschaft, die man besitzt: Je stärker das Bedürfnis zu glauben, desto eher dient die Intelligenz dem Wunsch statt der Prüfung.","quote":"","quoteLabel":"","scenario":"","kurz":"Intelligenz ist ein Werkzeug, das seinem Besitzer dient. Wer nach schweren Verlusten unbedingt glauben will, setzt den Verstand ein, um den Trost zu verteidigen, statt die Bilder ergebnisoffen zu prüfen. Das erklärt das Fehlurteil und den fehlenden Schutz.","prueffrage":"Was hätte ein fehlender Fälschungsnachweis über die Echtheit der Bilder gesagt, und wie ging der Autor damit um?","rueckmeldung":[{"option":0,"text":"Mangelndes Wissen über Fototechnik mag mitgespielt haben. Es erklärt aber nicht, warum gerade ein scharfer Denker so entschieden für die Echtheit eintrat, ohne die eigene Überzeugung kritisch zu prüfen."},{"option":2,"text":"Die Mädchen haben die Bilder tatsächlich gefälscht, doch angefangen hatte es als Scherz, nicht als Plan, ihn zu benutzen. Vor allem erklärt eine Täuschung nicht, warum ein scharfer Denker so bereitwillig darauf hereinfiel."},{"option":3,"text":"Begutachtet wurden die Bilder zwar, doch ein nicht gefundener Fälschungsnachweis ist noch kein Beleg für Echtheit. Wer daraus „echt“ macht, prüft nicht mehr ergebnisoffen, sondern sucht Bestätigung."}],"familie":"werkzeuge-gegen-sich-selbst","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Doyle, A. C. (1922): The Coming of the Fairies (Project Gutenberg Nr. 47506)","oeffentlich":true,"url":"https://www.gutenberg.org/files/47506/47506-0.txt","abruf":"2026-10-12"},{"typ":"url","kurz":"University of Leeds Library, Special Collections: Katalogeintrag Cottingley Fairies (Papierfiguren mit Hutnadeln, Geständnis 1983)","oeffentlich":true,"url":"https://explore.library.leeds.ac.uk/special-collections-explore/8705","abruf":"2026-10-12"},{"typ":"url","kurz":"Kahan, D. M.; Peters, E.; Dawson, E. C.; Slovic, P. (2013): Motivated Numeracy and Enlightened Self-Government (Working Paper, Yale Cultural Cognition Project)","oeffentlich":true,"url":"https://scholarsbank.uoregon.edu/items/e034d504-ed17-4e0c-a713-ac3f85a8187a/full","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"49645ead4ec90614"}},{"id":"qf-9","status":"entwurf","clusterId":"F","werkstueckRef":"F.1.7","stufe":3,"question":"Eine Biologin sagt: „Das bakterielle Flagellum besteht aus vielen Teilen, die nur im Zusammenspiel funktionieren. Entfernt man ein Teil, geht die Fortbewegung verloren. Also kann es nicht schrittweise entstanden sein, es muss geplant worden sein.“ Welche Antwort trifft den Fehler in diesem Schluss am besten?","options":["Der Schluss übersieht, dass Teilfunktionen früher einen anderen Nutzen gehabt haben können und später in ein neues System eingebaut wurden.","Der Schluss übersieht, dass sich komplexe Strukturen durch zufällige Kombination von Teilen bilden, sobald es genug Versuche gibt.","Der Schluss übersieht, dass alle Teile durch eine einzige große Mutation gleichzeitig entstanden sein können und sofort nützlich waren.","Der Schluss ist zwar richtig, beweist aber keinen Designer, sondern zeigt nur eine Lücke in unserem Wissen über die Entstehung."],"correctIndex":0,"explanation":"Aus „ohne ein Teil funktioniert das heutige System nicht“ folgt nicht „es gab nie einfachere Vorstufen“. Teilfunktionen bieten zunächst oft andere Vorteile und werden später in neue Kontexte integriert (Exaptation). Beim Flagellum zeigt das Typ-III-Sekretionssystem, dass ein Teil seiner Bauteile auch ohne den Rest eine andere, nützliche Funktion erfüllen kann; ob es Vorläufer, Abkömmling oder nur Verwandter ist, ist umstritten. Evolution ist zudem kein reiner Zufall, sondern kombiniert zufällige Mutation mit nicht-zufälliger Selektion über lange Zeiträume. Die anderen Antworten tragen nicht: Reine Zufallskombination und eine einzige Großmutation sind keine tragfähigen Erklärungen. Und die Aussage, der Schluss sei richtig und zeige nur eine Wissenslücke, nimmt die Prämisse „nur im Ganzen funktionsfähig“ als gegeben hin und übersieht, dass genau in ihr der Fehler steckt.","coreRule":"⚡ „Heute nur im Ganzen funktionsfähig“ heißt nicht „ohne Vorläufer entstanden“: Teile können früher anderen Nutzen gehabt haben.","quote":"Evolutionäre Prozesse sind keine rein zufälligen Schritte, sondern kombinieren zufällige Mutation und nicht-zufällige Selektion zu einem Mechanismus, der Komplexität schrittweise aufbaut.","quoteLabel":"Merksatz:","scenario":"Du hörst diese Behauptung in einer Diskussion über die Entstehung komplexer Strukturen bei Bakterien.","beleg":"Werkstück F.1.7, Kontext & Tiefe Abschnitt 1 und 2; Fußnote gl-f-kitzmiller (Typ-III-Sekretionssystem als möglicher Vorläufer, Urteil S. 74–77)","kurz":"Dass das heutige Flagellum ohne ein Teil nicht funktioniert, heißt nicht, dass es nie einfachere Vorstufen gab: Teile können zuvor anderen Zwecken gedient haben und später neu eingebaut worden sein. Der Fehler liegt im Schluss von „heute unverzichtbar“ auf „nie schrittweise“.","prueffrage":"Woher weiß die Biologin, wie die Vorfahren dieser Bakterien ausgestattet waren?","rueckmeldung":[{"option":1,"text":"Zufall spielt bei Mutationen tatsächlich eine Rolle, und viele Versuche klingen nach einem Ausweg. Bloße Zufallskombination erklärt komplexe Strukturen aber nicht; erst die nicht-zufällige Selektion über lange Zeiträume macht den Unterschied."},{"option":2,"text":"Eine einzige Mutation, die alle Teile auf einmal liefert, würde die Frage nach Vorstufen umgehen. Sie ist aber äußerst unwahrscheinlich und keine tragfähige Erklärung für ein Gebilde aus vielen Teilen."},{"option":3,"text":"Richtig ist, dass der Schluss auf einen Designer nicht zwingend folgt. Doch schon der Schritt davor trägt nicht: Aus „heute nur im Ganzen funktionsfähig“ folgt nicht, dass es keine Vorstufen gab. Das ist ein Denkfehler, nicht nur eine Wissenslücke."}],"familie":"auslese-statt-plan","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Kitzmiller v. Dover Area School District, U.S. District Court M.D. Pa., Memorandum Opinion vom 20.12.2005","oeffentlich":true,"url":"https://www.pamd.uscourts.gov/sites/pamd/files/opinions/04v2688d.pdf","seite":"S. 74–77","abruf":"2026-10-12"},{"typ":"url","kurz":"University of California Museum of Paleontology: Understanding Evolution, „Misconceptions about evolution“","oeffentlich":true,"url":"https://evolution.berkeley.edu/teach-evolution/misconceptions-about-evolution/","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"78902f77048b47c8"}},{"id":"qf-10","status":"entwurf","clusterId":"F","werkstueckRef":"F.2.1","stufe":1,"question":"Was folgt daraus für die Behauptung des Anbieters?","options":["Beide haben praktisch dasselbe Horoskop, verlaufen aber verschieden. Wenn die Planetenstellung den Charakter festlegen würde, müssten sie sich viel ähnlicher sein. Die Behauptung passt nicht zur Beobachtung.","Beide haben fast dieselben Gene, deshalb lässt sich der Einfluss der Sterne nicht von dem der Erbanlagen trennen. Das Paar sagt über die Behauptung des Anbieters nichts aus.","Beide müssten getrennt aufgewachsen sein, damit sich überhaupt prüfen lässt, was die Sterne bewirken. Ohne getrennte Kindheit ist das Paar als Beispiel wertlos.","Beide gelten als Ausnahme, weil Astrologen das Horoskop nach der Geburtsminute des erstgeborenen Kindes berechnen. Das zweite Kind bekäme dann das Horoskop des ersten."],"correctIndex":0,"explanation":"Wenn die Planetenstellung zur Geburtszeit den Charakter und Lebensweg festlegen soll, müssen Menschen mit praktisch gleicher Stellung sich ähnlich entwickeln. Eineiige Zwillinge, die am selben Ort fast gleichzeitig geboren werden, haben praktisch dasselbe Horoskop. Wenn sie sich trotzdem deutlich unterscheiden, passt die starke Behauptung der festen Kausalität nicht zur Beobachtung. Der Einwand mit den Genen trifft nicht zu: Gleiche Gene würden Ähnlichkeit erklären, nicht die Unterschiede. Sauberer ist deshalb der Test mit nicht verwandten „Zeitzwillingen“: Gut 2.000 Londoner, die im März 1958 geboren wurden, ähnelten ihren Zeitzwillingen in Intelligenz, Verhalten und Körpermerkmalen nicht stärker als beliebigen anderen. Auch eine getrennte Kindheit ist für den Test unnötig, denn die Behauptung betrifft die Planetenstellung, nicht die Erziehung. Und die Annahme, das Horoskop werde nach der Geburtsminute des erstgeborenen Kindes berechnet, erfindet eine Regel, die nicht belegt ist.","coreRule":"⚡ Gleiche Ursache, verschiedene Wirkung: Wer behauptet, etwas bestimme den Charakter, muss erklären, warum Gleiches zu Verschiedenem führt.","quote":"","quoteLabel":"","scenario":"Ein Horoskop-Anbieter wirbt: „Die Planetenstellung bei der Geburt legt Charakter und Lebensweg fest.“ Du kennst ein eineiiges Zwillingspaar, das am selben Ort mit wenigen Minuten Abstand geboren wurde. Die beiden sind in Temperament, Beruf und Lebensweg sehr verschieden.","kurz":"Praktisch gleiche Planetenstellung, aber deutlich verschiedene Lebenswege: Das passt nicht zu einer festen Kausalität, die Ähnlichkeit erwarten ließe. Gleiche Gene erklären höchstens Ähnlichkeit, nicht die Unterschiede.","prueffrage":"Welche Rolle spielen Gene oder Erziehung in der Behauptung des Anbieters überhaupt?","rueckmeldung":[{"option":1,"text":"Gene prägen den Charakter tatsächlich mit. Gleiche Gene würden aber Ähnlichkeit erklären, nicht die Unterschiede, die hier auffallen. Das Paar widerspricht der Behauptung des Anbieters also durchaus."},{"option":2,"text":"Getrennt aufgewachsene Zwillinge helfen bei der Frage nach Anlage und Umwelt. Die Behauptung betrifft aber nur die Planetenstellung, nicht die Erziehung. Dafür ist eine getrennte Kindheit nicht nötig."},{"option":3,"text":"Eine Sonderregel für Zwillinge scheint den Widerspruch aufzulösen. Sie ist aber erfunden, und selbst wenn sie gälte, hätten beide dasselbe Horoskop und müssten sich umso ähnlicher sein."}],"familie":"korrelation-und-ursache","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dean, G.; Kelly, I. W. (2003): Is Astrology Relevant to Consciousness and Psi? Journal of Consciousness Studies 10(6–7), S. 175–198 (Webfassung)","oeffentlich":true,"url":"https://www.astrology-and-science.com/D-psia2.htm","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"b956d6d8f61c4cf7"}},{"id":"qf-11","status":"entwurf","clusterId":"F","werkstueckRef":"F.2.3","stufe":3,"question":"In einem Forum behauptet jemand: „In den Wäldern Nordamerikas lebt ein riesiger Menschenaffe. Bisher hat ihn nur niemand eindeutig erwischt, zum Beispiel mit einem Kadaver, einem Knochen oder verwertbarer DNA.“ Welche Frage prüft diese Behauptung am besten?","options":["Gibt es mindestens ein einzelnes Tier, das über viele Jahrzehnte hinweg unentdeckt geblieben ist, ohne dass jemand es gesehen hat?","Gibt es genug Augenzeugenberichte, um die Existenz auch ohne Kadaver, Knochen oder DNA als gesichert zu betrachten, wenn viele Zeugen übereinstimmen?","Gibt es eine ganze Population aus Hunderten oder Tausenden Tieren, die sich fortpflanzt, ohne dass je ein eindeutiger Beleg gefunden wurde?","Gibt es eine Art, die so selten ist, dass sie nach den Regeln der Ökologie jeder Beobachtung entgeht, auch über viele Generationen?"],"correctIndex":2,"explanation":"Ein einzelnes Tier kann keine Art begründen: Damit eine Art nicht ausstirbt, braucht sie eine Population, bei großen Säugetieren Hunderte, wenn nicht Tausende Individuen. Genau diese Population macht die Behauptung prüfbar. So viele große Tiere müssten fressen, sich fortpflanzen und sterben, und sie würden dabei Kadaver, Knochen, Exkremente oder DNA hinterlassen. Die entscheidende Frage lautet deshalb, wie eine solche Population absolut keine eindeutigen Spuren hinterlassen soll. Die übrigen Fragen weichen aus: Ein einzelnes Tier klärt die Frage nach der Art nicht, Augenzeugenberichte gehören zu den schwächsten Belegen, weil Menschen sich irren können, und ersetzen keinen Kadaver, und „zu selten, um beobachtet zu werden“ widerspricht der Idee einer überlebensfähigen Population. Dass der Gorilla einst als Mythos galt, belegt Bigfoot nicht, es zeigt nur, dass die Welt damals weniger erforscht war.","coreRule":"⚡ Eine Art braucht eine Population, und eine Population hinterlässt Spuren.","quote":"","quoteLabel":"","scenario":"","kurz":"Eine große Säugetierart, die sich über Generationen hält, braucht Hunderte, wenn nicht Tausende Tiere, und die müssten Kadaver, Knochen, Kot oder DNA hinterlassen. Erst die Frage, wie so viele Tiere spurlos bleiben sollen, macht die Behauptung prüfbar.","prueffrage":"Was hinterlässt ein großes Säugetier, während es lebt, frisst und stirbt, und was davon wurde je gefunden?","rueckmeldung":[{"option":0,"text":"Ein einzelnes Tier unentdeckt zu denken, wirkt bescheidener und leichter zu halten. Aber selbst wenn es das gäbe: Ein Einzeltier begründet keine Art und klärt deshalb nicht, ob die behauptete Art existiert."},{"option":1,"text":"Viele übereinstimmende Berichte scheinen Gewicht zu haben. Doch Augenzeugen können sich irren, und kein Bericht ersetzt einen Kadaver, einen Knochen oder DNA. Als Anlass zum Suchen taugen sie, als Beweis nicht."},{"option":3,"text":"Dass sehr seltene Arten schwer zu finden sind, stimmt. So selten, dass sie jeder Beobachtung entgeht, kann eine große Säugerart über Generationen aber kaum sein: Dafür braucht sie Hunderte, wenn nicht Tausende Tiere."}],"familie":"population-und-spuren","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Traill, L. W.; Bradshaw, C. J. A.; Brook, B. W. (2007): Minimum viable population size: A meta-analysis of 30 years of published estimates. Biological Conservation 139, S. 159–166 (Autorenfassung)","oeffentlich":true,"doi":"10.1016/j.biocon.2007.06.011","url":"https://conservationbytes.com/wp-content/uploads/2011/03/traill-et-al-2007-biol-conserv.pdf","seite":"S. 159","abruf":"2026-10-12"},{"typ":"doi","kurz":"Sykes, B. C. u. a. (2014): Genetic analysis of hair samples attributed to yeti, bigfoot and other anomalous primates. Proc. R. Soc. B 281, 20140161","oeffentlich":true,"doi":"10.1098/rspb.2014.0161","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"c8bd3b5d2bcbf740"}},{"id":"qf-12","status":"entwurf","clusterId":"F","werkstueckRef":"F.2.4","stufe":2,"question":"Jemand sagt: „Wie sollen Menschen damals ohne moderne Technik die Pyramiden gebaut haben? Ich kann mir das nicht vorstellen. Also müssen es Aliens gewesen sein.“ Was ist an dieser Argumentationskette fehlerhaft?","options":["Aus dem Alter der Bauwerke wird auf ihre Herkunft geschlossen, obwohl Alter und Bauweise nichts miteinander zu tun haben.","Aus der Beliebtheit einer Idee wird auf ihre Wahrheit geschlossen, obwohl viele Menschen an Außerirdische glauben.","Aus einer einzelnen auffälligen Ähnlichkeit wird auf eine Ursache geschlossen, obwohl Ähnlichkeit zufällig sein kann.","Aus der eigenen Vorstellungslücke wird auf eine Erklärung geschlossen, obwohl fehlende Vorstellungskraft nichts darüber sagt, was möglich war."],"correctIndex":3,"explanation":"Die Kette lautet: „Ich kann mir nicht vorstellen, wie das ging, also waren es Aliens.“ Damit wird eine Grenze der eigenen Vorstellungskraft zum Beweis für eine ganz andere Erklärung gemacht. Das ist das Argument aus persönlichem Unglauben. Dass jemand sich etwas nicht ausmalen kann, sagt nichts darüber, was Menschen mit über Generationen angesammelter Erfahrung leisten können. Experimentelle Archäologie hat für fast alle angeblichen Rätsel dieser Art plausible menschliche Bau- und Transportmethoden demonstriert oder rekonstruiert. Die Alien-Hypothese umgeht so die Beweislast, statt sie zu erfüllen.","coreRule":"⚡ „Ich kann es mir nicht vorstellen“ beschreibt meine Grenze, nicht die Grenze der Menschen von damals.","quote":"","quoteLabel":"","beleg":"Werkstück F.2.4 (Prä-Astronautik), Abschnitt 3 „Die Konfrontation mit der Realität“ und Abschnitt 4 „Die Anatomie der Täuschung“","kurz":"Dass jemand sich etwas nicht vorstellen kann, sagt nichts darüber, was Menschen leisten konnten. Der Fehler: Die eigene Ratlosigkeit wird zum Beweis für Aliens, ohne dass diese Erklärung selbst belegt wird.","prueffrage":"Welche Belege nennt die Person für ihre eigene Erklärung, und gibt es dafür überhaupt welche?","rueckmeldung":[{"option":0,"text":"Das Alter der Bauwerke spielt in der Aussage kaum eine Rolle. Der Schluss ruht nicht auf dem Alter, sondern darauf, dass sich die Person den Bau nicht vorstellen kann."},{"option":1,"text":"Dass viele Menschen an Außerirdische glauben, sagt tatsächlich nichts über deren Existenz. Hier wird aber gar nicht mit Beliebtheit argumentiert, sondern mit der eigenen Ratlosigkeit."},{"option":2,"text":"Eine Ähnlichkeit zwischen zwei Dingen wird hier nirgends angeführt. Gestützt wird die Alien-Erklärung allein durch die Aussage, man könne sich den Bau nicht vorstellen."}],"familie":"vorstellung-ist-kein-massstab","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Chow, D. (2014): „Solved! How Ancient Egyptians Moved Massive Pyramid Stones“. Live Science, nachgedruckt bei NBC News, 01.05.2014","oeffentlich":true,"url":"https://www.nbcnews.com/science/science-news/solved-how-ancient-egyptians-moved-massive-pyramid-stones-n95171","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"378fe3f71c69c452"}},{"id":"qg-1","status":"entwurf","clusterId":"G","werkstueckRef":"G.1.1","stufe":1,"question":"Eine Freundin sagt dir: „Ich bin endlich aufgewacht. Wer das alles noch glaubt, schläft einfach noch.“ Du widersprichst mit einem Gegenbeleg, sie antwortet: „Genau so reden Schlafschafe.“ Was ist an ihrer Argumentation das Kernproblem?","options":["Sie stützt sich auf die Mehrheit: Weil immer mehr Menschen so denken, soll die Behauptung stimmen.","Sie bleibt zu vage: Es fehlt ein freundliches Etikett für die Gegenseite, das den Dialog erleichtert.","Sie sortiert die Gegenseite vorab: Widerspruch gilt als Beweis des Schlafs, so kann kein Beleg mehr zählen.","Sie verzichtet auf Details: Mit genauerer Statistik zu informierten Bürgern wäre die Aussage prüfbar."],"correctIndex":2,"explanation":"Die Freundin teilt die Welt in zwei Lager: Wer „wach“ ist, sieht die Wahrheit, wer widerspricht, „schläft“. Damit wird jeder Einwand schon vor der Prüfung entwertet, denn er gilt nicht als Argument, sondern als Symptom. Eine Behauptung, die durch kein denkbares Gegenargument mehr erschüttert werden kann, ist nicht prüfbar (unfalsifizierbar). Zugleich wird die Gegenseite zu fügsamen „Schafen“ herabgesetzt, sodass ein Gespräch über die Sache kaum noch möglich ist. Eine sinnvolle Reaktion: nicht darüber streiten, wer wach ist, sondern fragen, welcher Beleg sie überzeugen würde und welcher nicht.","coreRule":"⚡ Wenn Widerspruch selbst als Beweis gegen den Widersprechenden gilt, ist die Aussage gegen Prüfung abgeschirmt.","quote":"Jede Kritik von außen kann daher ignoriert werden; sie kommt ja nur von einem Schlafenden, der die wahre Realität nicht wahrnehmen kann.","quoteLabel":"Merksatz:","scenario":"","kurz":"Wer widerspricht, „schläft“ – so wird jeder Einwand zum Symptom statt zum Argument, und nichts kann die Behauptung mehr erschüttern. Das macht sie unprüfbar, und die Gegenseite wird nebenbei herabgesetzt.","prueffrage":"Worauf ging die Freundin in ihrer Antwort ein: auf den Inhalt deines Gegenbelegs oder auf etwas anderes?","rueckmeldung":[{"option":0,"text":"Von einer Mehrheit ist im Gespräch gar nicht die Rede; die Freundin beruft sich nicht darauf, dass viele so denken. Das Problem liegt woanders: Dein Gegenbeleg wird nicht geprüft, sondern als Zeichen des Schlafs gewertet."},{"option":1,"text":"Unklar ist zwar, was „das alles“ meint, doch ein freundlicheres Etikett würde daran nichts ändern. Der Kern liegt woanders: Jeder Widerspruch gilt von vornherein als Beweis des Schlafs."},{"option":3,"text":"Genauere Angaben machen Aussagen oft besser prüfbar. Hier würde das aber nichts ändern, denn jeder Beleg gälte schon im Voraus als Zeichen des Schlafs. Das Problem ist nicht fehlendes Detail, sondern dass nichts mehr zählen darf."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Karl Popper (überarb. 31.07.2026), Abschn. 2","oeffentlich":true,"url":"https://plato.stanford.edu/entries/popper/","abruf":"2026-10-12"},{"typ":"url","kurz":"Lewandowsky, S.; Cook, J. (2020): The Conspiracy Theory Handbook","oeffentlich":true,"url":"https://climatecommunication.gmu.edu/wp-content/uploads/2023/09/ConspiracyTheoryHandbook.pdf","seite":"7","abruf":"2026-10-12"},{"typ":"doi","kurz":"Körber, M.-L. (2025): The Infamous Afterlife of Popular Films: Metaphorical Production of Meaning in the Manosphere through The Matrix. Fandom | Cultures | Research 2(1), 18–31","oeffentlich":true,"doi":"10.25969/mediarep/23948","url":"https://journals.uni-marburg.de/fcr/article/download/8779/8508/21457","seite":"24","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"6f54682e72bfc2de"}},{"id":"qg-2","status":"entwurf","clusterId":"G","werkstueckRef":"G.1.2","stufe":2,"question":"Woran erkennst du am ehesten, dass diese Aufforderung eher Gefolgschaft als echte Prüfung meint?","options":["Daran, dass die Aufforderung Unabhängigkeit verspricht, die „Recherche“ aber nur Beiträge aus der eigenen Echokammer wiederholt.","Daran, dass Suchmaschinen vor allem Fachaufsätze anzeigen, die Laien überfordern und so in Resignation treiben.","Daran, dass die Aufforderung Eigenrecherche abwertet und stattdessen blindes Vertrauen in Experten verlangt.","Daran, dass die Recherche an Algorithmen ausgelagert wird, die allen Nutzern unabhängig von Vorlieben dasselbe anzeigen."],"correctIndex":0,"explanation":"Ein Aufruf zum Selbstdenken ist nur dann echte Prüfung, wenn er ergebnisoffen ist und auch die stärksten Gegenargumente einbezieht. Hier führen alle „eigenen“ Quellen aus demselben Umfeld zum selben vorgegebenen Ergebnis. Das ist Bestätigungssuche und Anpassung an die Gruppe, getarnt als Unabhängigkeit. Ein Hinweis darauf: In einer US-Panelbefragung sank bei Befragten, die „eigene Recherche ist so viel wert wie Expertenwissen“ stärker zustimmten, binnen drei Monaten eher das Vertrauen in die Wissenschaft, und sie hielten mehr Falsches über COVID-19 für wahr. Der Zusammenhang war schwach, und die Autoren deuten ihn eher als Haltung gegen Experten als als Bekenntnis zu sorgfältiger Prüfung. Eine gute Gegenfrage lautet daher: „Wie stellst du sicher, dass du nicht nur Bestätigung suchst? Wo hast du aktiv nach den stärksten Argumenten gegen deine Position gesucht?“","coreRule":"⚡ Scheinbare Autonomie: Wer „selbst recherchiert“, aber nur Bestätigung aus der eigenen Echokammer sammelt, prüft nicht ergebnisoffen.","quote":"","quoteLabel":"","scenario":"Ein Bekannter hält dir entgegen: „Glaub nicht den Experten, recherchier lieber selbst!“ Er schickt dir vier Videos aus seinem Lieblingskanal, die alle denselben Schluss ziehen.","kurz":"Echte Prüfung ist ergebnisoffen und sucht auch die stärksten Gegenargumente. Wenn alle „eigenen“ Quellen aus demselben Umfeld denselben Schluss liefern, ist das Bestätigungssuche und Gruppenanpassung im Gewand der Unabhängigkeit.","prueffrage":"Wer hat ausgewählt, was du dir ansehen sollst, und was davon hast du selbst gefunden?","rueckmeldung":[{"option":1,"text":"Dass Laien an Fachtexten verzweifeln können, ist nachvollziehbar. Dein Bekannter wirkt aber nicht überfordert: Seine „Recherche“ besteht aus vier Videos eines einzigen Kanals, die alle denselben Schluss ziehen."},{"option":2,"text":"Blindes Vertrauen in Experten wäre tatsächlich kein Ideal. Hier ist es aber umgekehrt: Der Bekannte fordert Eigenrecherche ein und misstraut den Experten. Auffällig ist nicht, dass er recherchieren lässt, sondern wohin die Recherche führen soll."},{"option":3,"text":"Algorithmen können die Suche tatsächlich lenken, aber nicht so: Sie zeigen nicht allen dasselbe, sondern richten sich oft nach früheren Vorlieben. Entscheidend ist hier, dass alle Videos aus einem Kanal mit vorgegebenem Ergebnis stammen."}],"familie":"gegenbeleg-suchen","fertigkeit":"F5","quellen":[{"typ":"doi","kurz":"Chinn, S.; Hasell, A. (2023): Support for “doing your own research” is associated with COVID-19 misperceptions and scientific mistrust. HKS Misinformation Review 4(3)","oeffentlich":true,"doi":"10.37016/mr-2020-117","url":"https://misinforeview.hks.harvard.edu/article/support-for-doing-your-own-research-is-associated-with-covid-19-misperceptions-and-scientific-mistrust/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Nickerson, R. S. (1998): Confirmation Bias: A Ubiquitous Phenomenon in Many Guises. Review of General Psychology 2(2), 175–220","oeffentlich":false,"doi":"10.1037/1089-2680.2.2.175"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"d2904030e46e5e61"}},{"id":"qg-3","status":"entwurf","clusterId":"G","werkstueckRef":"G.2.3","stufe":2,"question":"Welche Wirkung hat schon das Wort „Schulmedizin“ in diesem Satz?","options":["Das Wort lässt die wissenschaftliche Medizin wie eine unter mehreren gleichrangigen Lehrmeinungen erscheinen und rückt die eigene, unbelegte Methode auf Augenhöhe.","Das Wort lobt die wissenschaftliche Medizin als bewährte Tradition und stellt sie als zuverlässigen Standard dar, den die eigene Methode ergänzt.","Das Wort beschreibt neutral, wer Medizin lehrt und wo sie gelehrt wird, und enthält deshalb keine Wertung über die Qualität der Verfahren.","Das Wort teilt die Medizin nach den Kosten auf und rückt die eigene, günstigere Methode als die gerechtere Wahl in ein gutes Licht."],"correctIndex":0,"explanation":"Das Wort meint eigentlich die an Universitäten gelehrte Medizin und ist allgemein gebräuchlich. In diesem Satz wirkt es aber als Kampfbegriff: „Nur eine von mehreren Schulen“ macht die wissenschaftliche Medizin zu einer Lehrmeinung unter vielen und unterstellt zwei gleichwertige Lager, eine falsche Symmetrie. Tatsächlich unterscheidet man Methoden danach, ob ihre Wirksamkeit nach wissenschaftlichen Standards nachgewiesen ist; das ist keine Frage der Schulzugehörigkeit, sondern von Belegen. So verschiebt der Satz die Frage „Wirkt es?“ zu „Welche Schule bevorzugst du?“. Eine bessere Rückfrage lautet: „Meinst du die wissenschaftsbasierte Medizin, die sich durch Testung und Überprüfung ständig selbst korrigiert?“","coreRule":"⚡ Falsche Symmetrie: Es gibt keine zwei Schulen – es gibt Evidenz oder keine Evidenz.","quote":"","quoteLabel":"","scenario":"Ein Heilpraktiker wirbt für eine Methode, deren Wirksamkeit in Studien nicht belegt ist. Im Gespräch sagt er: „Die Schulmedizin ist nur eine von mehreren Schulen, wir bieten eine gleichwertige Alternative.“","beleg":"Werkstück G.2.3, Abschnitte 2 und 4 (Strohmann, falsche Symmetrie, Aktivierungs-Frage); keine Fußnoten-ID; Kurzquelle: Buchtext","kurz":"Das Wort „Schulmedizin“ macht die wissenschaftliche Medizin hier zur Lehrmeinung unter vielen. Es stellt zwei gleichwertige Lager nebeneinander, obwohl Methoden danach unterschieden werden, ob ihre Wirkung belegt ist. So wird aus „Wirkt es?“ ein „Welche Schule magst du?“.","prueffrage":"Was erfährst du über die Wirksamkeit eines Verfahrens, wenn du nur hörst, zu welcher „Schule“ es gehört?","rueckmeldung":[{"option":1,"text":"Dass die wissenschaftliche Medizin als verlässlicher Standard gilt, ist nachvollziehbar. Der Satz lobt sie aber nicht: Er macht sie zu einer „Schule“ unter mehreren und nennt die eigene Methode gleichwertig, nicht bloß ergänzend."},{"option":2,"text":"Das Wort meint ursprünglich die an Hochschulen gelehrte Medizin und ist gebräuchlich, was neutral wirkt. In diesem Satz stellt es aber „Schulen“ als gleichwertige Lager nebeneinander und macht aus der Frage nach Wirksamkeit eine Frage der Vorliebe."},{"option":3,"text":"Preise und Kosten spielen im Satz gar keine Rolle. Worum es geht, ist der Nachweis der Wirksamkeit, und von dem lenkt das Wort „Schule“ ab: Es lässt eine Wahl zwischen gleichwertigen Lagern entstehen, wo es um Belege gehen müsste."}],"familie":"gewicht-statt-redezeit","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Koehler, D. J. (2016): Can journalistic “false balance” distort public perception of consensus in expert opinion? J Exp Psychol Appl 22(1), 24–38 (Abstract auf PubMed)","oeffentlich":true,"doi":"10.1037/xap0000073","url":"https://pubmed.ncbi.nlm.nih.gov/26752513/","abruf":"2026-10-12"},{"typ":"url","kurz":"Haufe: Schulmedizinklausel § 4 Abs. 6 MB/KK 94 ist wirksam (Kommentar)","oeffentlich":true,"url":"https://www.haufe.de/id/kommentar/schulmedizinklausel-4-abs-6-mbkk-94-ist-wirksam-HI947826.html","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Heissmann, N.; Weymayr, C. (2012): Die Homöopathie-Lüge, Teil 5","oeffentlich":false}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"527e3f184d202ef8"}},{"id":"qg-4","status":"entwurf","clusterId":"G","werkstueckRef":"G.1.3","stufe":2,"question":"Was ist an diesem Argument fehlerhaft?","options":["Der Schmerz sozialer Konflikte sagt nichts darüber, ob die Überzeugung stimmt: Auch Irrtümer und Ideologien kosten Freundschaften.","Wer Freunde verliert, hat die eigene Überzeugung nicht überzeugend genug vertreten und sollte sie deshalb zunächst überdenken.","Überzeugungen mit hohen sozialen Kosten sind grundsätzlich falsch, weil sich Wahrheit in der Regel ohne Streit durchsetzt.","Der Verlust der Freundschaften ist die Schuld der Bekannten, die sich einer berechtigten Erkenntnis aus Bequemlichkeit verschließen."],"correctIndex":0,"explanation":"Das Argument macht aus dem Leiden einen Beweis: Weil der Streit wehtut, soll die Überzeugung stimmen. Das ist ein Fehlschluss, denn die Kosten einer Überzeugung sagen nichts darüber, ob sie wahr ist. Auch Irrtümer und Ideologien können Freundschaften kosten, und richtige Einsichten kommen manchmal ganz ohne Streit aus. Entscheidend sind die Gründe für eine Überzeugung, nicht der Preis, den sie fordert. Eine hilfreiche Gegenfrage lautet: Woran würdest du merken, dass du dich irrst?","coreRule":"⚡ Leiden ist kein Beweis: Ein hoher Preis sagt nichts über Wahrheit. Welche Methode prüft die Überzeugung?","quote":"Die rote Pille verspricht die schmerzhafte Wahrheit. Dies rechtfertigt die sozialen Kosten (Konflikte mit Freunden), die mit dem Glauben verbunden sind.","quoteLabel":"Merksatz:","scenario":"Eine Freundin hat sich in den letzten Monaten einer „alternativen“ Sicht auf die Welt zugewandt und spricht von ihrem „Aufwachen“. Zu mehreren Bekannten hat sie den Kontakt abgebrochen, weil die sich ihrer „Erkenntnis“ verschließen. Dir gegenüber begründet sie das so: „Wer die Wahrheit sieht, muss Streit aushalten. Dass es wehtut, zeigt, dass ich auf dem richtigen Weg bin.“","beleg":"Werkstück G.1.3: „Die rote Pille nehmen“ (Red Pilling). Abschnitt „Kontext & Tiefe“ (Validierung des Leidens) sowie „Das Härten im Feuer“ (Aktivierungs-Frage). Keine Fußnote im Buchtext vorhanden.","kurz":"Dass etwas wehtut, sagt nichts darüber, ob es stimmt: Auch Irrtümer und Ideologien kosten Freundschaften. Der Fehler liegt darin, aus dem Preis einer Überzeugung ihre Wahrheit abzuleiten, statt ihre Gründe zu prüfen.","prueffrage":"Welchen Grund außer dem Schmerz nennt die Freundin dafür, dass ihre Erkenntnis stimmt?","rueckmeldung":[{"option":1,"text":"Ob jemand Freunde verliert, hängt von vielen Dingen ab und widerlegt eine Überzeugung so wenig, wie es sie bestätigt. Auch dieser Schluss macht den Preis zum Maßstab, nur in die Gegenrichtung."},{"option":2,"text":"Dass der Schmerz die Wahrheit nicht belegt, stimmt, aber die Umkehrung trägt ebenso wenig. Auch richtige Einsichten können Freundschaften kosten, und Streit sagt in keine Richtung etwas über Wahrheit."},{"option":3,"text":"Diese Schuldzuweisung übernimmt einfach die Sicht der Freundin und setzt voraus, dass ihre Erkenntnis berechtigt ist. Genau das ist aber die offene Frage, und dass andere sich verschließen, beantwortet sie nicht."}],"familie":"nach-weg-und-kriterium-fragen","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Körber, M.-L. (2025): The Infamous Afterlife of Popular Films: Metaphorical Production of Meaning in the Manosphere through The Matrix. Fandom | Cultures | Research 2(1), 18–31","oeffentlich":true,"doi":"10.25969/mediarep/23948","url":"https://journals.uni-marburg.de/fcr/article/download/8779/8508/21457","seite":"18","abruf":"2026-10-12"},{"typ":"url","kurz":"Lewandowsky, S.; Cook, J. (2020): The Conspiracy Theory Handbook","oeffentlich":true,"url":"https://climatecommunication.gmu.edu/wp-content/uploads/2023/09/ConspiracyTheoryHandbook.pdf","seite":"7","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"ce59eeab02b9d007"}},{"id":"qg-5","status":"entwurf","clusterId":"G","werkstueckRef":"G.1.4","stufe":4,"question":"Wann wird der Slogan „Mein Körper, meine Wahl“ vom legitimen Freiheitsrecht zu einem Kampfbegriff, der Diskussionen abwürgt?","options":["Wenn das Recht als grenzenlos gilt und die vorhersehbare Gefährdung anderer als belanglos abgetan wird.","Sobald sich jemand in einer Gesundheitsfrage auf ein Freiheitsrecht beruft, weil jede solche Berufung verdächtig ist.","Wenn jemand eine empfohlene Behandlung für sich ablehnt, weil jede Ablehnung die Gesundheitsversorgung belastet.","Wenn der Staat das Recht gesetzlich festschreibt, weil verrechtlichte Freiheit den Spielraum des Einzelnen verkleinert."],"correctIndex":0,"explanation":"Körperliche Selbstbestimmung schützt vor Zwang und ist ein Fundament freier Gesellschaften. Eine empfohlene Operation für sich abzulehnen ist legitim, denn die Folgen trägt vor allem die Person selbst. Problematisch wird es, wenn das Recht als Freiheit gedeutet wird, andere vorhersehbar zu gefährden, etwa durch Ansteckung. Dann stehen zwei Rechte gegeneinander: die Selbstbestimmung des Einen und die körperliche Unversehrtheit der Anderen. Ein Slogan, der diesen Konflikt für nicht existent erklärt, beendet die Diskussion, statt sie zu führen. Eine pauschale Skepsis gegenüber Freiheitsrechten oder gegenüber jeder Ablehnung einer Behandlung trifft den Kern nicht: Entscheidend ist, ob Dritte vorhersehbar betroffen sind und ob das ausgeblendet wird.","coreRule":"⚡ Stimm dem Recht zu und zeig den Konflikt: Zwei Rechte stehen gegeneinander.","quote":"Es ist die Verwechslung von „Freiheit von Zwang“ (legitim) mit „Freiheit, andere zu gefährden“ (ein systemisches Problem).","quoteLabel":"Merksatz:","scenario":"In einer Debatte über eine Impfempfehlung legt jemand Daten zu Ansteckung und Risikogruppen vor. Eine andere Person antwortet: „Das mag alles sein. Aber mein Körper, meine Wahl. Wie sich das auf andere auswirkt, spielt keine Rolle.“","beleg":"Werkstück G.1.4, Abschnitte „Der Kipppunkt“, „Red Flags“, „Das Adaptive Talent“ und „Das Anti-Denkmuster (Skript 1)“; keine Fußnoten","kurz":"Der Slogan wird zum Kampfbegriff, wenn das Recht als grenzenlos gilt und die absehbare Gefährdung anderer für belanglos erklärt wird. Dann stehen zwei Rechte gegeneinander, und der Satz tut so, als gäbe es diesen Konflikt nicht.","prueffrage":"Was antwortet die Person auf die vorgelegten Daten zu Ansteckung und Risikogruppen, und welche Gründe nennt sie dafür?","rueckmeldung":[{"option":1,"text":"Freiheitsrechte in Gesundheitsfragen wecken schnell Argwohn, doch Selbstbestimmung schützt vor Zwang und ist an sich legitim. Entscheidend ist nicht die Berufung auf das Recht, sondern ob Dritte vorhersehbar betroffen sind und das ausgeblendet wird."},{"option":2,"text":"Wer eine empfohlene Behandlung für sich ablehnt, handelt legitim, solange die Folgen vor allem ihn selbst treffen. Eine mögliche Belastung des Gesundheitswesens macht den Slogan noch nicht zum Kampfbegriff; der Kern liegt bei der Gefährdung anderer."},{"option":3,"text":"Gesetzlich festgeschrieben schützt das Recht den Einzelnen eher, als dass es ihn einengt. Zum Kampfbegriff wird der Slogan nicht durch seinen rechtlichen Status, sondern durch seinen Gebrauch: wenn er die Betroffenheit anderer für irrelevant erklärt."}],"familie":"berechtigten-kern-anerkennen","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Deutscher Ethikrat (2019): Pressemitteilung 06/2019 zur Stellungnahme „Impfen als Pflicht?“","oeffentlich":true,"url":"https://www.ethikrat.org/fileadmin/PDF-Dateien/Pressemitteilungen/pressemitteilung-06-2019.pdf","abruf":"2026-10-12"},{"typ":"url","kurz":"Grundgesetz Art. 2 (freie Entfaltung, soweit Rechte anderer nicht verletzt; Recht auf körperliche Unversehrtheit)","oeffentlich":true,"url":"https://www.gesetze-im-internet.de/gg/art_2.html","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"6ad8f056801a1960"}},{"id":"qg-6","status":"entwurf","clusterId":"G","werkstueckRef":"G.2.1","stufe":2,"question":"Welche Antwort erklärt am besten, warum sich eine Behauptung wie „Die Eliten steuern alles“ kaum widerlegen lässt?","options":["Die Eliten verfügen tatsächlich über Informationen, die der Öffentlichkeit aus Sicherheitsgründen vorenthalten bleiben und deshalb nicht überprüfbar sind.","Wer die Eliten sind, bleibt offen, deshalb lässt sich jede Entlastung als Beleg für eine noch tiefer verborgene Elite umdeuten.","Machtpositionen sind in der Gesellschaft ungleich verteilt, deshalb muss jede Behauptung über verborgene Macht im Kern zutreffen.","Kritiker nehmen solche Behauptungen oft nicht ernst genug, deshalb unterbleibt die Prüfung und die Behauptung bleibt unwidersprochen."],"correctIndex":1,"explanation":"Die Behauptung nennt nie genau, wer gemeint ist. Dadurch kann sie jeden Gegenbeweis auffangen: Wird ein Beschuldigter entlastet, war er eben „nur eine Marionette“. Eine Behauptung, die durch keine denkbare Beobachtung widerlegt werden kann, sagt in Wahrheit nichts Prüfbares mehr. Wirksam ist deshalb die Frage nach Spezifität: Wer genau gehört dazu? Welcher überprüfbare Beleg zeigt, dass sich diese Personen abgesprochen haben, um dieses konkrete Ziel zu erreichen? Vage Begriffe wie „die Eliten“ bedeuten niemanden und zugleich jeden und sind deshalb unangreifbar und beliebig einsetzbar.","coreRule":"⚡ Bestehe auf Spezifität: Wer genau, welcher Beleg, welches Ziel?","quote":"","quoteLabel":"","scenario":"In einer Diskussion sagt jemand: „Die Eliten steuern alles.“ Du weist nach, dass der Politiker, den er als Drahtzieher genannt hat, bei dem fraglichen Beschluss gar nicht mitgestimmt hat. Die Antwort kommt prompt: „Der war doch nur eine Marionette. Die wahren Eliten sitzen dahinter.“","kurz":"Weil die Behauptung offenlässt, wer gemeint ist, lässt sich jeder Gegenbeleg umdeuten: Ist einer entlastet, war er eben „nur eine Marionette“. Was durch keine denkbare Beobachtung widerlegt werden kann, sagt nichts Prüfbares mehr.","prueffrage":"Wen genau nennt dein Gegenüber als Drahtzieher, nachdem der Politiker entlastet ist?","rueckmeldung":[{"option":0,"text":"Dass manche Informationen geheim gehalten werden, kommt durchaus vor. Unwiderlegbar wird die Behauptung aber anders: Sie verschiebt die Gemeinten bei jedem Einwand weiter nach hinten, und das funktioniert auch ohne Geheimnisse."},{"option":2,"text":"Macht ist tatsächlich ungleich verteilt, aber daraus folgt nicht, dass eine bestimmte, nie genannte Gruppe alles steuert. Der Schluss „muss zutreffen“ ersetzt den Beleg durch Plausibilität und verschiebt die Beweislast auf die Kritiker."},{"option":3,"text":"Hier wird die Behauptung sehr wohl geprüft: Der Beleg gegen den genannten Politiker liegt vor. Sie überlebt trotzdem, weil sie sich jedem Einwand anpasst; das liegt an ihrer Bauart, nicht am Verhalten der Kritiker."}],"familie":"kritik-braucht-adresse","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Lewandowsky, S.; Cook, J. (2020): The Conspiracy Theory Handbook","oeffentlich":true,"url":"https://climatecommunication.gmu.edu/wp-content/uploads/2023/09/ConspiracyTheoryHandbook.pdf","seite":"7","abruf":"2026-10-12"},{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Karl Popper (überarb. 31.07.2026), Abschn. 2","oeffentlich":true,"url":"https://plato.stanford.edu/entries/popper/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"fb58745f8cc45d70"}},{"id":"qg-7","status":"entwurf","clusterId":"G","werkstueckRef":"G.2.2","stufe":2,"question":"In einer Diskussion sagt jemand: „Dass die Zeitung diesen Bericht gebracht hat, beweist nur wieder, dass die Lügenpresse lügt. Auf die glaubt man nichts mehr.“ Du fragst, welcher Artikel denn welche Falschaussage enthalten habe. Die Antwort lautet: „Das ist ja gerade das Problem: Die sagen alle dasselbe.“ Was ist an dieser Argumentation das Kernproblem?","options":["Jede Gegeninformation aus professionellen Quellen gilt von vornherein als verdächtig, sodass nichts mehr das eigene Weltbild erschüttern kann.","Die Person hat einzelne Fehler der Zeitung übertrieben dargestellt, obwohl die Zeitung ihre Fehler in der Regel selbst schnell korrigiert.","Die Person überschätzt die Vielfalt der Medien, obwohl die großen Redaktionen in der Praxis tatsächlich sehr ähnlich berichten.","Die Person vertraut zu wenigen Quellen, obwohl sie ihre Informationen jederzeit aus noch mehr verschiedenen Zeitungen beziehen könnte."],"correctIndex":0,"explanation":"Der Pauschalvorwurf nennt keinen konkreten Fehler, sondern erklärt jede unbequeme Information im Voraus für unglaubwürdig. So lässt sich jede Gegeninformation als weiterer „Beweis“ umdeuten, und nichts kann das eigene Weltbild mehr erschüttern: Es ist nicht geprüft, sondern abgeschottet. Auch „Die sagen alle dasselbe“ ist nur ein Etikett, das „die Medien“ zu einer einzigen Stimme macht, obwohl Zeitungen mit gegensätzlicher Ausrichtung einander oft widersprechen; wer das behauptet, müsste es an einem konkreten Fall belegen. Zudem ist „Lügenpresse“ ein historisch belasteter Begriff, der spätestens im Ersten Weltkrieg zum nationalistischen Kampfbegriff wurde und den die NS-Propaganda antisemitisch zuspitzte. Wer ihn benutzt, knüpft an diese Vorgeschichte an, ob bewusst oder nicht.","coreRule":"⚡ Wer jede Gegeninformation vorab für unglaubwürdig erklärt, hat nichts geprüft. Frag nach dem konkreten Artikel: Welche überprüfbare Falschaussage, wann, und wurde sie korrigiert?","quote":"Lasst uns über Beweise reden, nicht über pauschale Etiketten.","quoteLabel":"Merksatz:","scenario":"","beleg":"Werkstück G.2.2, Abschnitte 2 (Versiegelung der Echokammer, Strohmann, historische Anknüpfung), 3 (Ad Hominem, Bestätigungsfehler), 4 (Aktivierungs-Frage); Fußnote gl-g-1","kurz":"Wer jede unbequeme Information im Voraus für unglaubwürdig erklärt, kann durch nichts mehr korrigiert werden. Statt eines konkreten Fehlers kommt hier nur das Etikett „Die sagen alle dasselbe“, und so bleibt das Weltbild gegen jede Widerlegung abgeschottet.","prueffrage":"Welchen Artikel und welche Falschaussage nennt die Person, nachdem du ausdrücklich danach gefragt hast?","rueckmeldung":[{"option":1,"text":"Im Gespräch kommt kein einzelner Fehler vor, auch kein übertriebener: Die Person nennt trotz Nachfrage keinen konkreten Fall. Wie zuverlässig Zeitungen ihre Fehler korrigieren, trifft den Kern deshalb nicht."},{"option":2,"text":"Hier ist es umgekehrt: Die Person unterschätzt die Vielfalt und macht „die Medien“ zu einer einzigen Stimme, obwohl Zeitungen mit gegensätzlicher Ausrichtung einander oft widersprechen. Dass alle gleich berichten, müsste sie belegen."},{"option":3,"text":"Mehr Zeitungen zu lesen, würde hier kaum etwas ändern, denn jede weitere Quelle wäre ebenfalls schon im Voraus als „gelogen“ abgestempelt. Das Problem liegt nicht in der Zahl der Quellen, sondern darin, dass nichts die Sicht mehr erschüttern kann."}],"familie":"kritik-braucht-adresse","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Lewandowsky, S.; Cook, J. (2020): The Conspiracy Theory Handbook","oeffentlich":true,"url":"https://climatecommunication.gmu.edu/wp-content/uploads/2023/09/ConspiracyTheoryHandbook.pdf","seite":"7","abruf":"2026-10-12"},{"typ":"url","kurz":"Sprachkritische Aktion Unwort des Jahres (13.01.2015): Pressemitteilung „Unwort des Jahres 2014: Lügenpresse“","oeffentlich":true,"url":"https://www.unwortdesjahres.net/wp-content/uploads/2021/06/pressemitteilung_unwort2014.pdf","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Schmitz-Berning, C. (2007): Vokabular des Nationalsozialismus. 2. Aufl. Berlin, New York: de Gruyter, s. v. „Journaille“","oeffentlich":false,"seite":"327"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"201d461391f2475a"}},{"id":"qg-8","status":"entwurf","clusterId":"G","werkstueckRef":"G.2.4","stufe":4,"question":"Welcher Einwand trifft den Kern des Problems am besten?","options":["Die Kritik kommt von jemandem ohne medizinische Ausbildung, deshalb lässt sich die Aussage nicht ernst nehmen und muss nicht widerlegt werden.","Der Vorwurf ist in dieser Schärfe zu laut vorgetragen, ein Mittelweg zwischen Kritik und Lob wäre angemessener und würde mehr Zuhörer erreichen.","Viele konkurrierende Unternehmen werden zu einem Akteur mit gemeinsamem Plan erklärt, und Studien werden pauschal verworfen, statt ihre Methodik zu prüfen.","Der Vorwurf ist falsch, weil Unternehmen mit Medikamenten Gewinne machen dürfen und deshalb keine Kritik verdienen, auch nicht an einzelnen Studien."],"correctIndex":2,"explanation":"Kritik an der Pharmaindustrie kann berechtigt sein, denn es gibt nachgewiesenes Fehlverhalten einzelner Unternehmen, etwa bei Preisgestaltung oder Marketing. Der Fehler liegt woanders: Viele konkurrierende Firmen werden pauschal zu einem einzigen böswilligen Akteur mit gemeinsamem Plan erklärt. Zudem wird jede industriefinanzierte Studie allein wegen ihrer Herkunft verworfen, ohne Methodik und Ergebnisse zu prüfen; die Finanzierung ist ein Grund, genauer hinzusehen, ersetzt aber nicht die Prüfung. Wer so argumentiert, kann aus Misstrauen am Ende auch lebensrettende Behandlungen ablehnen. Ein gutes Gegenargument fragt nach der Adresse der Kritik: Welches Unternehmen, welche Praxis, welcher Beleg?","coreRule":"⚡ Kritik braucht eine Adresse: Welcher Konzern, welche Praxis, welcher Beleg?","quote":"","quoteLabel":"","scenario":"In einer Diskussion über Arzneimittelpreise sagt jemand: „Big Pharma will uns alle krank halten, um uns ihre Gifte zu verkaufen. Jede Studie, die von der Industrie bezahlt wurde, kannst du vergessen.“","kurz":"Die Aussage macht aus vielen konkurrierenden Firmen einen einzigen Akteur mit gemeinsamem Plan und verwirft Studien allein wegen ihrer Herkunft, statt Methodik und Belege zu prüfen. Berechtigte Kritik an einzelnen Praktiken bleibt möglich, muss aber sagen, wen und was sie meint.","prueffrage":"Welche Firma, welche Praxis und welcher Beleg sind in der Aussage konkret gemeint?","rueckmeldung":[{"option":0,"text":"Die Ausbildung des Sprechers zu prüfen ist bequem, entscheidet aber nicht, ob die Aussage stimmt; von fehlender Ausbildung ist zudem nirgends die Rede. Kritik an einzelnen Praktiken kann berechtigt sein, der Fehler liegt in der Pauschalisierung."},{"option":1,"text":"Dass der Ton scharf ist, stimmt, und Mäßigung kann Zuhörer gewinnen. Das betrifft aber die Wirkung, nicht den Denkfehler. Die Wahrheit liegt auch nicht automatisch in der Mitte: Eine leise vorgetragene Pauschalisierung bliebe eine Pauschalisierung."},{"option":3,"text":"Gewinne zu machen ist erlaubt, doch daraus folgt nicht, dass Kritik unberechtigt wäre. Es gibt nachgewiesenes Fehlverhalten einzelner Unternehmen, etwa bei Preisen oder Marketing. Nur die pauschale Verallgemeinerung trägt nicht."}],"familie":"kritik-braucht-adresse","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Lundh, A. u. a. (2017): Industry sponsorship and research outcome. Cochrane Database of Systematic Reviews, MR000033","oeffentlich":true,"doi":"10.1002/14651858.MR000033.pub3","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8132492/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Krumholz, H. M.; Ross, J. S.; Presler, A. H.; Egilman, D. S. (2007): What have we learnt from Vioxx? BMJ 334, 120–123","oeffentlich":true,"doi":"10.1136/bmj.39024.487720.68","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC1779871/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"37e8d8cc68f55eed"}},{"id":"qg-9","status":"entwurf","clusterId":"G","werkstueckRef":"G.3.1","stufe":1,"question":"Eine Saftkur wird mit dem Versprechen beworben, „Schlacken“ und „Toxine“ auszuleiten. Welche Rückfrage prüft dieses Versprechen am besten?","options":["Wie viele Kundinnen und Kunden haben die Kur gekauft, und wie zufrieden waren sie danach?","Welcher einzelne Stoff soll entfernt werden, und wie wurde seine Menge vor und nach der Kur gemessen?","Welche Zutaten enthält der Saft, und stammen die Früchte aus kontrolliertem Anbau?","Wie lange dauert die Kur, und lässt sie sich mit einem normalen Arbeitsalltag vereinbaren?"],"correctIndex":1,"explanation":"Ein Versprechen wie „Ausleiten von Toxinen“ lässt sich nur prüfen, wenn klar ist, was ausgeleitet werden soll. Deshalb hilft die Frage nach einem benannten Stoff und nach einer Messung vor und nach der Kur: Ohne diese Angaben gibt es nichts, was sich überprüfen oder widerlegen ließe. Dazu kommt: Der Körper hat mit Leber und Nieren eigene Organe, die schädliche Substanzen abbauen und ausscheiden. Ein Angebot müsste also erklären, warum diese Organe bei einem bestimmten Stoff versagen. Die anderen Fragen betreffen Zufriedenheit, Zutaten oder Praktikabilität und sagen nichts darüber, ob die versprochene Wirkung eintritt. Eine Übersichtsarbeit von Klein und Kiat (2015) fand keine randomisierten kontrollierten Studien zu kommerziellen Detox-Diäten beim Menschen und sah keine überzeugenden Belege für Detox-Diäten zur Giftausleitung.","coreRule":"⚡ Wer „Gift“ sagt, muss den Stoff benennen und die Messung zeigen.","quote":"Nenne mir ein einziges. Wie heißt es chemisch? Wie hat man seine Konzentration in deinem Körper vor und nach der Kur gemessen?","quoteLabel":"Prüffrage:","scenario":"In der Werbung heißt es, die Kur reinige den Körper von „Schlacken“ und „Toxinen“, die sich durch Umwelt und Ernährung angesammelt hätten. Welche Stoffe das genau sind, steht dort nicht.","beleg":"Werkstück G.3.1, Fußnote gl-g-detox: Klein & Kiat (2015), J Hum Nutr Diet 28(6), 675–686; Rückfrage des Biochemikers aus der Einleitung des Werkstücks.","kurz":"Ein Versprechen ist nur prüfbar, wenn klar ist, was genau ausgeleitet werden soll. „Schlacken“ und „Toxine“ benennen nichts Messbares. Erst ein benannter Stoff mit Messung vor und nach der Kur ließe sich bestätigen oder widerlegen.","prueffrage":"Angenommen, die Kur leitet gar nichts aus: Bei welcher Auskunft des Anbieters würdest du das bemerken?","rueckmeldung":[{"option":0,"text":"Kaufzahlen und Zufriedenheit zeigen, wie gut sich die Kur verkauft und wie sich Kundinnen und Kunden danach fühlen. Ob dabei tatsächlich etwas ausgeleitet wurde, belegen sie nicht, denn Wohlbefinden kann viele Ursachen haben."},{"option":2,"text":"Die Zutaten und die Herkunft der Früchte sagen etwas über die Qualität des Safts. Ein guter Saft kann gesund sein, ohne irgendetwas „auszuleiten“. Das eigentliche Versprechen bleibt damit ungeprüft."},{"option":3,"text":"Dauer und Alltagstauglichkeit helfen bei der Entscheidung, ob man die Kur durchhalten könnte. Ob sie das Versprochene bewirkt, sagen sie nicht, denn dafür müsste erst feststehen, was ausgeleitet werden soll."}],"familie":"begriff-messbar-machen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Klein, A. V.; Kiat, H. (2015): Detox diets for toxin elimination and weight management: a critical review of the evidence. Journal of Human Nutrition and Dietetics 28(6), 675–686","oeffentlich":false,"doi":"10.1111/jhn.12286"},{"typ":"url","kurz":"Verbraucherzentrale: Detox – überflüssig oder doch gesünder durch Entgiftung? (Stand 09.01.2026)","oeffentlich":true,"url":"https://www.verbraucherzentrale.de/wissen/lebensmittel/nahrungsergaenzungsmittel/detox-gesuender-durch-entgiftung-25381","abruf":"2026-10-12"},{"typ":"url","kurz":"NCCIH (NIH): Detoxes and Cleanses: What You Need To Know (Stand März 2025)","oeffentlich":true,"url":"https://www.nccih.nih.gov/health/detoxes-and-cleanses-what-you-need-to-know","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"7384cd66acf21e28"}},{"id":"qg-10","status":"entwurf","clusterId":"G","werkstueckRef":"G.3.2","stufe":3,"question":"Eine Homöopathin sagt: „Mein Mittel ist so stark verdünnt, dass kein Wirkstoffmolekül mehr enthalten ist. Aber das Wasser behält die ‚Information‘ der Ursubstanz. Und beim Verschütteln werden alle früheren Informationen des Wassers gelöscht, nur diese eine bleibt.“ Welche Rückfrage setzt am schwächsten Punkt an und nutzt die Beweislast?","options":["Durch welchen Versuch ist gezeigt, dass das Verschütteln alle früheren Informationen löscht und genau die eine neue speichert?","Wie oft muss man schütteln, damit die Information des Mittels im Wasser dauerhaft erhalten bleibt?","Welche Hersteller bieten diese Mittel an, und sind ihre Präparate von einer Behörde zugelassen?","Warum vertrauen so viele Patienten auf diese Mittel, wenn das Verfahren der Chemie widerspricht?"],"correctIndex":0,"explanation":"Die Aussage, Schütteln lösche alle alten Informationen und speichere nur die eine neue, ist eine zusätzliche Hilfsannahme, die gerade den offensichtlichen Einwand abwehren soll: Wasser hat im Lauf seiner Geschichte unzählige Stoffe berührt, warum sollte es sich ausgerechnet an die letzte Ursubstanz erinnern? Die Beweislast liegt bei dem, der die Annahme einführt. Er muss zeigen, dass genau dieser Vorgang diese Eigenschaft hat, etwa in einem verblindeten Versuch. Die anderen Fragen setzen die Annahme voraus (wie oft schütteln?), lenken auf Nebenschauplätze (Hersteller, Zulassung) oder fragen nach Psychologie statt nach dem Beleg (warum vertrauen Patienten?). Dass solche Behauptungen oft nicht standhalten, zeigt der Fall Benveniste: Sein 1988 gemeldeter Effekt hochverdünnter Antikörper verschwand bei verblindeter Auswertung.","coreRule":"⚡ Wer eine Hilfsannahme einführt, schuldet den Test für genau diese Annahme.","quote":"Wie nützlich wäre dieser USB-Stick?","quoteLabel":"Prüffrage:","scenario":"","beleg":"Werkstück G.3.2, Abschnitt „Die Schmiede-Übung“ sowie Fußnote gl-g-4: Davenas u. a. (1988), Nature 333, S. 816–818; Maddox/Randi/Stewart (1988), Nature 334, S. 287–290.","kurz":"Wer behauptet, Schütteln lösche alles Alte und speichere genau die eine Information, muss das belegen, etwa in einem verblindeten Versuch. Diese Zusatzannahme wehrt den Einwand ab, dass Wasser unzählige Stoffe berührt hat; sie ist der schwächste Punkt.","prueffrage":"Für welche Teile ihrer Behauptung nennt die Homöopathin einen Beleg, und welche setzt sie einfach voraus?","rueckmeldung":[{"option":1,"text":"Die Frage nach der Zahl der Schüttelvorgänge wirkt praxisnah, übernimmt aber die ganze Behauptung, dass Wasser Information speichert und Schütteln sie erhält. Damit ist die eigentliche Lücke schon als geschlossen vorausgesetzt."},{"option":2,"text":"Herstellung und Zulassung lassen sich leicht nachschlagen und klingen nach Prüfung. Sie sagen aber nichts darüber, ob das Wasser tatsächlich Information speichert und Schütteln alles andere löscht. Die Behauptung selbst bleibt unberührt."},{"option":3,"text":"Warum Menschen auf solche Mittel vertrauen, ist eine berechtigte Frage, etwa mit Blick auf Erwartung und Zuwendung. Sie klärt aber nicht, ob die behauptete Wirkweise stimmt, und verlangt keinen Beleg für die Zusatzannahme."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Ball, P. (2004): The memory of water. Nature News, 08.10.2004","oeffentlich":true,"url":"https://www.nature.com/news/2004/041004/full/news041004-19.html","abruf":"2026-10-12"},{"typ":"doi","kurz":"Maddox, J.; Randi, J.; Stewart, W. W. (1988): „High-dilution“ experiments a delusion. Nature 334, 287–290","oeffentlich":false,"doi":"10.1038/334287a0"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"8ef5b3351af85c19"}},{"id":"qg-11","status":"entwurf","clusterId":"G","werkstueckRef":"G.3.3","stufe":2,"question":"Welche Rückfrage prüft diese Behauptung am besten?","options":["Wie viele Menschen sind nach einer Infektion tatsächlich geschützt, und wie hoch war dabei jeweils die Quote der Todesfälle und schweren Verläufe?","Wie lange gibt es das menschliche Immunsystem schon, und lässt sich daraus ableiten, was es heute leistet?","Wie viele Menschen in deinem Umfeld haben eine Infektion ohne Impfung gut überstanden und konnten danach weiterarbeiten?","Wie viele Menschen hat dieses Argument schon überzeugt, und welche Personen mit Erfahrung teilen diese Haltung?"],"correctIndex":0,"explanation":"Die Behauptung vergleicht zwei Wege zum selben Ziel, nennt aber nur das Ziel: den Schutz. Die Frage nach Schutzquote und Sterblichkeit holt den Preis des Weges zurück auf den Tisch. Eine überstandene Krankheit hinterlässt zwar oft einen robusten Schutz, doch der Weg dorthin kann tödlich sein oder bleibende Schäden hinterlassen. Der Hinweis auf „Millionen Jahre“ wirbt mit dem Wort „natürlich“, statt etwas über Nutzen und Risiko zu zeigen. Außerdem ist „natürliche Immunität“ nicht bei jeder Krankheit besser: Bei Tetanus hinterlässt die Infektion keine Immunität, die Impfung schon. Bei HPV ist die Impfantwort stärker und verlässlicher als nach einer Infektion. Wer prüfen will, ob ein Weg der bessere ist, vergleicht beide samt ihren Risiken und nicht nur das Ergebnis.","coreRule":"⚡ Vergleiche die Wege samt ihren Risiken, nicht nur das Ergebnis.","quote":"Wir vergleichen hier nicht zwei gleichwertige Ergebnisse.","quoteLabel":"Merksatz:","scenario":"In einer Diskussion über Impfungen sagt jemand: „Ich setze auf natürliche Immunität, die ist seit Millionen Jahren erprobt. Ich brauche keine Impfung.“","beleg":"Werkstück G.3.3, Abschnitt „Das Härten im Feuer“, Aktivierungs-Frage; Abschnitte „Kernidee“ und „Kontext & Tiefe“; Fußnoten gl-g-2 (Tetanus, CDC Pink Book), gl-g-3 (HPV, Ghilencea u. a. 2026) und gl-g-reinfektion (COVID-19 Forecasting Team 2023, The Lancet)","kurz":"Die Behauptung nennt nur das Ziel, den Schutz, und lässt den Preis des Weges weg. Wer nach Schutzquote, Todesfällen und schweren Verläufen fragt, holt ihn zurück. „Natürlich“ und „seit Millionen Jahren“ sagen darüber nichts.","prueffrage":"Welche zwei Wege zum Schutz stehen sich hier gegenüber, und was erfährst du über jeden der beiden?","rueckmeldung":[{"option":1,"text":"Das Immunsystem ist tatsächlich uralt. Wie alt ein System ist, sagt aber nicht, wie gut oder riskant ein Weg zum Schutz heute ist, und mit dem Wort „natürlich“ wird nur geworben."},{"option":2,"text":"Viele überstehen eine Infektion tatsächlich gut. Wer nur die Überlebenden im eigenen Umfeld zählt, sieht aber weder die Todesfälle noch die bleibenden Schäden und kennt keine Quote."},{"option":3,"text":"Wie viele ein Argument überzeugt oder wer es teilt, sagt etwas über seine Verbreitung, nicht über seinen Gehalt. Schutz, Sterblichkeit und Risiko beider Wege bleiben dabei ungeprüft."}],"familie":"nutzen-und-risiko-abwaegen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"CDC: Epidemiology and Prevention of Vaccine-Preventable Diseases („Pink Book“), Kap. 21 Tetanus","oeffentlich":true,"url":"https://www.cdc.gov/pinkbook/hcp/table-of-contents/chapter-21-tetanus.html","abruf":"2026-10-12"},{"typ":"doi","kurz":"Ghilencea, B. u. a. (2026): Natural Versus Vaccine-Induced Immunity Against HPV: A Comparative Review of Antibody Response and Cancer Prevention. Antibodies 15(4), 61","oeffentlich":true,"doi":"10.3390/antib15040061","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC13398047/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"8363d00e92b2195d"}},{"id":"qh-1","status":"entwurf","clusterId":"H","werkstueckRef":"H.0.1","stufe":3,"question":"Eine Forscherin behauptet: Wer kurz an den eigenen Tod erinnert wird, urteilt über Normbrecher deutlich härter. Als Beleg nennt sie ein Experiment mit 22 Richtern: Die Kontrollgruppe setzte im Schnitt 50 Dollar Kaution fest, die Gruppe, die zuvor Fragen zur eigenen Sterblichkeit beantwortet hatte, 455 Dollar. Wie sicher darfst du aus diesem Experiment allein auf den behaupteten Zusammenhang schließen?","options":["Nur vorläufig: Ein kleines Einzelexperiment ist ein Hinweis, aber noch kein Beleg.","Ziemlich sicher: Ein Unterschied von 50 zu 455 Dollar ist ein Hinweis, der Zufall ausschließt.","Gar nicht: Richter sind an Strafen gewöhnt, daher sagt das Ergebnis nichts über andere aus.","Sicher genug: Eine Erklärung der Forscher selbst ist ein Beleg, der den Zusammenhang stützt."],"correctIndex":0,"explanation":"Der Befund stammt aus einem einzelnen, kleinen Experiment mit nur 22 Richtern. Die Forscher deuten ihn so, dass die Erinnerung an den Tod ein Bedürfnis weckt, die eigene Weltanschauung zu verteidigen, und Normbrecher deshalb als Bedrohung wirken. Das ist aber eine Deutung und kein Beweis. Mehrere große Replikationsversuche zur Todeserinnerung sind seither gescheitert. Many Labs 4 wiederholte dabei allerdings nicht das Richter-Experiment, sondern einen anderen klassischen Befund derselben Richtung. Das Richter-Experiment ist deshalb die Gründungsgeschichte der Theorie, kein gesicherter Befund. Die vernünftige Haltung: als Hinweis ernst nehmen, aber nicht zur Schlagzeile machen. Der Schluss auf „gar nichts“ wäre ebenso übertrieben, denn ein einzelnes Experiment ist schwache, aber nicht wertlose Evidenz.","coreRule":"⚡ Je kleiner die Stichprobe und je spektakulärer das Ergebnis, desto mehr braucht es unabhängige Wiederholung, bevor man ihm traut.","quote":"","quoteLabel":"","scenario":"Ein Artikel greift das Ergebnis auf und titelt: „Todesangst macht Menschen gnadenlos.“ Du sollst einschätzen, wie viel die Datenlage hergibt.","kurz":"Ein einzelnes Experiment mit nur 22 Richtern ist ein Hinweis, aber noch kein Beleg. Der Fehler wäre, aus einem auffälligen Unterschied und einer plausiblen Deutung gleich eine Schlagzeile zu machen, zumal Replikationen zur Todeserinnerung gescheitert sind.","prueffrage":"Wie viele Richter saßen in jeder Gruppe, und wie stark könnte ein einzelner Richter mit einer sehr hohen Kaution den Durchschnitt verschieben?","rueckmeldung":[{"option":1,"text":"Ein Unterschied von 50 zu 455 Dollar wirkt gewaltig. Bei nur 22 Richtern kann aber auch der Zufall große Abstände erzeugen, und große Wiederholungsversuche zur Todeserinnerung sind gescheitert."},{"option":2,"text":"Dass Richter eine besondere Berufsgruppe sind, schränkt die Verallgemeinerung tatsächlich ein. „Gar nicht“ geht aber zu weit: Ein einzelnes kleines Experiment ist schwache, aber nicht wertlose Evidenz."},{"option":3,"text":"Die Deutung der Forscher macht den Befund verständlicher, und eine plausible Erklärung wirkt schnell wie Bestätigung. Sie bleibt aber eine Deutung und liefert keine neuen Daten, die den Zusammenhang stützen würden."}],"familie":"wiederholung-abwarten","fertigkeit":"F1","quellen":[{"typ":"literatur","kurz":"Rosenblatt, Greenberg, Solomon, Pyszczynski & Lyon (1989): Evidence for terror management theory I. Journal of Personality and Social Psychology 57(4), 681–690","oeffentlich":false},{"typ":"doi","kurz":"Klein, R. A. u. a. (2022): Many Labs 4: Failure to Replicate Mortality Salience Effect With and Without Original Author Involvement. Collabra: Psychology 8(1), 35271","oeffentlich":true,"doi":"10.1525/collabra.35271","abruf":"2026-10-12"},{"typ":"doi","kurz":"Treger, Benau & Timko (2023): Not so terrifying after all? A set of failed replications of the mortality salience effects of Terror Management Theory. PLOS ONE 18(5), e0285267","oeffentlich":true,"doi":"10.1371/journal.pone.0285267","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"8de5afcc84586412"}},{"id":"qh-2","status":"entwurf","clusterId":"H","werkstueckRef":"H.1.1","stufe":2,"question":"Was ist an Toms Reaktion das eigentliche Denkproblem?","options":["Tom prüft Lenas Einwand nüchtern als Hypothese und kommt zu dem Schluss, dass sie sich geirrt hat.","Tom zweifelt grundsätzlich an jeder Zahl und kann deshalb keine Annahme mehr treffen.","Tom bleibt bei seiner Methode, weil er sie nach festen Regeln gewählt hat, und bleibt offen für Korrekturen.","Tom hält Kritik an seiner Annahme für einen Angriff auf sich selbst und verteidigt sich deshalb."],"correctIndex":3,"explanation":"Lenas Einwand betrifft eine Annahme in der Rechnung, Tom hört darin ein Urteil über sich als Person. Wer seinen Selbstwert an eine Idee hängt, erlebt jede Kritik daran als Angriff und verteidigt dann die Identität statt die Wahrheit. Damit wird auch die Prüfung unmöglich, ob die Annahme wirklich fehlerhaft ist: Man kann eine Hypothese nur ernsthaft prüfen und notfalls fallen lassen, wenn ihr Scheitern nicht den eigenen Wert zerstört. Hilfreich ist die Unterscheidung: Eine Idee ist etwas, das man hat, nicht etwas, das man ist. Dann ist ein gefundener Fehler eine nützliche Information, kein persönliches Versagen.","coreRule":"⚡ Trenne dein Selbstwertgefühl von deiner Hypothese: Wer Kritik an der Idee als Angriff auf die Person erlebt, kann sie nicht mehr prüfen.","quote":"","quoteLabel":"","scenario":"Lena zu ihrem Kollegen Tom: „Deine Berechnung hat einen Fehler in der Annahme zum Wachstum.“ Tom wird laut: „Du hast es schon immer auf mich abgesehen! Ich lasse mir von dir nicht sagen, dass ich nichts kann.“","kurz":"Lena kritisiert eine Annahme, Tom hört ein Urteil über sich. Wer seinen Wert an eine Idee knüpft, verteidigt dann sich statt die Sache, und ob die Annahme stimmt, wird nicht mehr geprüft.","prueffrage":"Was erfährt man aus Toms Antwort darüber, ob die Annahme zum Wachstum stimmt?","rueckmeldung":[{"option":0,"text":"Nüchternes Prüfen wäre der passende Umgang mit einem Einwand. Tom tut aber das Gegenteil: Er wird laut und wehrt ab, statt zu prüfen, und ein Ergebnis einer Prüfung nennt er nicht."},{"option":1,"text":"Wer an jeder Zahl zweifelt, könnte tatsächlich keine Annahme mehr treffen. Tom zweifelt aber nicht an Zahlen, er verteidigt sich gegen einen vermeintlichen Angriff, und das ist ein anderes Problem als übertriebene Skepsis."},{"option":2,"text":"An einer begründeten Methode festzuhalten, ist in Ordnung, solange man für Korrekturen offen bleibt. Tom nennt aber keine Regeln, er reagiert persönlich und verschließt sich dem Einwand."}],"familie":"selbstrechtfertigung-erkennen","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Hayes, Levin, Plumb-Vilardaga, Villatte & Pistorello (2013): Acceptance and Commitment Therapy and Contextual Behavioral Science. Behavior Therapy 44(2), 180–198 (PMC-Fassung)","oeffentlich":true,"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3635495/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"ec68dec68009bd34"}},{"id":"qh-3","status":"entwurf","clusterId":"H","werkstueckRef":"H.1.6","stufe":3,"question":"Wie reagierst du in dieser Situation am hilfreichsten?","options":["Du teilst ihre Angst so stark wie möglich, damit sie spürt, dass du auf ihrer Seite stehst, und überlegst erst danach, wie du helfen kannst.","Du verstehst, welche Angst sie antreibt, nimmst ihr Gefühl ernst, bleibst selbst ruhig und bietest ihr damit einen Anker an, um ihr zu helfen.","Du analysierst ihre Argumentationskette Schritt für Schritt und hältst dich von ihren Gefühlen fern, damit du neutral bleibst und sie ihre Logik selbst prüft.","Du übernimmst ihre Sicht auf das Wasser vollständig, damit die Anspannung zwischen euch verschwindet und sie sich dadurch verstanden fühlt."],"correctIndex":1,"explanation":"Wer die Panik des anderen voll mitfühlt, schwingt mit ihr mit und wird leicht selbst handlungsunfähig; bei Ärzten, Pflegenden und Angehörigen gilt dieser „empathische Stress“ als Risikofaktor für Erschöpfung und Burnout. Wer dagegen nur kühl analysiert, gibt dem Gegenüber leicht das Gefühl, unter dem Mikroskop zu liegen, und das Gespräch bricht ab. Tragfähig ist die Kombination aus Verstehen und Fürsorge: Du erkennst, warum die Person so denkt und fühlt, nimmst ihre Angst ernst und bleibst selbst ruhig, und so kannst du ihr einen stabilen Anker bieten. Die Trainingsstudie von Klimecki, Singer u. a. (2014) stützt das: Empathie-Training verstärkte Aktivität in Arealen für Schmerz und negativen Affekt, während Mitgefühls-Training die Aktivierung in Areale des Belohnungs- und Zugehörigkeitssystems verschob. Zustimmen, nur damit das unangenehme Gefühl endet, hilft weder ihr noch dir.","coreRule":"⚡ Fühle FÜR die Person, nicht MIT ihrer Panik.","quote":"Man ertrinkt mit dem Ertrinkenden, anstatt ihm den Rettungsring zuzuwerfen.","quoteLabel":"Merksatz:","scenario":"Deine Tante ruft dich panisch an: Sie ist überzeugt, dass „die da oben“ das Trinkwasser vergiften, und redet sich immer weiter in Angst hinein. Du merkst, wie ihre Panik auf dich überspringt. Du willst ihr helfen, ohne dich dabei selbst auszulaugen und ohne sie zu verlieren.","beleg":"Werkstück H.1.6, Fußnote gl-h-empathie (Singer/Klimecki 2014; Klimecki et al. 2014)","kurz":"Hilfreich ist, zu verstehen, was ihre Angst antreibt, das Gefühl ernst zu nehmen und selbst ruhig zu bleiben. Wer die Panik voll mitfühlt, wird leicht selbst handlungsunfähig; wer nur kühl analysiert, verliert leicht den Draht zu ihr.","prueffrage":"Was macht ihre Panik gerade mit dir, und woran würde deine Tante merken, dass du ihr wirklich zuhörst?","rueckmeldung":[{"option":0,"text":"Dass du auf ihrer Seite stehst, ist wichtig, aber dafür musst du ihre Angst nicht maximal teilen. Wer voll mitschwingt, wird leicht selbst handlungsunfähig und kann ihr dann keinen Halt mehr bieten."},{"option":2,"text":"Ruhe zu bewahren und Gedanken zu ordnen kann sinnvoll sein. Wer ihre Angst aber ganz ausklammert, gibt ihr leicht das Gefühl, unter dem Mikroskop zu liegen, und das Gespräch kann abbrechen, bevor ihre Sorge überhaupt Raum hatte."},{"option":3,"text":"Der Wunsch nach Entspannung zwischen euch ist verständlich. Wer ihre Sicht aber ganz übernimmt, stimmt nur zu, damit das unangenehme Gefühl endet. Das hilft weder ihr noch dir, und einen Anker bietest du so nicht."}],"familie":"gefuehl-zuerst-aufgreifen","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Klimecki, Leiberg, Ricard & Singer (2014): Differential Pattern of Functional Brain Plasticity After Compassion and Empathy Training. Social Cognitive and Affective Neuroscience 9(6)","oeffentlich":true,"doi":"10.1093/scan/nst060","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4040103/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Singer & Klimecki (2014): Empathy and Compassion. Current Biology 24(18), R875–R878 (Verlagsseite hier nicht geöffnet; Register b2a0fd0f299 am Volltext bestätigt)","oeffentlich":false,"doi":"10.1016/j.cub.2014.06.054"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"5c63c6556049ec4f"}},{"id":"qh-4","status":"entwurf","clusterId":"H","werkstueckRef":"H.2.2","stufe":2,"question":"Dein Kollege sagt: „Ich bin zu 95 % sicher, dass Heilkristalle Krankheiten heilen. Meine Kopfschmerzen sind nach einem Rosenquarz verschwunden.“ Du willst ihn nicht überrumpeln, sondern ihn dazu bringen, selbst zu prüfen, wie verlässlich sein Weg zu dieser Sicherheit ist. Welche Frage hilft dabei am meisten?","options":["Wie könntest du prüfen, ob es der Stein war, und wie verlässlich ist dieser Weg?","Warum glaubst du eigentlich so etwas, und was hast du erlebt, dass du so leichtgläubig geworden bist?","Welche Studie hast du gelesen, die das bestätigt, und wie erklärst du dir, dass andere Studien keine Wirkung finden?","Weißt du, dass fast alle Fachleute Heilkristalle ablehnen, und warum hältst du dann trotzdem daran fest?"],"correctIndex":0,"explanation":"Wer eine Überzeugung direkt angreift, löst meist eine defensive Reaktion aus, und das Gespräch ist beendet. Wirksamer ist es, das Verfahren zu untersuchen, das zur Überzeugung geführt hat. Hier ist es die persönliche Erfahrung: Die Kopfschmerzen sind nach dem Rosenquarz verschwunden. Diese Methode kann täuschen, denn die Ursache könnte auch der Placebo-Effekt sein, oder die Kopfschmerzen wären von allein weggegangen. Die Frage lädt dazu ein, solche Alternativen zu bedenken und nach einem verlässlicheren Test zu suchen, ohne dass jemand „falsch“ gesagt bekommt. Die anderen drei Fragen greifen die Person oder das Ergebnis an: Sie stellen den Gesprächspartner als leichtgläubig dar, halten ihm Studien vor oder verweisen auf die Ablehnung durch Fachleute. Damit untersuchen sie nicht, wie er zu seiner Sicherheit gekommen ist.","coreRule":"⚡ Untersuche das Verfahren, nicht die Schlussfolgerung: Frag, wie jemand etwas weiß und ob dieser Weg verlässlich ist.","quote":"","quoteLabel":"","scenario":"","beleg":"Werkstück H.2.2, Geschichte (Ansatz A/B), Struktur der Methode Schritte 4 und 5; Fußnote gl-h-4 (Boghossian 2013)","kurz":"Die Frage nach einem verlässlichen Test lenkt den Blick auf den Weg zur Sicherheit, die Einzelerfahrung. Sie lädt dazu ein, Alternativen wie Placebo oder von selbst vergehende Kopfschmerzen zu bedenken. Ein direkter Angriff löst dagegen meist Abwehr aus.","prueffrage":"Worauf stützt dein Kollege seine Sicherheit: auf Studien, auf das Urteil von Fachleuten oder auf ein eigenes Erlebnis?","rueckmeldung":[{"option":1,"text":"Nach den Gründen für eine Überzeugung zu fragen, ist an sich hilfreich. Mit „leichtgläubig“ wird die Frage aber zum Vorwurf, und wer sich bloßgestellt fühlt, verteidigt meist die Überzeugung, statt sie zu prüfen."},{"option":2,"text":"Nach Belegen zu fragen klingt sachlich, trifft aber nicht seinen Weg: Er stützt sich auf eigene Erfahrung, nicht auf Studien. Gegenbefunde vorzuhalten erzeugt außerdem eher Verteidigung, als dass er sein Verfahren selbst anschaut."},{"option":3,"text":"Dass Fachleute Heilkristalle weitgehend ablehnen, stimmt, ersetzt aber keine eigene Prüfung. Wer so gefragt wird, fühlt sich meist angegriffen und rechtfertigt sich, statt zu überlegen, wie verlässlich seine Erfahrung als Beleg ist."}],"familie":"nach-weg-und-kriterium-fragen","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Street Epistemology International: What Is Street Epistemology? A Beginner's Introduction (12.04.2026)","oeffentlich":true,"url":"https://www.streetepistemology.com/blog/nb-m01-what-is-street-epistemology","abruf":"2026-10-12"},{"typ":"url","kurz":"Street Epistemology International: Using a Confidence Scale in Street Epistemology (31.05.2026)","oeffentlich":true,"url":"https://www.streetepistemology.com/blog/nb-m08-using-a-confidence-scale-in-street-epistemology","abruf":"2026-10-12"},{"typ":"url","kurz":"Lewandowsky & Cook (2020): The Conspiracy Theory Handbook (Skeptical Science)","oeffentlich":true,"url":"https://skepticalscience.com/docs/ConspiracyTheoryHandbook.pdf","seite":"10","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"d3d480f3d22088b8"}}]`);export{t as n,n as t};